  function setVerifiedDob(dob) {
    const d = (dob || '').trim();
    if (d) {
      const ym = d.match(/\b(19\d{2}|20\d{2})\b/);
      if (!ym) {
        return; // Từ chối ngày sinh rác/thiếu năm như '1506'
      }
    }
    activeVerifiedDob = d;
    try {
      if (typeof document !== 'undefined' && document.documentElement) {
        // Có ngày sinh mới (Cổng/QR/hồ sơ HIS) hoặc reset form -> bỏ cờ "người dùng tự nhập"
        delete document.documentElement.dataset.bhytUserDob;
        if (activeVerifiedDob) {
          document.documentElement.dataset.verifiedDob = activeVerifiedDob;
        } else {
          delete document.documentElement.dataset.verifiedDob;
        }
      }
      if (activeVerifiedDob) {
        window.dispatchEvent(new CustomEvent('bhyt_verified_dob', { detail: { dob: activeVerifiedDob } }));
      }
    } catch (e) {}
  }
  // Người dùng đang tự nhập ô Ngày sinh -> extension không được ghi đè ô này nữa.
  // Cờ lưu trên <html data-bhyt-user-dob> để cả interceptor.js (MAIN world) cùng đọc được.
  function isUserEditingDob() {
    try {
      if (document.documentElement?.dataset?.bhytUserDob === '1') return true;
      // Con trỏ đang nằm trong ô Ngày sinh -> người dùng đang thao tác, không ghi đè
      return isDobInputElement(document.activeElement);
    } catch (e) {
      return false;
    }
  }

  function isDobInputElement(t) {
    if (!t || t.nodeType !== 1 || t.tagName !== 'INPUT' || t.type === 'checkbox') return false;
    const ids = ['namsinh', 'ngaysinh', 'suatt_namsinh'];
    const id = (t.id || '').toLowerCase();
    const name = (t.name || '').toLowerCase();
    if (ids.includes(id) || ids.includes(name)) return true;
    const prev = t.closest?.('.textbox, .combo')?.previousElementSibling;
    if (prev) {
      const pid = (prev.id || '').toLowerCase();
      const pname = (prev.name || '').toLowerCase();
      if (ids.includes(pid) || ids.includes(pname)) return true;
    }
    return false;
  }

  if (!window.__bhytUserDobListenerAttached) {
    window.__bhytUserDobListenerAttached = true;
    const markUserDob = (e) => {
      if (!e.isTrusted || !isDobInputElement(e.target)) return;
      if (e.type === 'keydown') {
        // Bỏ qua phím điều hướng; chỉ tính phím làm thay đổi nội dung (số, /, Backspace, Delete...)
        const navKeys = ['Tab', 'Enter', 'Escape', 'Shift', 'Control', 'Alt', 'Meta', 'CapsLock',
          'ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End', 'PageUp', 'PageDown', 'F2'];
        if (navKeys.includes(e.key) || e.ctrlKey || e.metaKey) {
          if (!(e.ctrlKey && (e.key === 'v' || e.key === 'x'))) return;
        }
      }
      try { document.documentElement.dataset.bhytUserDob = '1'; } catch (err) {}
    };
    // Dùng cả keydown vì plugin mặt nạ ngày (inputmask) của HIS có thể chặn sự kiện input thật
    ['keydown', 'input', 'paste', 'cut', 'drop'].forEach((ev) => document.addEventListener(ev, markUserDob, true));  }

