  function checkIsCapCuu() {
    const isUrlCapCuu = window.location.href.includes('tiepnhancapcuu');
    const chk = getCapcuuCheckbox();
    if (chk && chk.checked) return true;
    return isUrlCapCuu;
  }

  function checkIsNoiTru() {
    const href = window.location.href.toLowerCase();
    if (href.includes('tiepnhannhapvien') || href.includes('nhapvien') || href.includes('noitru')) return true;
    const loaiKcbEl = document.getElementById('loaikcb') || document.getElementById('cb_loaikcb') || document.querySelector('select[name="loaikcb"]');
    if (loaiKcbEl) {
      const val = String(loaiKcbEl.value || '');
      const txt = String(loaiKcbEl.selectedOptions?.[0]?.text || '');
      if (val === '03' || val === '3' || txt.includes('Nội trú') || txt.includes('nội trú')) return true;
    }
    return false;
  }

  function checkHasGiayChuyenTuyen() {
    const chkChuyen = document.getElementById('chuyenvien') ||
                      document.getElementById('chuyentuyen') ||
                      document.getElementById('chk_chuyenvien') ||
                      document.getElementById('co_giay_chuyenvien');
    if (chkChuyen && chkChuyen.checked) return true;
    const soChuyenEl = document.getElementById('sochuyenvien') || document.getElementById('so_chuyentuyen');
    if (soChuyenEl && soChuyenEl.value && soChuyenEl.value.trim()) return true;
    return false;
  }

  function checkHasGiayHen() {
    const chkHen = document.getElementById('henkham') ||
                   document.getElementById('taikham') ||
                   document.getElementById('chk_henkham');
    if (chkHen && chkHen.checked) return true;
    const soHenEl = document.getElementById('so_henkham') || document.getElementById('sohenkham');
    if (soHenEl && soHenEl.value && soHenEl.value.trim()) return true;
    return false;
  }

  function determineTargetDoiTuongKcb(maDkbdPatient) {
    // 1. Cấp cứu: Luôn là mã 2
    if (checkIsCapCuu()) return '2';

    // 2. Chuyển tuyến: Luôn là mã 1.3
    if (checkHasGiayChuyenTuyen()) return '1.3';

    // 3. Giấy hẹn tái khám: Mã 1.5
    if (checkHasGiayHen()) return '1.5';

    const cap = String(cachedCapChuyenMon || 'Cơ bản').trim().toLowerCase();
    const isNoiTru = checkIsNoiTru();

    // Phân hệ 1: Cấp ban đầu (Trạm y tế, PKĐK...) -> Luôn dùng mã 1.2
    if (cap.includes('ban đầu') || cap.includes('ban_dau')) {
      return '1.2';
    }

    // Lấy mã CSKCB tiếp nhận của Đơn vị từ cấu hình Extension (mặc định 49008)
    const cleanCskcb = String(cachedCskcbCode || '').trim().replace(/\D/g, '').substring(0, 5);

    // Lấy mã Nơi ĐK KCB ban đầu của thẻ bệnh nhân
    let dkbd = maDkbdPatient;
    if (!dkbd) {
      const elDkbd = document.getElementById('noidangky') || document.querySelector('input[name="noidangky"]');
      if (elDkbd && elDkbd.value) dkbd = elDkbd.value;
    }
    const cleanDkbd = String(dkbd || '').trim().replace(/\D/g, '').substring(0, 5);
    const isSameDkbd = Boolean(cleanDkbd && cleanCskcb && cleanDkbd === cleanCskcb);

    // Phân hệ 2: Cấp cơ bản (BVĐKKV Quế Sơn 49008)
    if (cap.includes('cơ bản') || cap.includes('co_ban') || !cap) {
      if (isNoiTru) {
        // Tự đến KCB nội trú tại cơ sở KCB cấp cơ bản
        return '1.15';
      }
      if (isSameDkbd) {
        // Đúng nơi ĐKKCB ban đầu
        return '1.1';
      }
      // NẾU CHƯA CÓ MÃ ĐKKCB: Mặc định trả về 1.12 để tránh lỗi HIS cảnh báo nơi ĐK không trùng
      if (!cleanDkbd) {
        return '1.12';
      }
      // Khác nơi ĐKKCB ban đầu:
      const diem = (cachedDiemXepCap != null && !isNaN(Number(cachedDiemXepCap))) ? Number(cachedDiemXepCap) : 25;
      if (diem >= 50 && diem <= 70) {
        return '1.13'; // Tự đến KCB ngoại trú cơ bản đạt 50-70 điểm
      }
      return '1.12'; // Tự đến KCB ngoại trú cơ bản đạt dưới 50 điểm (Quế Sơn 25 điểm -> 1.12)
    }

    // Phân hệ 3: Cấp chuyên sâu
    if (cap.includes('chuyên sâu') || cap.includes('chuyen_sau')) {
      if (isNoiTru) return '3.2';
      if (isSameDkbd) return '1.1';
      return '1.18';
    }

    return '1.1';
  }

  function applyDoiTuongKcb(maDkbd) {
    const targetCode = determineTargetDoiTuongKcb(maDkbd);
    console.log('[BHYT Extension] Xác định Đối tượng KCB chuẩn xác:', targetCode, {
      capChuyenMon: cachedCapChuyenMon,
      diemXepCap: cachedDiemXepCap,
      cskcbCode: cachedCskcbCode,
      maDkbd: maDkbd,
      isCapCuu: checkIsCapCuu(),
      isNoiTru: checkIsNoiTru()
    });

    const doituongSelect = getDoiTuongSelect();
    if (!doituongSelect || !doituongSelect.options) {
      console.log('[BHYT Extension] Không tìm thấy select Đối tượng KCB trên form');
      return;
    }

    let matchedIdx = -1;

    for (let i = 0; i < doituongSelect.options.length; i++) {
      const opt = doituongSelect.options[i];
      const val = String(opt.value || '').trim();
      const txt = String(opt.text || '').trim();

      if (targetCode === '2') {
        if (val === '2' || /^2([^\d]|$)/.test(val) || /^2([^\d]|$)/.test(txt) || txt.toLowerCase().includes('cấp cứu') || val.toLowerCase().includes('capcuu')) {
          matchedIdx = i;
          break;
        }
      } else if (targetCode === '1.12') {
        // ƯU TIÊN TUYỆT ĐỐI MÃ 1.12 (Khớp mọi định dạng 1.12, dưới 50 điểm)
        if (
          val === '1.12' ||
          val === '112' ||
          val === '01.12' ||
          val.includes('1.12') ||
          txt.includes('1.12') ||
          /^1\.12([^\d]|$)/.test(val) ||
          /^1\.12([^\d]|$)/.test(txt) ||
          txt.toLowerCase().includes('dưới 50') ||
          txt.toLowerCase().includes('duoi 50') ||
          txt.toLowerCase().includes('< 50') ||
          txt.toLowerCase().includes('<50') ||
          txt.toLowerCase().includes('dưới 50 điểm') ||
          (txt.toLowerCase().includes('ngoại trú') && txt.toLowerCase().includes('cơ bản') && !txt.includes('50-70') && !txt.includes('50 - 70'))
        ) {
          matchedIdx = i;
          break; // Tìm thấy 1.12 -> Ưu tiên tuyệt đối, dừng tìm ngay!
        }
      } else if (targetCode === '1.13') {
        if (val === '1.13' || /^1\.13([^\d]|$)/.test(val) || /^1\.13([^\d]|$)/.test(txt) || txt.includes('1.13') || txt.includes('50-70') || txt.includes('50 - 70')) {
          matchedIdx = i;
          break;
        }
      } else if (targetCode === '1.1') {
        if ((val === '1.1' || /^1\.1([^\d]|$)/.test(val) || /^1\.1([^\d]|$)/.test(txt) ||
             txt.toLowerCase().includes('đúng cơ sở kcb') || txt.toLowerCase().includes('đúng nơi đăng ký') || txt.toLowerCase().includes('đúng nơi đkkcb')) &&
            !/^1\.1[1-9]/.test(val) && !/^1\.1[1-9]/.test(txt)) {
          matchedIdx = i;
          break;
        }
      } else if (targetCode === '1.3') {
        if ((val === '1.3' || /^1\.3([^\d]|$)/.test(val) || /^1\.3([^\d]|$)/.test(txt) || txt.toLowerCase().includes('phiếu chuyển')) &&
            !/^1\.3[1-9]/.test(val) && !/^1\.3[1-9]/.test(txt)) {
          matchedIdx = i;
          break;
        }
      } else {
        if (val === targetCode || txt.startsWith(targetCode + ' ') || txt.startsWith(targetCode + '-') || txt.startsWith(targetCode + '.')) {
          matchedIdx = i;
          break;
        }
      }
    }

    // Nếu cần mã 1.12 mà trong danh mục HIS chưa có sẵn -> Chủ động tạo và thêm option 1.12 vào select (TUYỆT ĐỐI KHÔNG CHỌN 3.3)
    if (matchedIdx < 0 && targetCode === '1.12') {
      console.log('[BHYT Extension] Select chưa có option 1.12 -> Khởi tạo option 1.12 chuẩn theo QĐ 3276/QĐ-BYT');
      const opt112 = document.createElement('option');
      opt112.value = '1.12';
      opt112.text = '1.12 - Tự đến KCB ngoại trú cấp cơ bản đạt dưới 50 điểm';
      doituongSelect.appendChild(opt112);
      matchedIdx = doituongSelect.options.length - 1;
    }

    if (matchedIdx < 0) {
      for (let i = 0; i < doituongSelect.options.length; i++) {
        const opt = doituongSelect.options[i];
        const val = String(opt.value || '').trim();
        const txt = String(opt.text || '').trim();
        if (val.includes(targetCode) || txt.includes(targetCode)) {
          matchedIdx = i;
          break;
        }
      }
    }

    if (matchedIdx >= 0) {
      const selectTarget = () => {
        if (!doituongSelect.options[matchedIdx]) return;
        const isChanged = doituongSelect.selectedIndex !== matchedIdx;
        doituongSelect.selectedIndex = matchedIdx;
        doituongSelect.value = doituongSelect.options[matchedIdx].value;
        if (isChanged) {
          doituongSelect.dispatchEvent(new Event('change', { bubbles: true }));
        }

        // Đồng bộ hiển thị giao diện Select2 của HIS (nếu có)
        const optText = doituongSelect.options[matchedIdx].text;
        const s2List = [
          document.getElementById('select2-doituong-container'),
          document.getElementById('select2-cbdoituong-container'),
          doituongSelect.id ? document.getElementById(`select2-${doituongSelect.id}-container`) : null,
          doituongSelect.parentElement?.querySelector('.select2-selection__rendered'),
          doituongSelect.closest('tr, .form-group, .row, div, td')?.querySelector('.select2-selection__rendered')
        ].filter(Boolean);
        s2List.forEach((s2) => {
          s2.textContent = optText;
          s2.title = optText;
        });

        // Đồng bộ ô input hiển thị text cạnh select nếu có
        const parentContainer = doituongSelect.closest('tr, .form-group, .row, div, td');
        if (parentContainer) {
          parentContainer.querySelectorAll('input[type="text"]').forEach((inp) => {
            const iid = (inp.id || '').toLowerCase();
            const iname = (inp.name || '').toLowerCase();
            if (iid.includes('doituong') || iname.includes('doituong') || iid.includes('combo')) {
              inp.value = optText;
            }
          });
        }

        // Tô xanh trường Đối tượng KCB và Select2 theo yêu cầu
        doituongSelect.classList.add('bhyt-ext-field-success');
        doituongSelect.classList.remove('bhyt-ext-field-mismatch');
        doituongSelect.style.backgroundColor = '#ddf5dd';
        doituongSelect.style.borderColor = '#28a745';
        doituongSelect.style.color = '#0b4f1b';

        s2List.forEach((s2) => {
          s2.classList.add('bhyt-ext-field-success');
          const parentBox = s2.closest('.select2-selection, .select2-container');
          if (parentBox) {
            parentBox.classList.add('bhyt-ext-field-success');
            parentBox.style.backgroundColor = '#ddf5dd';
            parentBox.style.borderColor = '#28a745';
          }
        });

        const tbWrap = findEasyUiWrapper(doituongSelect);
        if (tbWrap) {
          tbWrap.classList.add('bhyt-ext-field-success');
          tbWrap.style.backgroundColor = '#ddf5dd';
          tbWrap.style.borderColor = '#28a745';
          tbWrap.querySelectorAll('.textbox-text, .combo-text').forEach((txt) => {
            txt.classList.add('bhyt-ext-field-success');
            txt.style.backgroundColor = '#ddf5dd';
            txt.style.borderColor = '#28a745';
            txt.style.color = '#0b4f1b';
          });
        }

        markTick(doituongSelect);
      };

      selectTarget();

      // Đảm bảo không bị các event ngầm của HIS ghi đè sau đó
      setTimeout(selectTarget, 50);
      setTimeout(selectTarget, 150);
      setTimeout(selectTarget, 300);
      setTimeout(selectTarget, 600);
      setTimeout(selectTarget, 1000);
      setTimeout(selectTarget, 1500);
      setTimeout(selectTarget, 2500);
      console.log('[BHYT Extension] Đã chọn thành công Đối tượng KCB:', doituongSelect.options[matchedIdx].text);
    } else {
      console.log('[BHYT Extension] Không tìm thấy option cho mã Đối tượng KCB:', targetCode);
    }
  }

  function init() {
    initPersistentPatientCache();
    // Dọn sạch mọi Toast nền đen nếu còn tồn tại trên DOM
    try {
      document.querySelectorAll('#bhytToastNotification, .bhyt-toast-notification, .bhyt-ext-toast').forEach(el => el.remove());
    } catch (e) {}

    // Bảo tồn kiểu chữ màu xanh lá đậm mặc định của HIS cho ô Số BHYT trên form tiếp nhận
    const sobhytEl = document.getElementById('sobhyt') || document.querySelector('input[name="sobhyt"]');
    if (sobhytEl) {
      sobhytEl.style.color = 'green';
      sobhytEl.style.fontWeight = 'bold';
    }

    const path = (window.location.pathname || '').toLowerCase();
    const href = (window.location.href || '').toLowerCase();

    // 0. BỎ QUA HOÀN TOÀN PHÂN HỆ HỒ SƠ BỆNH ÁN ĐIỆN TỬ (EMR / ho-so-benh-an-dien-tu) VÀ TẤT CẢ MODAL CỦA PHÂN HỆ NÀY:
    // Bảo toàn 100% giao diện, form và modal mặc định của VNPT HIS, tuyệt đối không can thiệp
    if (isHoSoBenhAnDienTuPage()) {
      console.log('[BHYT Extension] Bỏ qua phân hệ Hồ sơ bệnh án điện tử (EMR) theo yêu cầu, giữ nguyên 100% mặc định của HIS:', path);
      cleanExcludedModalsCheckButtons(document);
      const oldFloating = document.querySelector('.bhyt-ext-floating-right-btn, #bhytExtFloatingRightBtn');
      if (oldFloating) oldFloating.remove();
      const oldModalBtn = document.getElementById('btnCheckTheBHYT_modal');
      if (oldModalBtn) oldModalBtn.remove();
      return;
    }

    // 0. BỎ QUA HOÀN TOÀN FORM BÁO CÁO TIẾP NHẬN (baocaotiepnhan) THEO YÊU CẦU:
    // Tuyệt đối không can thiệp, giữ 100% mặc định của HIS, không chèn nút Tiếp nhận hay nút nổi
    if (isBaoCaoTiepNhanPage()) {
      console.log('[BHYT Extension] Bỏ qua form Báo cáo tiếp nhận theo yêu cầu, giữ nguyên 100% mặc định của HIS:', path);
      cleanExcludedModalsCheckButtons(document);
      const oldFloating = document.querySelector('.bhyt-ext-floating-right-btn, #bhytExtFloatingRightBtn');
      if (oldFloating) oldFloating.remove();
      const oldModalBtn = document.getElementById('btnCheckTheBHYT_modal');
      if (oldModalBtn) oldModalBtn.remove();
      return;
    }

    // Tự động đóng mọi Context Menu (chuột phải) khi click ra ngoài hoặc bấm phím Escape
    initContextMenuAutoClose(document);

    // =========================================================================
    // 0.1. FORM XUẤT DANH SÁCH GIẤY CHỨNG TỪ (xuatdsgiaychungtu):
    // Tạo button Xuất XML (XML chứng từ của từng bệnh nhân gom thành 1 file XML tổng)
    // =========================================================================
    if (isXuatDsGiayChungTuPage()) {
      console.log('[BHYT Extension] Khởi tạo chức năng Xuất XML cho trang Xuất danh sách giấy chứng từ:', path);
      initXuatDsGiayChungTu();
      return;
    }

    // 0. BỎ QUA HOÀN TOÀN TRANG KIỂM TRA BẢNG KÊ KHÔNG BHYT (kiemtrabangke_khongbhyt) THEO YÊU CẦU:
    // TUYỆT ĐỐI KHÔNG TÁC ĐỘNG ĐẾN FORM kiemtrabangke_khongbhyt, GIỮ 100% MẶC ĐỊNH CỦA HIS
    if (isKiemTraBangKeKhongBhyt()) {
      console.log('[BHYT Extension] Bỏ qua trang kiemtrabangke_khongbhyt theo yêu cầu, giữ nguyên 100% mặc định của HIS.');
      return;
    }

    // 0. BỎ QUA HOÀN TOÀN CÁC TRANG NHÂN VIÊN (vnpthis.vn/web_his/nhanvien, thongtinnhanvien, danhmucnhanvien...)
    if (path.includes('nhanvien')) {
      console.log('[BHYT Extension] Bỏ qua trang Nhân viên (không hiển thị nút Kiểm tra BHYT):', path);
      const oldFloating = document.querySelector('.bhyt-ext-floating-right-btn, #bhytExtFloatingRightBtn');
      if (oldFloating) oldFloating.remove();
      const oldModalBtn = document.getElementById('btnCheckTheBHYT_modal');
      if (oldModalBtn) oldModalBtn.remove();
      return;
    }

    // 0. BỎ QUA HOÀN TOÀN CÁC TRANG NGOÀI PHẠM VI (Báo cáo, Thống kê, Dược, Viện phí, CLS...)
    // Giúp bảo toàn 100% hiệu năng và tốc độ tải form cho các phân hệ này

    // =========================================================================
    // 1. KIỂM TRA TRANG BẢNG KÊ (kiemtrabangke, kiemtrabangkenoitru, kiemtrabangkebannt):
    // ƯU TIÊN SỐ 1 TUYỆT ĐỐI: Khởi tạo đầy đủ 100% chức năng Bảng kê
    // TUYỆT ĐỐI KHÔNG BỊ CHẶN BỞI isNoiTruPage HAY isExcludedPage
    // =========================================================================
    const isBangKeUrl = !isKiemTraBangKeKhongBhyt() && (
      path.includes('kiemtrabangke') ||
      path.includes('kiemtra_bangke') ||
      path.includes('kiemtrabangkenoitru') ||
      path.includes('kiemtrabangkebannt') ||
      path.includes('bangke') ||
      href.includes('kiemtrabangke') ||
      href.includes('kiemtra_bangke') ||
      href.includes('kiemtrabangkenoitru') ||
      href.includes('kiemtrabangkebannt') ||
      href.includes('bangke')
    );

    if (isBangKeUrl) {
      console.log('[BHYT Extension] Khởi tạo chức năng Kiểm tra BHYT cho trang Bảng kê KCB:', path);
      try {
        document.querySelectorAll('#bhytResultContainer, #bhyt_khambenh_top_result, #bhyt_khambenh_top_result_tr, #bhyt_noitru_notice_table, #bhytBangKeResultModalOverlay, #bhyt_bangke_inline_result').forEach(el => el.remove());
      } catch (_) {}
      initKiemTraBangKe();
      return;
    }

    // =========================================================================
    // 2. FORM KHÁM BỆNH NỘI TRÚ (khambenhnoitru) - CHỈ DUY NHẤT FORM KHÁM BỆNH NỘI TRÚ:
    // Hiển thị nút Kiểm tra BHYT cố định ngay dưới ô mã thẻ BHYT (#bhyt, #sobhyt...), chống nhấp nháy 100%
    // =========================================================================
    if (isNoiTruPage()) {
      console.log('[BHYT Extension] Khởi tạo chức năng cho trang Khám bệnh nội trú:', path);
      try {
        document.querySelectorAll('#bhytResultContainer, #bhyt_khambenh_top_result, #bhyt_khambenh_top_result_tr, #bhyt_noitru_notice_table, #bhytBangKeResultModalOverlay, #bhyt_bangke_inline_result').forEach(el => el.remove());
      } catch (_) {}
      setupSuattModalObserver();
      setupNoiTruPatientChangeListener();
      observeDomChanges();
      loadExtensionSettings();
      injectKhamBenhNoiTruCheckButton();
      [150, 300, 600, 1000, 1800, 3000].forEach(delay => {
        setTimeout(injectKhamBenhNoiTruCheckButton, delay);
      });
      // Watchdog nhẹ nhàng duy trì nút cố định (0ms nếu nút đã tồn tại)
      setInterval(() => {
        const btn = document.getElementById('btnKhamBenhNoiTruCheckBHYT');
        if (!btn || !btn.isConnected) {
          injectKhamBenhNoiTruCheckButton();
        }
      }, 1500);
      return;
    }

    // =========================================================================
    // 2.1 FORM KHÁM BỆNH BỆNH ÁN NGOẠI TRÚ (khambenhBANT):
    // Gắn nút Kiểm tra BHYT đặt dưới ô #bhyt và hỗ trợ modal Sửa thông tin bệnh nhân (#suatt_sobhyt, ui-id-30)
    // =========================================================================
    if (isKhambenhBantPage()) {
      console.log('[BHYT Extension] Khởi tạo chức năng cho trang Khám bệnh Bệnh án ngoại trú (khambenhBANT):', path);
      initKhambenhBant();
      return;
    }

    // =========================================================================
    // 2.2 FORM KHÁM BỆNH CẤP CỨU & NGOẠI TRÚ (khambenhcapcuu, khambenhngoaitru, khambenhngoaitrutraingay):
    // Gắn nút Kiểm tra BHYT đặt cố định dưới ô mã thẻ BHYT (#bhyt, #sobhyt...) và hỗ trợ modal
    // =========================================================================
    if (isKhamBenhGeneralPage()) {
      console.log('[BHYT Extension] Khởi tạo chức năng cho trang Khám bệnh (Cấp cứu / Ngoại trú):', path);
      initKhamBenhGeneral();
      return;
    }

    // =========================================================================
    // 3. BỎ QUA HOÀN TOÀN CÁC TRANG NGOÀI PHẠM VI (Báo cáo, Thống kê, Dược, Viện phí, CLS, SmartCA, Ký số...)
    // Yêu cầu: Giữ nguyên 100% theo mặc định của HIS, tiện ích tuyệt đối không can thiệp SmartCA
    // =========================================================================
    const isExcludedPage =
      isHoSoBenhAnDienTuPage() ||
      path.includes('baocao') ||
      path.includes('thongke') ||
      path.includes('vienphi') ||
      path.includes('duoc') ||
      path.includes('khoaduoc') ||
      path.includes('cls') ||
      path.includes('canlamsang') ||
      path.includes('nhanvien') ||
      path.includes('hethong') ||
      path.includes('quantri') ||
      path.includes('smartca') || href.includes('smartca') ||
      path.includes('kyso') || href.includes('kyso') ||
      path.includes('chuky') || href.includes('chuky') ||
      path.includes('casign') || href.includes('casign') ||
      path.includes('vnptca') || href.includes('vnptca');

    if (isExcludedPage) {
      console.log('[BHYT Extension] Bỏ qua trang (giữ nguyên mặc định HIS theo yêu cầu):', path);
      const oldFloating = document.querySelector('.bhyt-ext-floating-right-btn, #bhytExtFloatingRightBtn');
      if (oldFloating) oldFloating.remove();
      const oldModalBtn = document.getElementById('btnCheckTheBHYT_modal');
      if (oldModalBtn) oldModalBtn.remove();
      return;
    }

    // Tải cấu hình & kích hoạt theo dõi modal trên các trang nghiệp vụ
    loadExtensionSettings();
    setupSuattModalObserver();

    // 3. KIỂM TRA TRANG THÔNG TIN HÀNH CHÍNH (nếu mở trong tab riêng hoặc popup độc lập):
    const isHanhChinhUrl =
      path.includes('thongtinhanhchinh') ||
      path.includes('thongtin_hanhchinh') ||
      path.includes('suathongtin') ||
      path.includes('hanhchinh');

    if (isHanhChinhUrl) {
      console.log('[BHYT Extension] Khởi tạo chức năng cho trang Thông tin hành chính:', path);
      return;
    }

    const isTiepNhanUrl =
      path.includes('tiepnhan') ||
      path.includes('tiep_nhan') ||
      path.includes('tiep-nhan') ||
      path.includes('tiepdon');

    if (!isTiepNhanUrl) {
      console.log('[BHYT Extension] Không phải form tiếp nhận bệnh nhân -> Không hiển thị nút ở giữa bên phải.');
      const oldFloating = document.querySelector('.bhyt-ext-floating-right-btn, #bhytExtFloatingRightBtn');
      if (oldFloating) oldFloating.remove();
      return;
    }

    // Dọn dẹp toolbar cán bộ cũ nếu có
    const oldBar = document.getElementById('bhytExtStaffToolbar');
    if (oldBar) oldBar.remove();
    localStorage.removeItem('hoTenCb');
    localStorage.removeItem('cccdCb');

    injectMainWorldInterceptors();
    loadExtensionSettings();
    autoDetectStaffInfo();
    setupGlobalQrScannerListener();
    setupFormListeners();
    interceptExistingCheckButtons();
    ensureSuaCccdButton();
    setupCccdEnableGuard();
    keepCccdEnabled();
    injectInlineCheckButton();
    injectFloatingRightButton();
    ensureSobhytCounter();
    setupResetListeners();
    observeDomChanges();
    applyCapcuuRuleByUrl();
    syncQuocTich('01');

    // Lắng nghe sự kiện trigger check từ Main World Interceptor (khi bấm Enter hoặc click nút Kiểm tra BHYT)
    const handleTriggerCheckFromInterceptor = async (e) => {
      console.log('[BHYT Extension] Nhận sự kiện trigger check từ Interceptor:', e.detail);
      const field = String(e.detail?.field || '').toLowerCase();
      const rawVal = String(e.detail?.value || '').trim();

      const cccdEl = getCccdInput();
      const currentCccdVal = (rawVal || cccdEl?.value || '').trim();

      // 1. ƯU TIÊN SỐ 1: BẤT KỂ SỰ KIỆN TỪ ĐÂU, NẾU CHỨA MÃ QR (CÓ DẤU '|') HOẶC CỜ isQr
      if (rawVal.includes('|') || currentCccdVal.includes('|') || e.detail?.isQr) {
        const qrVal = rawVal.includes('|') ? rawVal : (currentCccdVal.includes('|') ? currentCccdVal : rawVal);
        clearTimeout(qrScanDebounceTimer);
        const targetInput = (field && field !== 'global_scanner') ? (document.getElementById(field) || cccdEl) : cccdEl;
        handleQrScan(qrVal, targetInput);
        return;
      }

      // Nếu sự kiện xuất phát từ ô CCCD hoặc có chuỗi 12 số
      if (field.includes('socmt') || field.includes('cccd') || field.includes('cmt') || field.includes('cmnd') || /^\d{12}$/.test(currentCccdVal)) {
        const digitsOnly = currentCccdVal.replace(/\D/g, '');
        if (digitsOnly.length === 12) {
          lastCheckedCccd = digitsOnly;
          updateCccdCounter(digitsOnly);
          syncQuocTich('01');
          applyCapcuuRuleByUrl();

          triggerBhytCheckFromForm();
          return;
        } else if (currentCccdVal) {
          triggerBhytCheckFromForm();
          return;
        }
      }

      // Nếu xuất phát từ ô Thẻ BHYT
      if (field.includes('sobhyt')) {
        const sobhytEl = document.getElementById('sobhyt');
        const bhytVal = (rawVal || sobhytEl?.value || '').trim();
        if (bhytVal.includes('|') || e.detail?.isQr) {
          clearTimeout(qrScanDebounceTimer);
          handleQrScan(bhytVal, sobhytEl);
          return;
        }
        triggerBhytCheckFromForm();
        return;
      }

      // Nếu xuất phát từ ô Mã y tế
      if (field.includes('mayte')) {
        triggerBhytCheckFromForm();
        return;
      }

      triggerBhytCheckFromForm();
    };

    window.addEventListener('bhyt-ext-trigger-check', handleTriggerCheckFromInterceptor);
  }

  // =========================================================================
  // 1. TÌM VÀ LẮNG NGHE TOÀN DIỆN CÁC Ô NHẬP LIỆU (CCCD, SỐ BHYT, NĂM SINH)
  // =========================================================================
  function getCccdInput() {
    const candidates = document.querySelectorAll('#socmt, #so_cccd, #socccd, #cccd, input[name="socmt"], input[name="cccd"], input[name="so_cccd"], input[name="socccd"], #txt_socmt, #txt_cccd');
    for (const el of candidates) {
      if (!el.closest('.window, .panel.window, .ui-dialog, .modal, [role="dialog"], #suattModal')) {
        return el;
      }
    }
    const labels = document.querySelectorAll('label, span, td, b');
    for (const l of labels) {
      const txt = (l.textContent || '').trim().toLowerCase();
      if (txt === 'cmt/cccd' || txt === 'cccd' || txt === 'cmnd/cccd' || txt.includes('cmt/cccd')) {
        const inp = l.querySelector?.('input:not([type="button"]):not([type="hidden"])') ||
                    l.nextElementSibling?.querySelector?.('input:not([type="button"]):not([type="hidden"])') ||
                    (l.nextElementSibling?.tagName === 'INPUT' ? l.nextElementSibling : null);
        if (inp && !inp.closest('.window, .panel.window, .ui-dialog, .modal, [role="dialog"], #suattModal')) {
          return inp;
        }
      }
    }
    return null;
  }

  // Tự động focus con trỏ đặt tại ô CMT/CCCD khi tiếp nhận lượt mới (bấm Thêm / phím tắt F2)
  // Chỉ thực hiện khi người dùng đang trong phiên tiếp nhận mới và ô CCCD chưa bị khóa
  // Tuyệt đối KHÔNG bôi đen (select) và KHÔNG cướp tiêu điểm nếu người dùng đã bấm sang ô khác
  function focusCccdInput() {
    if (!isTiepNhanPage()) return false;
    if (window.__bhytIsViewingLichSuKham || isLichSuKhamModalOpen()) return false;
    if (!isUserInTiepNhanThemMoi || isCccdLockedAfterCheck) return false;

    const cccdEl = getCccdInput() || document.getElementById('socmt') || document.querySelector('input[name="socmt"]');
    if (!cccdEl) return false;

    // Đảm bảo mở khóa ô CCCD trước khi đặt tiêu điểm
    unlockCccdInput();

    const tb = (typeof findEasyUiWrapper === 'function') ? findEasyUiWrapper(cccdEl) : null;
    const txt = tb ? tb.querySelector('.textbox-text') : null;
    const targetEl = txt || cccdEl;

    // Kiểm tra xem tiêu điểm hiện tại có đang ở ô BHYT (do VNPT HIS tự động đặt khi bấm Thêm) không
    const sobhytEl = document.getElementById('sobhyt') || document.querySelector('input[name="sobhyt"]');
    const sobhytWrapper = sobhytEl && (typeof findEasyUiWrapper === 'function') ? findEasyUiWrapper(sobhytEl) : null;
    const active = document.activeElement;
    const isSobhytActive = Boolean(
      active && (
        active === sobhytEl ||
        active.id === 'sobhyt' ||
        active.name === 'sobhyt' ||
        (sobhytWrapper && (active === sobhytWrapper || sobhytWrapper.contains(active)))
      )
    );

    // BẢO VỆ CON TRỎ: Nếu người dùng đã chủ động bấm sang ô khác (Họ tên, SĐT, Ngày sinh, v.v.), không cướp tiêu điểm!
    // Nhưng nếu tiêu điểm đang ở body, ở nút Thêm, hoặc ở chính ô sobhyt (do VNPT HIS tự động focus sau khi bấm Thêm), tiếp tục đưa con trỏ về ô CCCD!
    if (active && active !== document.body && active !== targetEl && active !== cccdEl && !isSobhytActive) {
      const activeTag = (active.tagName || '').toUpperCase();
      if (activeTag === 'INPUT' || activeTag === 'TEXTAREA' || activeTag === 'SELECT' || active.isContentEditable) {
        return false;
      }
    }

    try {
      cccdEl.removeAttribute('disabled');
      cccdEl.disabled = false;
      cccdEl.readOnly = false;
      if (typeof cccdEl.focus === 'function') {
        cccdEl.focus();
        const len = cccdEl.value ? cccdEl.value.length : 0;
        if (typeof cccdEl.setSelectionRange === 'function') {
          cccdEl.setSelectionRange(len, len); // Đặt con trỏ ở cuối chuỗi, TUYỆT ĐỐI KHÔNG BÔI ĐEN
        }
      }
      if (targetEl && targetEl !== cccdEl) {
        targetEl.removeAttribute('disabled');
        targetEl.disabled = false;
        targetEl.readOnly = false;
        if (typeof targetEl.focus === 'function') {
          targetEl.focus();
          const len = targetEl.value ? targetEl.value.length : 0;
          if (typeof targetEl.setSelectionRange === 'function') {
            targetEl.setSelectionRange(len, len);
          }
        }
      }
      if (window.$ && typeof window.$(cccdEl).textbox === 'function') {
        try { window.$(cccdEl).textbox('textbox').focus(); } catch (e) {}
      }
      return true;
    } catch (err) {
      console.warn('[BHYT Extension] focusCccdInput catch:', err);
    }
    return false;
  }

  function triggerFocusCccdAfterAdd() {
    // GIỮ NGUYÊN CHỨC NĂNG THEO YÊU CẦU: Khi bấm nút "Thêm", tự động mở khóa và auto focus con trỏ đặt tại ô CMT/CCCD (#socmt)
    // để sẵn sàng quét mã QR CCCD ngay tức thì qua máy quét mã vạch mà không cần dùng chuột bấm vào ô.
    [50, 150, 300, 500, 800, 1200].forEach((delay) => {
      setTimeout(() => {
        if (isUserInTiepNhanThemMoi && !isCccdLockedAfterCheck) {
          unlockCccdInput();
          focusCccdInput();
        }
      }, delay);
    });
  }

  // Kiểm tra chính xác thông báo lỗi Cổng BHXH hoặc cảnh báo số BHYT đã sử dụng từ HIS
  function isHisGatewayError(text) {
    if (!text) return false;
    const str = String(text).toLowerCase();
    if (str.includes('số bhyt đã sử dụng') || str.includes('nhấn lại nút te, pv') || str.includes('nhập lại số bhyt khác') || str.includes('bảo hiểm pvi')) {
      return true;
    }
    const hasGateway = str.includes('cổng bhxh') || str.includes('cổng tiếp nhận');
    const hasError =
      str.includes('lỗi') ||
      str.includes('không trả về dữ liệu') ||
      str.includes('liên hệ bộ phận cntt') ||
      str.includes('thất bại') ||
      str.includes('không lấy được dữ liệu');
    return hasGateway && hasError;
  }

  // Cập nhật huy hiệu đếm số CCCD nhập tay theo thời gian thực nhỏ gọn (0/12, 1..11/12, 12/12, >12)
  function updateCccdCounter(val) {
    const counterEl = document.getElementById('bhytExtCccdCounter');
    if (!counterEl) return;

    const s = String(val || '').trim();
    if (s.includes('|')) {
      counterEl.className = 'bhyt-cccd-counter badge-success';
      counterEl.textContent = 'QR';
      counterEl.title = 'Đã quét mã QR CCCD hợp lệ';
      return;
    }

    const digitsOnly = s.replace(/\D/g, '');
    const len = digitsOnly.length;

    if (len === 0) {
      counterEl.className = 'bhyt-cccd-counter badge-neutral';
      counterEl.textContent = '0/12';
      counterEl.title = 'Chưa nhập số CCCD (chuẩn 12 số)';
    } else if (len < 12) {
      counterEl.className = 'bhyt-cccd-counter badge-warning';
      counterEl.textContent = `${len}/12`;
      counterEl.title = `Đã nhập ${len}/12 số CCCD (còn thiếu ${12 - len} số)`;
    } else if (len === 12) {
      counterEl.className = 'bhyt-cccd-counter badge-success';
      counterEl.textContent = '12/12';
      counterEl.title = 'Đã nhập đúng chuẩn 12/12 số CCCD';
    } else {
      counterEl.className = 'bhyt-cccd-counter badge-danger';
      counterEl.textContent = `${len}/12`;
      counterEl.title = `Đã nhập ${len} số (thừa ${len - 12} số CCCD)`;
    }
  }

  // Cập nhật huy hiệu đếm số ký tự Số BHYT trên form tiếp nhận (0/15, 1..9/10, 10/10, 11..14/15, 15/15, 16/17, 17/17, >17)
  function updateSobhytCounter(val) {
    const counterEl = document.getElementById('bhytExtSobhytCounter');
    if (!counterEl) return;

    const s = String(val || '').trim().replace(/\s+/g, '');
    if (s.includes('|')) {
      counterEl.className = 'bhyt-sobhyt-counter badge-success';
      counterEl.textContent = 'QR';
      counterEl.title = 'Đã quét mã QR thẻ BHYT hợp lệ';
      return;
    }

    const len = s.length;
    if (len === 0) {
      counterEl.className = 'bhyt-sobhyt-counter badge-neutral';
      counterEl.textContent = '0/15';
      counterEl.title = 'Chưa nhập số thẻ BHYT (chuẩn 10 số BHXH, 15 ký tự thẻ truyền thống hoặc 17 ký tự thẻ mới)';
    } else if (len === 10) {
      counterEl.className = 'bhyt-sobhyt-counter badge-success';
      counterEl.textContent = '10/10';
      counterEl.title = 'Đã nhập đúng chuẩn 10 số BHXH';
    } else if (len === 15) {
      counterEl.className = 'bhyt-sobhyt-counter badge-success';
      counterEl.textContent = '15/15';
      counterEl.title = 'Đã nhập đúng chuẩn thẻ BHYT 15 ký tự (truyền thống)';
    } else if (len === 17) {
      counterEl.className = 'bhyt-sobhyt-counter badge-success';
      counterEl.textContent = '17/17';
      counterEl.title = 'Đã nhập đúng chuẩn thẻ BHYT mới 17 ký tự (theo số CCCD/ĐDCN)';
    } else if (len < 10) {
      counterEl.className = 'bhyt-sobhyt-counter badge-warning';
      counterEl.textContent = `${len}/10`;
      counterEl.title = `Đã nhập ${len} ký tự (còn thiếu ${10 - len} số để đủ 10 số BHXH)`;
    } else if (len < 15) {
      counterEl.className = 'bhyt-sobhyt-counter badge-warning';
      counterEl.textContent = `${len}/15`;
      counterEl.title = `Đã nhập ${len} ký tự (còn thiếu ${15 - len} ký tự để đủ thẻ 15 ký tự)`;
    } else if (len === 16) {
      counterEl.className = 'bhyt-sobhyt-counter badge-warning';
      counterEl.textContent = '16/17';
      counterEl.title = 'Đã nhập 16 ký tự (còn thiếu 1 ký tự để đủ thẻ BHYT mới 17 ký tự)';
    } else {
      counterEl.className = 'bhyt-sobhyt-counter badge-danger';
      counterEl.textContent = `${len}/17`;
      counterEl.title = `Đã nhập ${len} ký tự (thừa ${len - 17} ký tự so với chuẩn 17 ký tự)`;
    }
  }

  // Đảm bảo huy hiệu đếm ký tự được gắn vào ngay cạnh ô Số BHYT (#sobhyt / name="sobhyt")
  function ensureSobhytCounter() {
    const sobhytEl = document.getElementById('sobhyt') || document.querySelector('input[name="sobhyt"]');
    if (!sobhytEl) return;

    let counterEl = document.getElementById('bhytExtSobhytCounter');
    if (!counterEl) {
      counterEl = document.createElement('span');
      counterEl.id = 'bhytExtSobhytCounter';
      counterEl.className = 'bhyt-sobhyt-counter badge-neutral';
      counterEl.title = 'Đếm số ký tự thẻ BHYT (chuẩn 10 số hoặc 15 ký tự)';
      counterEl.textContent = '0/15';

      const tbWrapper = (typeof findEasyUiWrapper === 'function') ? findEasyUiWrapper(sobhytEl) : null;
      const targetAnchor = tbWrapper || sobhytEl;

      if (targetAnchor.nextElementSibling) {
        targetAnchor.parentElement.insertBefore(counterEl, targetAnchor.nextElementSibling);
      } else if (targetAnchor.parentElement) {
        targetAnchor.parentElement.appendChild(counterEl);
      }
    }

    const tbWrapper = (typeof findEasyUiWrapper === 'function') ? findEasyUiWrapper(sobhytEl) : null;
    const txtInp = tbWrapper ? tbWrapper.querySelector('.textbox-text') : null;
    const curVal = (txtInp ? txtInp.value : sobhytEl.value || '').trim();
    updateSobhytCounter(curVal);
  }

  let currentHisPatient = null;
  let currentBhytCardData = null;
  let userForcedNewBhytCard = false;
  let lastCheckedMaThe = '';
  let isCccdLockedAfterCheck = false;
  let isUserInTiepNhanThemMoi = false;

  // Tính tuổi chính xác từ ngày sinh
  function calculateAge(dobStr) {
    if (!dobStr) return null;
    const s = String(dobStr).trim();
    let d = 1, m = 1, y = 0;

    if (/^\d{2}\/\d{2}\/\d{4}$/.test(s)) {
      d = parseInt(s.substring(0, 2), 10);
      m = parseInt(s.substring(3, 5), 10);
      y = parseInt(s.substring(6, 10), 10);
    } else if (/^\d{8}$/.test(s)) {
      const p1 = parseInt(s.substring(0, 4), 10);
      const p2 = parseInt(s.substring(4, 8), 10);
      if (p2 >= 1900 && p2 <= 2100) {
        d = parseInt(s.substring(0, 2), 10);
        m = parseInt(s.substring(2, 4), 10);
        y = p2;
      } else if (p1 >= 1900 && p1 <= 2100) {
        y = p1;
        m = parseInt(s.substring(4, 6), 10);
        d = parseInt(s.substring(6, 8), 10);
      } else {
        d = parseInt(s.substring(0, 2), 10);
        m = parseInt(s.substring(2, 4), 10);
        y = p2;
      }
    } else if (/^\d{4}$/.test(s)) {
      y = parseInt(s, 10);
    } else if (/^\d{4}-\d{2}-\d{2}/.test(s)) {
      y = parseInt(s.substring(0, 4), 10);
      m = parseInt(s.substring(5, 7), 10);
      d = parseInt(s.substring(8, 10), 10);
    }

    if (y < 1900 || y > 2100) return null;

    const now = new Date();
    const currentYear = now.getFullYear();
    const currentMonth = now.getMonth() + 1;
    const currentDay = now.getDate();

    let tuoi = currentYear - y;
    if (currentMonth < m || (currentMonth === m && currentDay < d)) {
      tuoi--;
    }
    if (tuoi < 0) tuoi = 0;

    let thang = 0;
    let ngay = 0;
    if (tuoi < 6) {
      thang = (currentYear - y) * 12 + (currentMonth - m);
      if (currentDay < d) thang--;
      if (thang < 0) thang = 0;

      const lastMonthDate = new Date(currentYear, currentMonth - 1, 0).getDate();
      ngay = currentDay >= d ? (currentDay - d) : (lastMonthDate - d + currentDay);
      if (ngay < 1) ngay = 1;
    }

    return { tuoi, thang, ngay, isUnder6: (currentYear - y) < 6 };
  }

  // Chọn option cho select một cách chắc chắn và đồng bộ Select2 (nếu có)
  function setSelectValue(selectEl, val) {
    if (!selectEl || val === undefined || val === null) return;
    const sVal = String(val).trim();
    if (!sVal) return;

    selectEl.value = sVal;
    // Nếu select chưa ăn giá trị, quét tìm theo value hoặc text
    if (selectEl.selectedIndex < 0 || selectEl.value !== sVal) {
      for (let i = 0; i < selectEl.options.length; i++) {
        const opt = selectEl.options[i];
        if (
          opt.value === sVal ||
          parseInt(opt.value, 10) === parseInt(sVal, 10) ||
          opt.text.trim().startsWith(sVal) ||
          opt.text.toLowerCase().includes(sVal.toLowerCase())
        ) {
          selectEl.selectedIndex = i;
          break;
        }
      }
    }
    selectEl.dispatchEvent(new Event('change', { bubbles: true }));

    // Cập nhật giao diện Select2 container của HIS
    if (selectEl.id) {
      const s2Container = document.getElementById(`select2-${selectEl.id}-container`);
      if (s2Container && selectEl.selectedOptions?.[0]) {
        s2Container.textContent = selectEl.selectedOptions[0].text;
        s2Container.title = selectEl.selectedOptions[0].text;
      }
    }
  }

  // Bảng suy luận mã nghề theo đầu thẻ BHYT và khớp danh mục thực tế của HIS
  // Trích xuất Nghề nghiệp từ dữ liệu tiếp nhận khám trước đó trong HIS
  function extractNgheNghiepFromHis(obj) {
    if (!obj || typeof obj !== 'object') return null;
    const candidates = [
      obj.MA_NGHE_NGHIEP,
      obj.MANGHENGHIEP,
      obj.MA_NGHENGHIEP,
      obj.ma_nghe_nghiep,
      obj.manghenghiep,
      obj.NGHE_NGHIEP,
      obj.NGHENGHIEP,
      obj.nghenghiep,
      obj.MA_NN,
      obj.MANN,
      obj.ma_nn,
      obj.mann,
      obj.TEN_NGHE_NGHIEP,
      obj.TEN_NGHENGHIEP,
      obj.tennghenghiep,
      obj.TEN_NN,
      obj.ten_nn
    ];
    for (const c of candidates) {
      if (c !== undefined && c !== null) {
        const s = String(c).trim();
        if (s && s !== 'null' && s !== 'undefined' && s !== '0') return s;
      }
    }
    return null;
  }

  const DEFAULT_NN_CODE = '96331';
  const DEFAULT_NN_TEXT = 'Lao động giản đơn trong nông nghiệp, lâm nghiệp và thủy sản';

  // Danh mục mã nghề nghiệp thông dụng (hỗ trợ hai chiều: nhập mã hiển thị tên hoặc chọn tên hiển thị mã)
