  // Tìm đúng option tương ứng với mã 96331 trong danh mục select#cbnghenghiep của HIS
  function findOption96331(cbNn) {
    if (!cbNn || !cbNn.options || cbNn.options.length === 0) return null;

    // 1. Tìm option có value === '96331'
    for (let i = 0; i < cbNn.options.length; i++) {
      const opt = cbNn.options[i];
      if (String(opt.value || '').trim() === DEFAULT_NN_CODE) {
        return { code: DEFAULT_NN_CODE, optValue: opt.value, text: opt.text, index: i };
      }
    }

    // 2. Tìm option có text bắt đầu hoặc chứa '96331' (VD: "96331 - Lao động giản đơn...")
    for (let i = 0; i < cbNn.options.length; i++) {
      const opt = cbNn.options[i];
      const optTxt = String(opt.text || '').trim();
      if (optTxt.startsWith(DEFAULT_NN_CODE) || optTxt.includes(DEFAULT_NN_CODE)) {
        return { code: DEFAULT_NN_CODE, optValue: opt.value, text: opt.text, index: i };
      }
    }

    // 3. Tìm theo tên tiếng Việt "lao động giản đơn trong nông nghiệp"
    for (let i = 0; i < cbNn.options.length; i++) {
      const opt = cbNn.options[i];
      const t = (opt.text || '').toLowerCase();
      if (t.includes('lao động giản đơn') && (t.includes('nông nghiệp') || t.includes('thủy sản') || t.includes('lâm nghiệp'))) {
        return { code: DEFAULT_NN_CODE, optValue: opt.value, text: opt.text, index: i };
      }
    }

    // 4. Tìm theo cụm từ "lao động giản đơn"
    for (let i = 0; i < cbNn.options.length; i++) {
      const opt = cbNn.options[i];
      const t = (opt.text || '').toLowerCase();
      if (t.includes('lao động giản đơn')) {
        return { code: DEFAULT_NN_CODE, optValue: opt.value, text: opt.text, index: i };
      }
    }

    // 5. Tìm theo "nông nghiệp" hoặc "nông dân"
    for (let i = 0; i < cbNn.options.length; i++) {
      const opt = cbNn.options[i];
      const t = (opt.text || '').toLowerCase();
      if (t.includes('nông nghiệp') || t.includes('nông dân')) {
        return { code: DEFAULT_NN_CODE, optValue: opt.value, text: opt.text, index: i };
      }
    }

    // 6. Fallback: option hợp lệ đầu tiên khác 0
    for (let i = 0; i < cbNn.options.length; i++) {
      const opt = cbNn.options[i];
      if (opt.value && opt.value !== '0' && opt.value !== '' && opt.text && !opt.text.includes('--')) {
        return { code: DEFAULT_NN_CODE, optValue: opt.value, text: opt.text, index: i };
      }
    }

    return null;
  }

  // Khớp mã hoặc tên nghề nghiệp với danh mục select#cbnghenghiep của HIS hoặc từ điển mở rộng
  function findNgheNghiepMatch(codeOrText) {
    if (codeOrText === undefined || codeOrText === null) return null;
    const str = String(codeOrText).trim();
    if (!str || str.toLowerCase() === 'null') return null;

    const cbNn = document.getElementById('cbnghenghiep') || document.querySelector('select[name="cbnghenghiep"]');

    // 1. ĐẶC BIỆT: Hỗ trợ mã '0', '00', '00000' (Người bệnh không có hoặc chưa có nghề nghiệp: TE, HS, SV, tuổi < 18 hoặc >= 75)
    if (str === '0' || str === '00' || str === '00000') {
      if (cbNn && cbNn.options) {
        for (let i = 0; i < cbNn.options.length; i++) {
          const opt = cbNn.options[i];
          if (String(opt.value || '').trim() === '0' || String(opt.value || '').trim() === '00000') {
            return { code: '0', optValue: opt.value, text: opt.text, index: i };
          }
        }
        for (let i = 0; i < cbNn.options.length; i++) {
          const opt = cbNn.options[i];
          const t = (opt.text || '').toLowerCase();
          if (t.includes('không có hoặc chưa có') || t.includes('chưa có nghề nghiệp') || t.includes('không có nghề nghiệp')) {
            return { code: '0', optValue: opt.value, text: opt.text, index: i };
          }
        }
      }
      return { code: '0', optValue: '0', text: 'Người bệnh không có hoặc chưa có nghề nghiệp', index: -1 };
    }

    const isNumeric = /^\d+$/.test(str);
    const numVal = isNumeric ? parseInt(str, 10) : null;
    const paddedStr = (isNumeric && str.length === 1) ? ('0' + str) : str;

    // 2. Nếu cbnghenghiep đã nạp options:
    if (cbNn && cbNn.options && cbNn.options.length > 0) {
      if (isNumeric) {
        // 2a. Khớp chính xác theo opt.value
        for (let i = 0; i < cbNn.options.length; i++) {
          const opt = cbNn.options[i];
          const ov = String(opt.value || '').trim();
          if (ov === str || ov === paddedStr || (numVal !== null && parseInt(ov, 10) === numVal)) {
            return { code: str, optValue: opt.value, text: opt.text, index: i };
          }
        }
        // 2b. Khớp opt.text bắt đầu bằng mã số (Ví dụ: "01 - Cán bộ...", "96337: Lực lượng...", "03. Nông dân")
        for (let i = 0; i < cbNn.options.length; i++) {
          const opt = cbNn.options[i];
          const optTxt = (opt.text || '').trim();
          if (
            optTxt.startsWith(str + ' ') || optTxt.startsWith(str + '-') || optTxt.startsWith(str + ':') || optTxt.startsWith(str + '.') || optTxt.startsWith(str + '\t') ||
            (paddedStr !== str && (optTxt.startsWith(paddedStr + ' ') || optTxt.startsWith(paddedStr + '-') || optTxt.startsWith(paddedStr + ':') || optTxt.startsWith(paddedStr + '.')))
          ) {
            return { code: str, optValue: opt.value, text: opt.text, index: i };
          }
        }
        // 2c. Khớp mã số độc lập trong text
        for (let i = 0; i < cbNn.options.length; i++) {
          const opt = cbNn.options[i];
          const optTxt = (opt.text || '').trim();
          if (new RegExp(`(^|\\D)${str}(\\D|$)`).test(optTxt) || (paddedStr !== str && new RegExp(`(^|\\D)${paddedStr}(\\D|$)`).test(optTxt))) {
            return { code: str, optValue: opt.value, text: opt.text, index: i };
          }
        }
      }

      // 3. Nếu là chữ hoặc tìm theo tên: Khớp theo tên text trong cbnghenghiep
      const lower = str.toLowerCase();
      for (let i = 0; i < cbNn.options.length; i++) {
        const opt = cbNn.options[i];
        const optLower = (opt.text || '').toLowerCase().trim();
        if (optLower === lower || optLower.startsWith(lower + ' ') || optLower.startsWith(lower + '-')) {
          const m = /^\s*(\d+)/.exec(opt.text);
          const code = m ? m[1] : (/^\d+$/.test(opt.value) ? opt.value : str);
          return { code: code, optValue: opt.value, text: opt.text, index: i };
        }
      }

      // 4. Khớp các từ khóa nghề nghiệp thông dụng
      const aliases = [
        { keys: ['công an', 'lực lượng công an'], code: '96337' },
        { keys: ['quân đội', 'lực lượng quân đội', 'bộ đội', 'sĩ quan'], code: '96336' },
        { keys: ['chế biến thực phẩm', 'gia công gỗ', 'may mặc', 'đồ thủ công'], code: '96326' },
        { keys: ['nhân viên tổng hợp', 'bàn giấy', 'văn phòng'], code: '96311' },
        { keys: ['không có hoặc chưa có', 'chưa có nghề', 'không có nghề', 'trẻ em', 'học sinh', 'sinh viên'], code: '0' },
        { keys: ['lao động giản đơn', 'nông nghiệp', 'lâm nghiệp', 'thủy sản'], code: '96331' },
        { keys: ['nông', 'ruộng', 'rẫy', 'trồng trọt', 'chăn nuôi'], code: '03' },
        { keys: ['hưu', 'nghỉ hưu', 'mất sức'], code: '05' },
        { keys: ['công nhân', 'thợ', 'lao động'], code: '02' },
        { keys: ['công chức', 'viên chức', 'cán bộ', 'nhà nước', 'giáo viên', 'bác sĩ'], code: '01' },
        { keys: ['buôn bán', 'kinh doanh', 'thương nhân', 'bán buôn', 'bán lẻ'], code: '04' },
        { keys: ['tự do', 'nội trợ', 'nội chợ', 'làm thuê', 'ở nhà'], code: '39' }
      ];

      for (const a of aliases) {
        if (a.keys.some((k) => lower.includes(k))) {
          for (let i = 0; i < cbNn.options.length; i++) {
            const opt = cbNn.options[i];
            const optTxt = (opt.text || '').trim();
            const m = /^\s*(\d+)/.exec(optTxt);
            if (opt.value === a.code || (m && m[1] === a.code) || String(opt.value || '').trim() === a.code || parseInt(opt.value, 10) === parseInt(a.code, 10)) {
              return { code: a.code, optValue: opt.value, text: opt.text, index: i };
            }
          }
        }
      }
    }

    // 5. Nếu không có trong options của cbnghenghiep (hoặc select chưa load): Tra cứu COMMON_NN_MAP
    if (COMMON_NN_MAP[str]) {
      return { code: str, optValue: str, text: COMMON_NN_MAP[str], index: -1 };
    }
    if (paddedStr && COMMON_NN_MAP[paddedStr]) {
      return { code: paddedStr, optValue: paddedStr, text: COMMON_NN_MAP[paddedStr], index: -1 };
    }

    return null;
  }

  // Cờ ghi nhận người dùng đã tự tay chỉnh sửa nghề nghiệp trên form tiếp nhận
  // Khi cờ này = true: Tiện ích TÔN TRỌNG TUYỆT ĐỐI dữ liệu người dùng đã chọn, KHÔNG tự ý ghi đè lại trước khi Lưu!
  let isUserModifiedNgheNghiep = false;

  // Ánh xạ nghề nghiệp tự động theo độ tuổi và 2 ký tự đầu mã thẻ BHYT
  function inferNgheNghiep(cardStr, age) {
    let numAge = typeof age === 'number' ? age : parseInt(age, 10);
    if (isNaN(numAge)) {
      const formTuoi = parseInt(document.getElementById('tuoi')?.value || '', 10);
      const formDob = document.getElementById('namsinh')?.value || '';
      const calcTuoi = calculateAge(formDob)?.tuoi;
      numAge = !isNaN(formTuoi) ? formTuoi : (typeof calcTuoi === 'number' ? calcTuoi : NaN);
    }

    // 1. ƯU TIÊN SỐ 1: Bệnh nhân từ 0 tuổi đến dưới 18 tuổi (< 18) HOẶC người cao tuổi >= 75 tuổi (<input name="tuoi" id="tuoi">)
    if (!isNaN(numAge) && (numAge < 18 || numAge >= 75)) {
      return {
        code: '0',
        text: 'Người bệnh không có hoặc chưa có nghề nghiệp',
        byAge: true
      };
    }

    const prefix = String(cardStr || '').trim().toUpperCase().substring(0, 2);

    // 2. Thẻ CA: 96337 Lực lượng công an
    if (prefix === 'CA') {
      return {
        code: '96337',
        text: 'Lực lượng công an'
      };
    }

    // 3. Thẻ QN, QD: 96336 Lực lượng quân đội
    if (prefix === 'QN' || prefix === 'QD') {
      return {
        code: '96336',
        text: 'Lực lượng quân đội'
      };
    }

    // 4. Thẻ DN, DD: 96326 Thợ chế biến thực phẩm, gia công gỗ, may mặc, đồ thủ công và thợ có liên quan khác
    if (prefix === 'DN' || prefix === 'DD') {
      return {
        code: '96326',
        text: 'Thợ chế biến thực phẩm, gia công gỗ, may mặc, đồ thủ công và thợ có liên quan khác'
      };
    }

    // 5. Thẻ HC: 96311 Nhân viên tổng hợp và nhân viên làm các công việc bàn giấy
    if (prefix === 'HC') {
      return {
        code: '96311',
        text: 'Nhân viên tổng hợp và nhân viên làm các công việc bàn giấy'
      };
    }

    // 6. Thẻ TE, HS, SV: 0 Người bệnh không có hoặc chưa có nghề nghiệp
    if (prefix === 'TE' || prefix === 'HS' || prefix === 'SV') {
      return {
        code: '0',
        text: 'Người bệnh không có hoặc chưa có nghề nghiệp'
      };
    }

    // 7. Những thẻ BHYT có 2 ký tự khác với khai báo ở trên: 96331 Lao động giản đơn trong nông nghiệp, lâm nghiệp và thủy sản
    return {
      code: '96331',
      text: 'Lao động giản đơn trong nông nghiệp, lâm nghiệp và thủy sản'
    };
  }

  let isSyncingNgheNghiep = false;
  let lastSyncedNgheNghiepCode = null;

  // Gửi API HIS laymanghenghiep_4069 để đồng bộ trường ẩn nghenghiep_4069
  function sendLayMaNgheNghiep4069(code) {
    const matchedCode = String(code !== undefined && code !== null ? code : '').trim();
    if (!matchedCode || lastSyncedNgheNghiepCode === matchedCode) return;
    lastSyncedNgheNghiepCode = matchedCode;
    try {
      fetch(`${window.location.origin}/web_his/laymanghenghiep_4069`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8' },
        body: `manghenghiep=${encodeURIComponent(matchedCode)}`
      })
        .then((r) => r.text())
        .then((code4069) => {
          const el4069 = document.getElementById('nghenghiep_4069') || document.querySelector('input[name="nghenghiep_4069"]');
          if (el4069 && code4069 && code4069.trim()) {
            el4069.value = code4069.trim();
            el4069.classList.remove('bhyt-ext-field-mismatch');
            el4069.classList.add('bhyt-ext-field-success');
            markTick(el4069);
          }
        })
        .catch(() => {});
    } catch (e) {}
  }

  // Đồng bộ Nghề nghiệp (#nghenghiep & #cbnghenghiep) và cập nhật #select2-cbnghenghiep-container
  function syncNgheNghiep(codeOrText, customText = '') {
    if (isSyncingNgheNghiep) return;
    if (codeOrText === undefined || codeOrText === null) return;
    const strVal = String(codeOrText).trim();
    if (!strVal && strVal !== '0') return;

    isSyncingNgheNghiep = true;
    const targetCode = strVal;
    let matchedCode = targetCode;
    let matchedVal = targetCode;
    let matchedText = customText || COMMON_NN_MAP[targetCode] || (targetCode.length === 1 ? COMMON_NN_MAP['0' + targetCode] : '') || '';
    let match = findNgheNghiepMatch(targetCode);

    try {
      const inputNn = document.getElementById('nghenghiep') || document.querySelector('input[name="nghenghiep"]');
      const cbNn = document.getElementById('cbnghenghiep') || document.querySelector('select[name="cbnghenghiep"]');

      if (match && match.index >= 0) {
        matchedCode = match.code || targetCode;
        matchedVal = match.optValue || targetCode;
        matchedText = match.text || customText || COMMON_NN_MAP[matchedCode] || '';

        if (cbNn) {
          cbNn.selectedIndex = match.index;
          cbNn.value = matchedVal;
        }
      } else {
        // KHÔNG TỰ ĐỘNG CHUYỂN THÀNH 96331! Giữ nguyên mã người dùng nhập
        if (targetCode === '0' || targetCode === '00' || targetCode === '00000') {
          matchedCode = '0';
          matchedVal = '0';
          matchedText = customText || 'Người bệnh không có hoặc chưa có nghề nghiệp';
          if (cbNn) cbNn.value = '0';
        } else {
          matchedCode = targetCode;
          matchedVal = targetCode;
          matchedText = customText || COMMON_NN_MAP[targetCode] || (targetCode.length === 1 ? COMMON_NN_MAP['0' + targetCode] : '') || targetCode;
        }
      }

      // 1. Điền mã vào ô #nghenghiep (trực tiếp, không dispatch synthetic events để tránh loop)
      if (inputNn) {
        if (inputNn.value !== matchedCode) {
          inputNn.value = matchedCode;
        }
        inputNn.classList.remove('bhyt-ext-field-mismatch');
        inputNn.classList.add('bhyt-ext-field-success');
        markTick(inputNn);
      }

      // 2. Cập nhật select #cbnghenghiep
      if (cbNn) {
        cbNn.classList.remove('bhyt-ext-field-success', 'bhyt-ext-field-mismatch');
        cbNn.style.removeProperty('background-color');
        cbNn.style.removeProperty('border-color');
        cbNn.style.removeProperty('color');
        markTick(cbNn);
      }

      // 3. Hiển thị đúng tên nghề nghiệp trong Select2 container (#select2-cbnghenghiep-container)
      const s2Container = document.getElementById('select2-cbnghenghiep-container') || document.querySelector('[id*="select2-cbnghenghiep"]');
      let cleanName = matchedText || COMMON_NN_MAP[matchedCode] || (matchedCode.length === 1 ? COMMON_NN_MAP['0' + matchedCode] : '') || matchedCode;
      cleanName = String(cleanName || '').replace(/^\s*\d+[\s\-:.]*/, '').trim();
      if (!cleanName && COMMON_NN_MAP[matchedCode]) {
        cleanName = COMMON_NN_MAP[matchedCode];
      }
      if (s2Container && cleanName) {
        s2Container.textContent = cleanName;
        s2Container.title = cleanName;
      }

      // 4. Đồng bộ giá trị với jQuery nếu có (không trigger change để tránh xung đột)
      if (window.$) {
        try {
          const $cb = window.$('#cbnghenghiep');
          if ($cb.length && match && match.index >= 0 && $cb.val() !== matchedVal) {
            $cb.val(matchedVal);
          }
          if (inputNn && window.$('#nghenghiep').val() !== matchedCode) {
            window.$('#nghenghiep').val(matchedCode);
          }
        } catch (e) {}
      }

      // 5. Đảm bảo sau khi Select2 cập nhật lại DOM, container vẫn CHỈ CHỨA TÊN THÔI
      const enforceCleanS2Text = () => {
        const s2 = document.getElementById('select2-cbnghenghiep-container') || document.querySelector('[id*="select2-cbnghenghiep"]');
        if (s2) {
          let cur = (s2.textContent || '').trim();
          if (/^\s*\d+/.test(cur) || !cur) {
            const stripped = cur.replace(/^\s*\d+[\s\-:.]*/, '').trim() || cleanName;
            if (stripped) {
              s2.textContent = stripped;
              s2.title = stripped;
            }
          }
        }
      };
      enforceCleanS2Text();
      setTimeout(enforceCleanS2Text, 40);
      setTimeout(enforceCleanS2Text, 150);

      // 6. Nếu danh mục select đang nạp trễ (length <= 1), hẹn giờ kiểm tra lại để tìm đúng tên khi nạp xong
      if (cbNn && cbNn.options.length <= 1) {
        let retryCount = 0;
        const retryTimer = setInterval(() => {
          retryCount++;
          if (cbNn.options.length > 1 || retryCount > 8) {
            clearInterval(retryTimer);
            if (cbNn.options.length > 1) {
              const retryMatch = findNgheNghiepMatch(matchedCode);
              if (retryMatch && retryMatch.index >= 0) {
                cbNn.selectedIndex = retryMatch.index;
                cbNn.value = retryMatch.optValue;
                const rClean = String(retryMatch.text || '').replace(/^\s*\d+[\s\-:.]*/, '').trim();
                const s2 = document.getElementById('select2-cbnghenghiep-container') || document.querySelector('[id*="select2-cbnghenghiep"]');
                if (s2 && rClean) {
                  s2.textContent = rClean;
                  s2.title = rClean;
                }
              }
            }
          }
        }, 200);
      }
    } finally {
      setTimeout(() => {
        isSyncingNgheNghiep = false;
      }, 50);
    }

    // 7. Gửi laymanghenghiep_4069
    sendLayMaNgheNghiep4069(matchedCode);
  }

  // Chuẩn hóa địa danh (chuyển đ/Đ thành d, bỏ dấu tiếng Việt, chữ thường, bỏ tiền tố hành chính)
  function normalizeLocationStr(str) {
    if (!str) return '';
    return str
      .toLowerCase()
      .replace(/đ/g, 'd')
      .replace(/Đ/g, 'd')
      .replace(/^(tỉnh|thành\s*phố|tp\.?|quận|huyện|thị\s*xã|tx\.?|xã|phường|thị\s*trấn|tt\.?|thôn|ấp|tổ|khu\s*phố|kp|khóm|bản|số\s*nhà|đường|ngõ|ngách)\s+/gi, '')
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/^(tinh|thanh\s*pho|tp\.?|quan|huyen|thi\s*xa|tx\.?|xa|phuong|thi\s*tran|tt\.?|thon|ap|to|khu\s*pho|kp|khom|ban|so\s*nha|duong|ngo|ngach)\s+/gi, '')
      .replace(/[^a-z0-9]/g, '')
      .trim();
  }

  // Quy tắc tự động tích ô Cấp cứu theo URL tiếp đón
  function applyCapcuuRuleByUrl() {
    const capcuuCheck = getCapcuuCheckbox();
    if (!capcuuCheck) return;

    const pathname = window.location.pathname.toLowerCase();
    if (pathname.includes('tiepnhancapcuu')) {
      capcuuCheck.checked = true;
      capcuuCheck.dispatchEvent(new Event('change', { bubbles: true }));
      removeTick(capcuuCheck);
    }
  }

  // Đồng bộ Quốc tịch (#agg_quoc_tich, #cboagg_quoc_tich) -> Mặc định 01 - Việt Nam, giữ nguyên 100% màu sắc mặc định của HIS
  function syncQuocTich(maQuocTich = '01') {
    const code = String(maQuocTich || '01').trim();
    const inputQt = document.getElementById('agg_quoc_tich') ||
                    document.querySelector('input[name="agg_quoc_tich"]') ||
                    document.getElementById('quoctich') ||
                    document.querySelector('input[name="quoctich"]');

    const selectQt = document.getElementById('cboagg_quoc_tich') ||
                     document.querySelector('select[name="cboagg_quoc_tich"]') ||
                     document.getElementById('cbquoctich') ||
                     document.querySelector('select[name="cbquoctich"]');

    if (inputQt) {
      inputQt.value = code;
      inputQt.classList.remove('bhyt-ext-field-success', 'bhyt-ext-field-mismatch');
      inputQt.style.removeProperty('background-color');
      inputQt.style.removeProperty('border-color');
      inputQt.style.removeProperty('color');
      inputQt.dispatchEvent(new Event('input', { bubbles: true }));
      inputQt.dispatchEvent(new Event('change', { bubbles: true }));
    }

    if (selectQt) {
      setSelectValue(selectQt, code);
      selectQt.classList.remove('bhyt-ext-field-success', 'bhyt-ext-field-mismatch');
      selectQt.style.removeProperty('background-color');
      selectQt.style.removeProperty('border-color');
      selectQt.style.removeProperty('color');
      removeTick(selectQt);
      document.querySelectorAll('.bhyt-ext-tick-cboagg_quoc_tich, .bhyt-ext-tick-cbquoctich').forEach(t => t.remove());
    }
  }

  // Tìm ô Số điện thoại một cách linh hoạt (theo ID, name hoặc text nhãn của HIS)
  function findSdtInput() {
    const el = document.getElementById('sodt') ||
               document.querySelector('input[name="sodt"]') ||
               document.getElementById('so_dt') ||
               document.getElementById('sodienthoai') ||
               document.getElementById('so_dien_thoai') ||
               document.getElementById('dienthoai') ||
               document.getElementById('dien_thoai') ||
               document.getElementById('dt_benhnhan') ||
               document.getElementById('so_dt_bn') ||
               document.getElementById('sodt_bn') ||
               document.getElementById('txt_sodt') ||
               document.getElementById('txtSodt') ||
               document.getElementById('txt_dienthoai') ||
               document.getElementById('txtDienthoai') ||
               document.getElementById('txt_sodienthoai') ||
               document.getElementById('sdt') ||
               document.querySelector('input[name="so_dt"]') ||
               document.querySelector('input[name="sodienthoai"]') ||
               document.querySelector('input[name="so_dien_thoai"]') ||
               document.querySelector('input[name="dienthoai"]') ||
               document.querySelector('input[name="dien_thoai"]') ||
               document.querySelector('input[name="txt_sodt"]') ||
               document.querySelector('input[name="sdt"]') ||
               document.querySelector('input[name="sodt_bn"]');
    if (el) return el;

    const labels = document.querySelectorAll('label, span, td, div');
    for (const l of labels) {
      const txt = (l.textContent || '').trim().toLowerCase();
      if (txt === 'số đt' || txt === 'số điện thoại' || txt.startsWith('số đt') || txt === 'điện thoại' || txt === 'sđt' || txt.startsWith('sđt') || txt === 'so_dt') {
        const nextTd = l.closest('td')?.nextElementSibling;
        if (nextTd) {
          const inp = nextTd.querySelector('input[type="text"], input[type="tel"], input:not([type="checkbox"]):not([type="hidden"]):not([type="button"])');
          if (inp) return inp;
        }
        const parent = l.closest('.form-group, .row, tr, div') || l.parentElement;
        if (parent) {
          const inp = parent.querySelector('input[type="text"], input[type="tel"], input:not([type="checkbox"]):not([type="hidden"]):not([type="button"])');
          if (inp) return inp;
        }
      }
    }
    return null;
  }

  // Nhận diện phần tử thuộc cụm Miễn Cùng Chi Trả (MCCT) - Tuyệt đối không nhầm sang Ngày BH đủ 5 năm
  function isMcctField(el) {
    if (!el) return false;
    const idName = `${el.id || ''} ${el.name || ''} ${el.className || ''}`.toLowerCase();
    if (idName.includes('mcct') || idName.includes('mien_cung') || idName.includes('miencung') || idName.includes('cungchitra') || idName.includes('luyke') || idName.includes('cung_ct')) return true;

    // Kiểm tra wrapper EasyUI nếu có
    const wrap = el.closest ? el.closest('.textbox, .combo') : null;
    if (wrap && wrap.previousElementSibling) {
      const prevId = `${wrap.previousElementSibling.id || ''} ${wrap.previousElementSibling.name || ''}`.toLowerCase();
      if (prevId.includes('mcct') || prevId.includes('mien_cung') || prevId.includes('miencung') || prevId.includes('cungchitra') || prevId.includes('luyke') || prevId.includes('cung_ct')) return true;
    }

    // Kiểm tra container nhãn gần nhất
    const container = (el.closest ? el.closest('td, th, .form-group, div') : null) || el.parentElement;
    if (container) {
      const containerTxt = (container.textContent || '').toLowerCase();
      if ((containerTxt.includes('ngày mcct') || containerTxt.includes('ngay mcct') || containerTxt.includes('có mcct')) && !containerTxt.includes('đủ 5 năm')) {
        return true;
      }
    }

    const prevText = `${el.previousElementSibling?.textContent || ''} ${el.parentElement?.textContent || ''}`.toLowerCase();
    if (prevText.includes('ngày mcct') || prevText.includes('có mcct') || prevText.includes('ngay mcct') || prevText.includes('miễn cùng chi trả')) return true;
    return false;
  }

  // Tìm ô Ngày BH đủ 5 năm một cách linh hoạt (theo ID, name hoặc text nhãn của HIS)
  function find5NamInput(scope = document) {
    const root = scope || document;
    const el = (root.getElementById ? (root.getElementById('thoigian_du5namlientuc_tnhc') || root.getElementById('thoigian_du5namlientuc') || root.getElementById('ngay5nam') || root.getElementById('suatt_ngay5nam') || root.getElementById('ngay_5nam')) : null) ||
               root.querySelector?.('#ngay5nam, input[name="ngay5nam"], #suatt_ngay5nam, input[name="suatt_ngay5nam"], #sua_ngay5nam, input[name="sua_ngay5nam"], #ngay_5nam, input[name="ngay_5nam"], #ngay_5_nam, input[name="ngay_5_nam"], #suatt_ngay_5nam, #suatt_ngay_5_nam, #txt_ngay5nam, #thoigian_du5namlientuc_tnhc, input[name="thoigian_du5namlientuc_tnhc"], #thoigian_du5namlientuc, input[name="thoigian_du5namlientuc"], #ngay_bh_du_5nam, input[name="ngay_bh_du_5nam"], #suatt_thoigian_du5namlientuc, input[name="suatt_thoigian_du5namlientuc"], #suatt_ngay_bh_du_5nam, input[name="suatt_ngay_bh_du_5nam"], #suatt_ngaydu5nam, input[name="suatt_ngaydu5nam"], #suatt_du5nam, input[name="suatt_du5nam"], #ngaydu5nam, #ngay_du_5nam, #ngaydu5namlientuc, #thoigiandu5nam, #suatt_thoigian_du5nam, #sua_ngaydu5nam, #sua_du5nam, #txt_du5nam, #txt_ngaydu5nam, #thoidiem5nam, #suatt_thoidiem5nam, #nt_thoidiem_5nam_lientuc, input[name="nt_thoidiem_5nam_lientuc"], #kb_thoidiem_5nam_lientuc, input[name="kb_thoidiem_5nam_lientuc"], #thoidiem_5nam_lientuc, #suatt_thoidiem_5nam_lientuc');
    if (el && !isMcctField(el)) {
      const val = (typeof getInputValueThoroughly === 'function' ? getInputValueThoroughly(el) : (el.value || '')).trim();
      const y = parseInt(val.slice(-4), 10);
      if (!val || (isValidDateStr(val) && (isNaN(y) || (y >= 1900 && y <= 2100)))) return el;
    }

    // Quét đặc thù modal: Tìm ô input ngay cạnh nút "KT TT thẻ" hoặc link "Clear"
    const allActionEls = root.querySelectorAll?.('button, a, input[type="button"], span, div') || [];
    for (const b of allActionEls) {
      const bTxt = (b.textContent || '').trim().toLowerCase();
      if (bTxt === 'kt tt thẻ' || bTxt === 'kt tt the' || bTxt === 'kt thẻ' || bTxt === 'kttt the' || bTxt === 'kt tt the bhyt') {
        const parent = b.parentElement;
        const inp = parent?.querySelector('input:not([type="button"]):not([type="submit"]):not([type="checkbox"]):not([type="hidden"])');
        if (inp && !isMcctField(inp)) return inp;
      }
    }

    const labels = root.querySelectorAll?.('label, span, td, th, b, div') || [];
    for (const l of labels) {
      const txt = (l.textContent || '').trim().toLowerCase();
      // TUYỆT ĐỐI không lấy nếu nhãn là MCCT
      if (txt.includes('mcct') || txt.includes('miễn cùng') || txt.includes('cùng chi trả')) continue;

      const is5NamTxt = txt.includes('đủ 5 năm') || txt.includes('5 năm liên tục') || txt.includes('bh đủ 5 năm') || txt.includes('ngày 5 năm') || txt.includes('ngày bh đủ 5 năm') || txt.includes('5nam');
      if (!is5NamTxt) continue;

      let inp = l.querySelector?.('input:not([type="checkbox"]):not([type="hidden"]):not([type="button"]):not([type="submit"])') ||
                l.nextElementSibling?.querySelector?.('input:not([type="checkbox"]):not([type="hidden"]):not([type="button"]):not([type="submit"])') ||
                (l.nextElementSibling?.tagName === 'INPUT' && !['checkbox', 'hidden', 'button', 'submit'].includes(l.nextElementSibling.type) ? l.nextElementSibling : null);
      
      if (!inp && l.closest) {
        const td = l.closest('td, th');
        if (td && td.nextElementSibling) {
          inp = td.nextElementSibling.querySelector('input:not([type="checkbox"]):not([type="hidden"]):not([type="button"]):not([type="submit"])') ||
                (td.nextElementSibling.tagName === 'INPUT' ? td.nextElementSibling : null);
        }
      }

      if (inp && !isMcctField(inp)) {
        const val = (typeof getInputValueThoroughly === 'function' ? getInputValueThoroughly(inp) : (inp.value || '')).trim();
        const y = parseInt(val.slice(-4), 10);
        if (!val || (isValidDateStr(val) && (isNaN(y) || (y >= 1900 && y <= 2100)))) return inp;
      }
    }
    return null;
  }

  // Tìm ô Hạn thẻ BHYT Từ ngày một cách linh hoạt (theo ID, name hoặc text nhãn của HIS)
  
  // Tìm các ô Chuỗi nhận dạng BHYT (#chuoinhandang, #chuoinhandang_hc, #chuoind...)
  function findChuoiNhanDangInputs(scope = document) {
    const root = scope || document;
    const selectors = [
      '#chuoinhandang', 'input[name="chuoinhandang"]',
      '#chuoinhandang_hc', 'input[name="chuoinhandang_hc"]',
      '#chuoind', 'input[name="chuoind"]',
      '#chuoind_hc', 'input[name="chuoind_hc"]',
      '#txt_chuoinhandang', 'input[name="txt_chuoinhandang"]',
      '#suatt_chuoinhandang', 'input[name="suatt_chuoinhandang"]',
      '#sua_chuoinhandang', 'input[name="sua_chuoinhandang"]'
    ];
    const list = [];
    for (const sel of selectors) {
      const el = root.querySelector ? root.querySelector(sel) : document.querySelector(sel);
      if (el && !list.includes(el)) list.push(el);
    }
    return list;
  }

