  // Tìm ô Ngày MCCT (chuẩn ID của HIS: #ngay_mien_cung_ct)
  function findNgayMcctInput(scope = document) {
    const root = scope || document;
    const el = (root.getElementById ? root.getElementById('ngay_mien_cung_ct') : null) ||
               root.querySelector?.('#ngay_mien_cung_ct, #suatt_ngay_mien_cung_ct, #sua_ngay_mien_cung_ct, #suatt_ngaymcct, #suatt_ngay_mcct, #sua_ngaymcct, #ngay_mcct, #ngaymcct, #thoigian_mcct, #thoigian_miencungchitra, #ngay_miencungchitra, #ngay_cungchitra, input[name="ngay_mien_cung_ct"], input[name="suatt_ngay_mien_cung_ct"], input[name="ngay_mcct"], input[name="ngaymcct"], input[name="thoigian_mcct"]');
    if (el && isMcctField(el) && !isTreatmentTimeOrPeriodElement(el)) return el;

    // Trong hàng chứa ô #thoigian_du5namlientuc: ô text ngay trước nó là Ngày MCCT nếu thỏa mãn isMcctField
    const el5Nam = root.querySelector?.('#thoigian_du5namlientuc, #suatt_ngaydu5nam, #suatt_du5nam, #ngay_bh_du_5nam');
    if (el5Nam) {
      const row = el5Nam.closest('tr, .row, .form-group, div');
      if (row) {
        const inputs = Array.from(row.querySelectorAll('input[type="text"], input:not([type="checkbox"]):not([type="hidden"]):not([type="button"])'));
        const idx5Nam = inputs.indexOf(el5Nam);
        if (idx5Nam > 0 && isMcctField(inputs[idx5Nam - 1]) && !isTreatmentTimeOrPeriodElement(inputs[idx5Nam - 1])) {
          return inputs[idx5Nam - 1];
        }
      }
    }

    // Tìm input nằm sau text "Ngày MCCT"
    const all = root.querySelectorAll?.('label, span, td, div') || [];
    for (const l of all) {
      if (l.children.length > 2) continue;
      const txt = (l.textContent || '').trim();
      if ((txt.includes('Ngày MCCT') || txt.includes('ngay mcct')) && !txt.includes('đủ 5 năm')) {
        let inp = l.querySelector?.('input:not([type="checkbox"]):not([type="hidden"]):not([type="button"])') ||
                  l.nextElementSibling?.querySelector?.('input:not([type="checkbox"]):not([type="hidden"]):not([type="button"])') ||
                  (l.nextElementSibling?.tagName === 'INPUT' && !['checkbox', 'hidden', 'button'].includes(l.nextElementSibling.type) ? l.nextElementSibling : null);
        if (inp && isMcctField(inp) && !isTreatmentTimeOrPeriodElement(inp)) return inp;
        const parent = l.closest('tr, .form-group, .row, div') || l.parentElement;
        if (parent) {
          const inps = Array.from(parent.querySelectorAll('input[type="text"], input:not([type="checkbox"]):not([type="hidden"]):not([type="button"])')).filter(i => isMcctField(i) && !isTreatmentTimeOrPeriodElement(i));
          if (inps.length > 0) return inps[0];
        }
      }
    }

    return null;
  }

  // Tìm ô Số tiền BNCCT luỹ kế trong năm
  function findSoTienLuyKeInput(scope = document) {
    const root = scope || document;
    const el = (root.getElementById ? root.getElementById('sotien_bncctluyke') : null) ||
               root.querySelector?.('#sotien_bncctluyke, #suatt_sotien_bncctluyke, #suatt_sotien_bncct_luyke, #sotien_bncct_luyke, #sua_sotien_bncctluyke, #sotien_luyke, #tien_cungchitra_luyke, #bncct_luyke, #sotien_cungchitra, #sotien_bncct, #tien_luyke, #sotien_luyke_trongnam, #bncct_nam, input[name="sotien_bncctluyke"], input[name="suatt_sotien_bncctluyke"], input[name="sotien_bncct_luyke"], input[name="sotien_luyke"]');
    if (el && !isTreatmentTimeOrPeriodElement(el)) return el;

    // Tìm theo nhãn "Số tiền BNCCT luỹ kế" hoặc "luỹ kế trong năm"
    const all = root.querySelectorAll?.('label, span, td, div') || [];
    for (const l of all) {
      if (l.children.length > 2) continue;
      const txt = (l.textContent || '').trim();
      if (txt.includes('Số tiền BNCCT luỹ kế') || txt.includes('luỹ kế trong năm') || txt.includes('BNCCT luỹ kế')) {
        let inp = l.querySelector?.('input:not([type="checkbox"]):not([type="hidden"]):not([type="button"])') ||
                  l.nextElementSibling?.querySelector?.('input:not([type="checkbox"]):not([type="hidden"]):not([type="button"])') ||
                  (l.nextElementSibling?.tagName === 'INPUT' && !['checkbox', 'hidden', 'button'].includes(l.nextElementSibling.type) ? l.nextElementSibling : null);
        if (inp && !isTreatmentTimeOrPeriodElement(inp)) return inp;
        const parent = l.closest('tr, .form-group, .row, div') || l.parentElement;
        if (parent) {
          const inp = parent.querySelector('input[type="text"], input[type="number"], input:not([type="checkbox"]):not([type="hidden"]):not([type="button"])');
          if (inp && !isTreatmentTimeOrPeriodElement(inp)) return inp;
        }
      }
    }

    // Tìm ô input ngay trước chữ "đồng" hoặc "VNĐ" (chỉ trong ngữ cảnh số tiền / luỹ kế)
    for (const l of all) {
      const txt = (l.textContent || '').trim();
      if (txt === 'đồng' || txt === 'VNĐ') {
        const parent = l.closest('tr, .form-group, .row');
        const parentTxt = (parent?.textContent || '').toLowerCase();
        if (parentTxt.includes('luỹ kế') || parentTxt.includes('lũy kế') || parentTxt.includes('bncct') || parentTxt.includes('chi trả')) {
          const prev = l.previousElementSibling;
          if (prev && prev.tagName === 'INPUT' && !isTreatmentTimeOrPeriodElement(prev)) return prev;
          const inp = l.parentElement?.querySelector('input[type="text"], input[type="number"]');
          if (inp && !isTreatmentTimeOrPeriodElement(inp)) return inp;
        }
      }
    }

    return null;
  }

  // Tìm nút KTra MCCT
  function findKtraMcctButton() {
    const el = document.getElementById('btn_ktramcct') ||
               document.getElementById('ktra_mcct') ||
               document.getElementById('btn_ktra_mcct') ||
               document.getElementById('ktramcct') ||
               document.getElementById('btn_kiemtra_mcct') ||
               document.getElementById('kiemtra_mcct');
    if (el) return el;

    const btns = document.querySelectorAll('button, input[type="button"], a.btn, .btn');
    for (const b of btns) {
      const txt = (b.value || b.textContent || '').trim();
      if (txt.includes('KTra MCCT') || txt.includes('Kiểm tra MCCT') || txt.includes('KT MCCT')) {
        return b;
      }
    }
    return null;
  }

  // Bóc tách ngày đủ 5 năm liên tục từ chuỗi hoặc ghi chú Cổng BHXH / HIS
  function extract5NamDate(rawVal, ghiChuText = '') {
    const candidates = [rawVal, ghiChuText];
    for (const str of candidates) {
      if (!str || typeof str !== 'string') continue;
      const s = str.trim();
      if (!s || s.toLowerCase() === 'null' || s.toLowerCase() === 'undefined' || s.toLowerCase().includes('dd/mm')) continue;

      // 1. Khớp ngày trong chuỗi có chữ "5 năm"
      const m5 = s.match(/(?:đủ\s*0?5\s*năm|5\s*năm)[^\d]*?(\d{1,2}\/\d{1,2}\/\d{4}|\d{4}-\d{2}-\d{2}|\d{8})/i);
      if (m5 && m5[1]) {
        return formatBhxhDate(m5[1]);
      }

      // 2. Khớp DD/MM/YYYY chuẩn
      const mDate = s.match(/\b(\d{1,2}\/\d{1,2}\/\d{4})\b/);
      if (mDate && mDate[1]) {
        return formatBhxhDate(mDate[1]);
      }

      // 3. Khớp YYYYMMDD hoặc YYYY-MM-DD
      const mIso = s.match(/\b(\d{4}[-/]\d{2}[-/]\d{2}|\d{8})\b/);
      if (mIso && mIso[1]) {
        return formatBhxhDate(mIso[1]);
      }
    }
    return '';
  }

  // Kiểm tra trên form có thông tin thẻ BHYT hợp lệ hay không (dùng để chặn điền 5 năm khi không có BHYT)
  function hasValidBhytInfoOnForm() {
    // 1. Kiểm tra ô mã thẻ BHYT trên form tiếp nhận / form chính
    const cardInput = document.getElementById('sobhyt') || document.querySelector('input[name="sobhyt"]');
    const cardVal = (cardInput?.value || '').trim().replace(/\s+/g, '').toUpperCase();
    if (cardVal && cardVal !== '0' && cardVal.length >= 10) return true;

    // 2. Kiểm tra ô thẻ trên modal đang mở nếu có
    const modalCard = document.querySelector('#sobhyt_hc, input[name="sobhyt_hc"], #suatt_sobhyt, input[name="suatt_sobhyt"]');
    const mVal = (modalCard?.value || '').trim().replace(/\s+/g, '').toUpperCase();
    if (mVal && mVal !== '0' && mVal.length >= 10) return true;

    // 3. Kiểm tra dữ liệu thẻ BHYT hợp lệ từ Cổng tiếp nhận vừa tra cứu thành công
    if (currentBhytCardData && currentBhytCardData.maThe && currentBhytCardData.maThe !== '0') return true;
    if (window.__lastBhytVerifiedData?.data?.maThe) return true;

    return false;
  }

  // Gán ngày đủ 5 năm liên tục: Điền ngày vào ô #thoigian_du5namlientuc (chuẩn theo plugin mẫu negokffhaooinmfdcofbdbnapfoklaom)
  function apply5NamValue(d5Nam) {
    const el5Nam = find5NamInput();
    if (!el5Nam) return;

    // YÊU CẦU ĐẶC BIỆT TỪ NGƯỜI DÙNG:
    // Đối với các trường hợp KHÔNG có thông tin thẻ BHYT (đối tượng Viện phí / Thu phí, hoặc không có thẻ BHYT hợp lệ),
    // TUYỆT ĐỐI KHÔNG trả kết quả / không điền dữ liệu vào trường thoigian_du5namlientuc để không bị lỗi khi lưu form tiếp nhận!
    const hasBhyt = hasValidBhytInfoOnForm();
    if (!hasBhyt || !d5Nam) {
      const clearVal = () => {
        if (el5Nam.value && el5Nam.value !== 'dd/mm/yyyy') {
          el5Nam.value = '';
          if (window.$) {
            try { window.$(el5Nam).val(''); } catch (e) {}
          }
        }
        el5Nam.classList.remove('bhyt-ext-field-success', 'bhyt-ext-field-mismatch');
        el5Nam.style.removeProperty('background-color');
        el5Nam.style.removeProperty('border');
        el5Nam.style.removeProperty('color');
        el5Nam.style.removeProperty('-webkit-text-fill-color');
        removeTick(el5Nam);
        el5Nam.disabled = true;
        el5Nam.setAttribute('disabled', 'disabled');
        const btnSua5Nam = document.getElementById('sua_5nam');
        if (btnSua5Nam) btnSua5Nam.remove();
      };
      clearVal();
      setTimeout(clearVal, 100);
      setTimeout(clearVal, 300);
      return;
    }

    // Khi CÓ THẺ BHYT và có d5Nam hợp lệ:
    let btnSua5Nam = document.getElementById('sua_5nam');
    if (!btnSua5Nam && el5Nam.parentNode) {
      btnSua5Nam = document.createElement('input');
      btnSua5Nam.type = 'button';
      btnSua5Nam.name = 'sua_5nam';
      btnSua5Nam.id = 'sua_5nam';
      btnSua5Nam.value = 'Sửa5Nam';
      btnSua5Nam.title = 'Click vào để sửa Ngày BH đủ 5 năm';
      btnSua5Nam.className = 'button_shadow';
      btnSua5Nam.style.cssText = 'width: 75px; margin-left: 4px; padding: 2px 6px; font-size: 11px; cursor: pointer;';
      btnSua5Nam.addEventListener('click', () => {
        el5Nam.disabled = false;
        el5Nam.removeAttribute('disabled');
        el5Nam.readOnly = false;
        el5Nam.focus();
      });
      el5Nam.parentNode.insertBefore(btnSua5Nam, el5Nam.nextSibling);
    }

    const setVal = () => {
      if (!hasValidBhytInfoOnForm()) {
        el5Nam.value = '';
        el5Nam.disabled = true;
        el5Nam.setAttribute('disabled', 'disabled');
        el5Nam.classList.remove('bhyt-ext-field-success');
        removeTick(el5Nam);
        return;
      }
      el5Nam.value = d5Nam;
      if (window.$) {
        try {
          window.$(el5Nam).val(d5Nam);
        } catch (e) {}
      }
      el5Nam.classList.remove('bhyt-ext-field-mismatch');
      el5Nam.classList.add('bhyt-ext-field-success');
      el5Nam.style.setProperty('background-color', '#ddf5dd', 'important');
      el5Nam.style.setProperty('border', '1.5px solid #28a745', 'important');
      el5Nam.style.setProperty('color', '#0f5132', 'important');
      el5Nam.style.setProperty('-webkit-text-fill-color', '#0f5132', 'important');
      markTick(el5Nam);
      el5Nam.disabled = true;
      el5Nam.setAttribute('disabled', 'disabled');
    };

    setVal();
    setTimeout(setVal, 100);
    setTimeout(setVal, 300);
    setTimeout(setVal, 800);
  }

  // Xử lý Ngày MCCT, Checkbox Có MCCT và Số tiền BNCCT luỹ kế trong năm theo QĐ 188/2025/NĐ-CP
  function applyMcctAndLuyKe(ngayMcct, soTienLuyKe, scope = document) {
    const root = scope || document;
    const checkCoMcct = findCoMcctCheckbox(root);
    const elNgayMcct = findNgayMcctInput(root);
    const elLuyKe = findSoTienLuyKeInput(root);

    // 1. Cập nhật Checkbox Có MCCT (#baohiem5nam / #co_mcct):
    // Đặt .checked và .prop('checked') trực tiếp, TUYỆT ĐỐI không dispatch change event để tránh HIS xóa trắng ô #thoigian_du5namlientuc!
    if (checkCoMcct) {
      const targetChecked = Boolean(ngayMcct);
      checkCoMcct.checked = targetChecked;
      const jq = checkCoMcct.ownerDocument?.defaultView?.$ || window.$;
      if (jq) {
        try { jq(checkCoMcct).prop('checked', targetChecked); } catch (e) {}
      }
      if (targetChecked) {
        markTick(checkCoMcct);
      } else {
        removeTick(checkCoMcct);
      }
    }

    // 2. Gán giá trị các ô text
    const setValues = () => {
      // Ô Ngày MCCT (#ngay_mien_cung_ct)
      if (elNgayMcct && !isTreatmentTimeOrPeriodElement(elNgayMcct)) {
        const tbWrapper = findEasyUiWrapper(elNgayMcct);
        const txtInp = tbWrapper ? tbWrapper.querySelector('.textbox-text') : null;
        const valInp = tbWrapper ? tbWrapper.querySelector('.textbox-value') : null;

        if (ngayMcct) {
          ensureInputEditable(elNgayMcct);
          elNgayMcct.value = ngayMcct;
          if (txtInp) { ensureInputEditable(txtInp); txtInp.value = ngayMcct; }
          if (valInp) valInp.value = ngayMcct;
          const jq = elNgayMcct.ownerDocument?.defaultView?.$ || window.$;
          if (jq) {
            try { jq(elNgayMcct).val(ngayMcct); } catch (e) {}
          }
          elNgayMcct.classList.remove('bhyt-ext-field-success', 'bhyt-modal-field-filled');
          elNgayMcct.style.removeProperty('background-color');
          elNgayMcct.style.removeProperty('border-color');
          elNgayMcct.style.removeProperty('color');
          if (tbWrapper) {
            tbWrapper.classList.remove('bhyt-ext-field-success', 'bhyt-modal-field-filled');
            tbWrapper.style.removeProperty('background-color');
            tbWrapper.style.removeProperty('border-color');
          }
          removeTick(tbWrapper || elNgayMcct);
        } else {
          elNgayMcct.value = '';
          if (txtInp) txtInp.value = '';
          if (valInp) valInp.value = '';
          const jq = elNgayMcct.ownerDocument?.defaultView?.$ || window.$;
          if (jq) {
            try { jq(elNgayMcct).val(''); } catch (e) {}
          }
          elNgayMcct.classList.remove('bhyt-ext-field-success', 'bhyt-modal-field-filled');
          elNgayMcct.style.removeProperty('background-color');
          elNgayMcct.style.removeProperty('border-color');
          elNgayMcct.style.removeProperty('color');
          if (tbWrapper) {
            tbWrapper.classList.remove('bhyt-ext-field-success', 'bhyt-modal-field-filled');
            tbWrapper.style.removeProperty('background-color');
            tbWrapper.style.removeProperty('border-color');
          }
          removeTick(tbWrapper || elNgayMcct);
        }
      }

      // Ô Số tiền BNCCT luỹ kế trong năm
      if (elLuyKe && !isTreatmentTimeOrPeriodElement(elLuyKe)) {
        const tbWrapper = findEasyUiWrapper(elLuyKe);
        const txtInp = tbWrapper ? tbWrapper.querySelector('.textbox-text') : null;
        const valInp = tbWrapper ? tbWrapper.querySelector('.textbox-value') : null;
        const valStr = (soTienLuyKe != null) ? String(soTienLuyKe) : '0';

        elLuyKe.value = valStr;
        if (txtInp) { ensureInputEditable(txtInp); txtInp.value = valStr; }
        if (valInp) valInp.value = valStr;
        const jq = elLuyKe.ownerDocument?.defaultView?.$ || window.$;
        if (jq) {
          try { jq(elLuyKe).val(valStr); } catch (e) {}
        }

        elLuyKe.classList.remove('bhyt-ext-field-success', 'bhyt-modal-field-filled');
        elLuyKe.style.removeProperty('background-color');
        elLuyKe.style.removeProperty('border-color');
        elLuyKe.style.removeProperty('color');
        if (tbWrapper) {
          tbWrapper.classList.remove('bhyt-ext-field-success', 'bhyt-modal-field-filled');
          tbWrapper.style.removeProperty('background-color');
          tbWrapper.style.removeProperty('border-color');
        }
        removeTick(tbWrapper || elLuyKe);
      }
    };

    setValues();
    setTimeout(setValues, 100);
    setTimeout(setValues, 300);
    setTimeout(setValues, 800);
  }

  // Bắt sự kiện click nút KTra MCCT của HIS để gọi API TraCuuTienMCCT
  function setupKtraMcctButtonListener() {
    const btn = findKtraMcctButton();
    if (!btn || btn.dataset.bhytMcctAttached === 'true') return;
    btn.dataset.bhytMcctAttached = 'true';

    btn.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();

      const maThe = (document.getElementById('sobhyt')?.value || '').trim().toUpperCase();
      const hoTen = (document.getElementById('hoten')?.value || '').trim();
      const ngaySinh = (document.getElementById('namsinh')?.value || '').trim();

      if (!maThe) {
        alert('Vui lòng nhập Mã thẻ BHYT trước khi tra cứu tiền MCCT!');
        return;
      }

      if (!chrome || !chrome.runtime || typeof chrome.runtime.sendMessage !== 'function') {
        alert('Tiện ích vừa được tải lại. Vui lòng bấm phím F5 để làm mới trang HIS!');
        return;
      }

      console.log('[BHYT Extension] Bấm nút KTra MCCT -> Gọi API TraCuuTienMCCT:', { maThe, hoTen, ngaySinh });
      try {
        chrome.runtime.sendMessage(
          {
            action: 'traCuuTienMCCT',
            payload: {
              maThe,
              hoTen,
              ngaySinh,
              hisOrigin: window.location.origin
            }
          },
          (resp) => {
            if (resp && resp.success) {
              applyMcctAndLuyKe(resp.ngayMcct, resp.soTienLuyKe);
            } else {
              console.log('[BHYT Extension] Tra cứu tiền MCCT không thành công:', resp?.message);
            }
          }
        );
      } catch (err) {
        alert('Tiện ích vừa được tải lại. Vui lòng bấm phím F5 để làm mới trang HIS!');
      }
    }, true);
  }

  // Điền thông tin thân nhân & liên hệ (SĐT, Người LH, CMND Người LH, Họ tên cha, Họ tên mẹ, BHXH cha, BHXH mẹ)
  function applyFamilyAndContact(info) {
    if (!info) return;

    // 1. Số điện thoại (#sodt)
    const sdt = extractPatientSdt(info);
    const elSdt = findSdtInput();
    if (sdt) {
      if (elSdt) {
        elSdt.value = sdt;
        setFieldSuccess(elSdt, sdt);
        if (window.$) {
          try {
            window.$(elSdt).val(sdt).trigger('input').trigger('change');
          } catch (e) {}
        }
      }
    } else if (elSdt && elSdt.value && elSdt.value.trim()) {
      setFieldSuccess(elSdt, elSdt.value.trim());
    }

    // 2. Người liên hệ (#nguoilienhe)
    const ngLh = info.NGUOI_LIEN_HE || info.nguoilienhe || info.NGUOI_THAN || info.nguoithan || '';
    if (ngLh) {
      const elLh = document.getElementById('nguoilienhe') || document.querySelector('input[name="nguoilienhe"]') || document.getElementById('nguoithan');
      if (elLh) {
        setFieldSuccess(elLh, ngLh);
        if (window.$) {
          try { window.$(elLh).val(ngLh).trigger('input').trigger('change'); } catch (e) {}
        }
      }
    }

    // 3. CMND Người LH (#cmnd_nguoilh)
    const cmndLh = info.CMND_NGUOILH || info.cmnd_nguoilh || info.CMND_NGUOI_LIEN_HE || info.CMND_NGUOI_THAN || '';
    if (cmndLh) {
      const elCmLh = document.getElementById('cmnd_nguoilh') || document.querySelector('input[name="cmnd_nguoilh"]') || document.getElementById('cmnd_nguoithan');
      if (elCmLh) {
        setFieldSuccess(elCmLh, cmndLh);
        if (window.$) {
          try { window.$(elCmLh).val(cmndLh).trigger('input').trigger('change'); } catch (e) {}
        }
      }
    }

    // 4. Họ tên cha & Họ tên mẹ
    const tenCha = info.HO_TEN_CHA || info.ho_ten_cha || info.TEN_CHA || '';
    if (tenCha) {
      const elCha = document.getElementById('ho_ten_cha') || document.getElementById('hotencha') ||
                    document.querySelector('input[name="ho_ten_cha"]') || document.querySelector('input[name="hotencha"]') ||
                    document.getElementById('tencha') || document.getElementById('hoten_cha') ||
                    document.querySelector('input[name="tencha"]');
      if (elCha) {
        elCha.value = tenCha.toUpperCase();
        setFieldSuccess(elCha, tenCha.toUpperCase());
        if (window.$) {
          try { window.$(elCha).val(tenCha.toUpperCase()).trigger('input').trigger('change'); } catch (e) {}
        }
      }
    }
    const tenMe = info.HO_TEN_ME || info.ho_ten_me || info.TEN_ME || '';
    if (tenMe) {
      const elMe = document.getElementById('ho_ten_me') || document.getElementById('hotenme') ||
                   document.querySelector('input[name="ho_ten_me"]') || document.querySelector('input[name="hotenme"]') ||
                   document.getElementById('tenme') || document.getElementById('hoten_me') ||
                   document.querySelector('input[name="tenme"]');
      if (elMe) {
        elMe.value = tenMe.toUpperCase();
        setFieldSuccess(elMe, tenMe.toUpperCase());
        if (window.$) {
          try { window.$(elMe).val(tenMe.toUpperCase()).trigger('input').trigger('change'); } catch (e) {}
        }
      }
    }

    // 5. Mã BHXH Cha & Mẹ
    const maCha = info.MA_CHA || info.ma_bhxh_cha || info.MA_BHXH_CHA || '';
    if (maCha) {
      const elMaCha = document.getElementById('ma_bhxh_cha') || document.getElementById('mabhxh_cha') || document.querySelector('input[name="ma_bhxh_cha"]');
      if (elMaCha) setFieldSuccess(elMaCha, maCha);
    }
    const maMe = info.MA_ME || info.ma_bhxh_me || info.MA_BHXH_ME || '';
    if (maMe) {
      const elMaMe = document.getElementById('ma_bhxh_me') || document.getElementById('mabhxh_me') || document.querySelector('input[name="ma_bhxh_me"]');
      if (elMaMe) setFieldSuccess(elMaMe, maMe);
    }

    // 6. Quốc tịch
    syncQuocTich(info.MA_QUOC_TICH || '01');
  }

  function setupNghenghiepListener() {
    const inputNn = document.getElementById('nghenghiep') || document.querySelector('input[name="nghenghiep"]');
    const cbNn = document.getElementById('cbnghenghiep') || document.querySelector('select[name="cbnghenghiep"]');

    // 1. NGƯỜI DÙNG NHẬP MÃ VÀO Ô <input name="nghenghiep" id="nghenghiep"> -> HIỂN THỊ TÊN NGHỀ NGHIỆP
    if (inputNn && !inputNn._bhytUserListenerAttached) {
      inputNn._bhytUserListenerAttached = true;
      inputNn.dataset.bhytListenerAttached = 'true';

      let debounceTimer = null;
      const handleInput = () => {
        if (isSyncingNgheNghiep) return;
        const val = (inputNn.value || '').trim();
        if (val || val === '0') {
          syncNgheNghiep(val);
        }
      };

      inputNn.addEventListener('input', (e) => {
        if (!e.isTrusted) return;
        isUserModifiedNgheNghiep = true;
        console.log('[BHYT Extension] Người dùng đã tự gõ Nghề nghiệp (#nghenghiep):', inputNn.value);
        if (debounceTimer) clearTimeout(debounceTimer);
        debounceTimer = setTimeout(handleInput, 200);
      });

      inputNn.addEventListener('change', (e) => {
        if (!e.isTrusted) return;
        isUserModifiedNgheNghiep = true;
        if (debounceTimer) clearTimeout(debounceTimer);
        handleInput();
      });

      inputNn.addEventListener('blur', (e) => {
        if (!e.isTrusted) return;
        isUserModifiedNgheNghiep = true;
        if (debounceTimer) clearTimeout(debounceTimer);
        handleInput();
      });

      inputNn.addEventListener('keyup', (e) => {
        if (!e.isTrusted) return;
        isUserModifiedNgheNghiep = true;
        if (e.key === 'Enter') {
          if (debounceTimer) clearTimeout(debounceTimer);
          handleInput();
        }
      });
    }

    // Làm sạch tên nghề nghiệp hiển thị trong container Select2 (loại bỏ tiền tố mã số)
    const cleanS2JobText = () => {
      const s2 = document.getElementById('select2-cbnghenghiep-container') || document.querySelector('[id*="select2-cbnghenghiep"]');
      if (s2 && s2.textContent) {
        const cur = s2.textContent.trim();
        if (/^\s*\d+/.test(cur)) {
          const cleaned = cur.replace(/^\s*\d+[\s\-:.]*/, '').trim();
          if (cleaned) {
            s2.textContent = cleaned;
            s2.title = cleaned;
          }
        }
      }
    };

    // Hàm xử lý khi người dùng chọn một nghề nghiệp từ dropdown select hoặc Select2 -> HIỂN THỊ MÃ THEO
    const handleJobSelect = (opt, chosenVal) => {
      if (isSyncingNgheNghiep) return;
      isUserModifiedNgheNghiep = true;

      let extractedCode = '';
      let cleanJobName = '';

      if (opt) {
        const optVal = String(opt.value || '').trim();
        const optTxt = String(opt.text || '').trim();
        // 1. Thử trích xuất mã số từ đầu text (Ví dụ: "01 - Cán bộ..." -> "01", "96331: Lao động..." -> "96331", "0 - Chưa có..." -> "0")
        const m = /^\s*(\d+)/.exec(optTxt);
        if (m && m[1]) {
          extractedCode = m[1];
          cleanJobName = optTxt.replace(/^\s*\d+[\s\-:.]*/, '').trim();
        } else if (optVal && optVal !== '' && optVal !== 'null') {
          extractedCode = optVal;
          cleanJobName = optTxt;
        } else {
          // Thử tìm theo alias từ text
          const aliasMatch = findNgheNghiepMatch(optTxt);
          if (aliasMatch && aliasMatch.code) {
            extractedCode = aliasMatch.code;
            cleanJobName = optTxt;
          }
        }
      } else if (chosenVal) {
        extractedCode = String(chosenVal).trim();
      }

      if (extractedCode !== undefined && extractedCode !== null && extractedCode !== '') {
        console.log(`[BHYT Extension] Người dùng chọn Nghề nghiệp -> Đổi mã ô #nghenghiep thành: "${extractedCode}" (Tên: "${cleanJobName}")`);
        if (inputNn && inputNn.value !== extractedCode) {
          inputNn.value = extractedCode;
          inputNn.classList.remove('bhyt-ext-field-mismatch');
          inputNn.classList.add('bhyt-ext-field-success');
          markTick(inputNn);
          if (window.$) {
            try { window.$('#nghenghiep').val(extractedCode); } catch (e) {}
          }
        }
        sendLayMaNgheNghiep4069(extractedCode);
      }

      cleanS2JobText();
      setTimeout(cleanS2JobText, 40);
      setTimeout(cleanS2JobText, 150);
    };

    // 2. NGƯỜI DÙNG CHỌN NGHỀ NGHIỆP TỪ DROPDOWN <select name="cbnghenghiep" id="cbnghenghiep"> HOẶC SELECT2
    if (cbNn && !cbNn._bhytCleanListenerAttached) {
      cbNn._bhytCleanListenerAttached = true;

      cbNn.addEventListener('change', () => {
        if (!isSyncingNgheNghiep) {
          const chosenOpt = cbNn.selectedIndex >= 0 ? cbNn.options[cbNn.selectedIndex] : null;
          handleJobSelect(chosenOpt, cbNn.value);
        }
      });

      if (window.$) {
        try {
          window.$(cbNn).on('select2:select', function (e) {
            if (!isSyncingNgheNghiep) {
              const selectedData = e?.params?.data;
              let chosenOpt = cbNn.selectedIndex >= 0 ? cbNn.options[cbNn.selectedIndex] : null;
              if (!chosenOpt && selectedData) {
                chosenOpt = { value: selectedData.id, text: selectedData.text };
              }
              handleJobSelect(chosenOpt, selectedData?.id || cbNn.value);
            }
          });
        } catch (err) {}
      }
    }

    // 3. Theo dõi DOM của #select2-cbnghenghiep-container để luôn xóa tiền tố mã số khi hiển thị
    const s2El = document.getElementById('select2-cbnghenghiep-container') || document.querySelector('[id*="select2-cbnghenghiep"]');
    if (s2El && !s2El._bhytObserverAttached) {
      s2El._bhytObserverAttached = true;
      try {
        const obs = new MutationObserver(() => {
          cleanS2JobText();
        });
        obs.observe(s2El, { childList: true, characterData: true, subtree: true });
      } catch (e) {}
    }
  }

  // Tự động cập nhật nghề nghiệp khi ô Tuổi (#tuoi) thay đổi và người dùng chưa khóa nghề nghiệp thủ công
  function setupTuoiListener() {
    const tuoiEl = document.getElementById('tuoi') || document.querySelector('input[name="tuoi"]');
    if (!tuoiEl || tuoiEl._bhytTuoiBound) return;
    tuoiEl._bhytTuoiBound = true;

    const handleTuoiChange = (e) => {
      if (!e.isTrusted || isUserModifiedNgheNghiep) return;
      const ageVal = parseInt(tuoiEl.value || '', 10);
      if (!isNaN(ageVal)) {
        const cardNo = (document.getElementById('sobhyt')?.value || '').trim();
        const inferred = inferNgheNghiep(cardNo, ageVal);
        syncNgheNghiep(inferred.code, inferred.text);
      }
    };
    tuoiEl.addEventListener('input', handleTuoiChange);
    tuoiEl.addEventListener('change', handleTuoiChange);
  }

  // Kiểm tra và tự động chuẩn hóa nghề nghiệp trước khi lưu tiếp nhận (cho phép người dùng tự do thay đổi trước khi Lưu)
  function ensureValidNgheNghiepBeforeSave() {
    if (!isTiepNhanPage()) return;

    // NẾU NGƯỜI DÙNG ĐÃ TỰ TAY THAY ĐỔI NGHỀ NGHIỆP -> TÔN TRỌNG 100%, KHÔNG CAN THIỆP!
    if (isUserModifiedNgheNghiep) {
      console.log('[BHYT Extension] Người dùng đã tự chỉnh sửa Nghề nghiệp trước khi Lưu -> Giữ nguyên 100% dữ liệu người dùng đã chọn.');
      return;
    }

    const inputNn = document.getElementById('nghenghiep') || document.querySelector('input[name="nghenghiep"]');
    const cbNn = document.getElementById('cbnghenghiep') || document.querySelector('select[name="cbnghenghiep"]');
    if (!inputNn || !cbNn) return;

    // Chỉ kiểm tra khi form đang có dữ liệu bệnh nhân tiếp nhận
    const hasPatient = Boolean(
      document.getElementById('sobhyt')?.value?.trim() ||
      document.getElementById('hoten')?.value?.trim() ||
      getCccdInput()?.value?.trim()
    );
    if (!hasPatient) return;

    const curVal = (inputNn.value || '').trim();
    if (!curVal) {
      const cardNo = (document.getElementById('sobhyt')?.value || '').trim();
      const ageVal = parseInt(document.getElementById('tuoi')?.value || '', 10);
      const inferred = inferNgheNghiep(cardNo, ageVal);
      console.log(`[BHYT Extension] Chuẩn hóa mã nghề nghiệp trước khi lưu (ô trống -> "${inferred.code}"):`, inferred);
      syncNgheNghiep(inferred.code, inferred.text);
    }
  }

  // Lắng nghe sự kiện thay đổi trên ô Địa chỉ (#diachi) để tự động bóc tách Tỉnh/Huyện/Xã đổ vào Select2
  function setupDiachiListener() {
    const diachiEl = document.getElementById('diachi') || document.querySelector('input[name="diachi"]');
    if (!diachiEl || diachiEl._bhytDiachiListenerAttached) return;
    diachiEl._bhytDiachiListenerAttached = true;
    console.log('[BHYT Extension] Gắn listener thành công vào ô Địa chỉ (#diachi)');

    let debounceTimer = null;
    const handleDiachiChange = () => {
      if (isClearingForm || isInternalAddressSync) return;
      diachiEl._userManuallyEdited = true;
      const val = (diachiEl.value || '').trim();
      // Bỏ qua nếu chuỗi rỗng hoặc là chuỗi thô từ máy quét có chứa '|' (đã có luồng QR xử lý)
      if (!val || val.includes('|') || val.length < 2) return;

      console.log('[BHYT Extension] Ô Địa chỉ thay đổi -> Tự động bóc tách CV30 Tỉnh/Xã:', val);
      fillAddressAndCv30(val);
    };

    diachiEl.addEventListener('change', (e) => {
      if (!e.isTrusted && isInternalAddressSync) return;
      handleDiachiChange();
    });
    diachiEl.addEventListener('blur', (e) => {
      if (!e.isTrusted && isInternalAddressSync) return;
      handleDiachiChange();
    });
    diachiEl.addEventListener('keyup', (e) => {
      if (e.key === 'Enter') {
        if (debounceTimer) clearTimeout(debounceTimer);
        handleDiachiChange();
      }
    });

    diachiEl.addEventListener('input', (e) => {
      if (!e.isTrusted && isInternalAddressSync) return;
      if (debounceTimer) clearTimeout(debounceTimer);
      debounceTimer = setTimeout(handleDiachiChange, 350);
    });
    diachiEl.addEventListener('paste', () => {
      setTimeout(handleDiachiChange, 100);
    });
  }

  // Giữ nguyên 100% mặc định của HIS cho nút Lưu và phím tắt F3/Ctrl+S (không can thiệp code)

  function setupCapcuuListener() {
    // VNPT HIS đã tự động đồng bộ (sync) ô Cấp cứu với Đối tượng KCB (mã 2)
    // Nếu ta can thiệp thêm sẽ gây ra race condition (nhấp nhả liên tục) với hàm native của HIS.
    // Nên tắt hoàn toàn listener này.
    return;
  }

  function setupDoiTuongKcbListener() {
    const doituongSelect = getDoiTuongSelect();
    if (!doituongSelect || doituongSelect._hasDoiTuongListener) return;
    doituongSelect._hasDoiTuongListener = true;

    const enforce112Over33 = () => {
      const currentSelect = getDoiTuongSelect() || doituongSelect;
      if (!currentSelect || !currentSelect.options) return;
      const selectedOpt = currentSelect.selectedOptions?.[0];
      const val = String(selectedOpt?.value || currentSelect.value || '').trim();
      const txt = String(selectedOpt?.text || '').trim();

      const syncSelect2 = (optText) => {
        const s2List = [
          document.getElementById('select2-doituong-container'),
          document.getElementById('select2-cbdoituong-container'),
          currentSelect.id ? document.getElementById(`select2-${currentSelect.id}-container`) : null,
          currentSelect.parentElement?.querySelector('.select2-selection__rendered'),
          currentSelect.closest('tr, .form-group, .row, div, td')?.querySelector('.select2-selection__rendered')
        ].filter(Boolean);
        s2List.forEach((s2) => {
          s2.textContent = optText;
          s2.title = optText;
          const container = s2.closest('.select2-container');
          if (container) {
            container.style.removeProperty('border');
            container.style.removeProperty('border-radius');
            container.style.removeProperty('background-color');
          }
        });

        const parentContainer = currentSelect.closest('tr, .form-group, .row, div, td');
        if (parentContainer) {
          parentContainer.querySelectorAll('input[type="text"]').forEach((inp) => {
            const iid = (inp.id || '').toLowerCase();
            const iname = (inp.name || '').toLowerCase();
            if (iid.includes('doituong') || iname.includes('doituong') || iid.includes('combo')) {
              inp.value = optText;
            }
          });
        }
      };

      // 1. Nếu ô Cấp cứu đang tích thì luôn ưu tiên mã 2 (Đã loại bỏ theo yêu cầu của user)
      /*
      if (checkIsCapCuu()) {
        if (val !== '2' && !txt.toLowerCase().includes('cấp cứu')) {
          for (let i = 0; i < currentSelect.options.length; i++) {
            const opt = currentSelect.options[i];
            const v = String(opt.value || '').trim();
            const t = String(opt.text || '').trim();
            if (v === '2' || /^2([^\d]|$)/.test(v) || /^2([^\d]|$)/.test(t) || t.toLowerCase().includes('cấp cứu')) {
              if (currentSelect.selectedIndex !== i) {
                currentSelect.selectedIndex = i;
                currentSelect.value = opt.value;
                currentSelect.dispatchEvent(new Event('change', { bubbles: true }));
                syncSelect2(opt.text);
                markTick(currentSelect);
              }
              return;
            }
          }
        }
        return;
      }
      */

      // 2. Xử lý khi HIS mặc định gán mã 3 hoặc 3.3
      const is33 = val === '3.3' || val === '3' || txt.startsWith('3.3') || txt.includes('3.3') || txt.startsWith('3 -');
      if (is33) {
        // Kiểm tra nếu bệnh nhân Đúng tuyến (đã tích Đúng tuyến hoặc mã ĐKKCB là 49006):
        const dungTuyenCheck = getDungTuyenCheckbox();
        const thongTuyenCheck = getThongTuyenCheckbox();
        const curDkbd = (document.getElementById('noidangky')?.value || document.querySelector('input[name="noidangky"]')?.value || '').trim().replace(/\D/g, '').substring(0, 5);
        const cleanCskcb = String(cachedCskcbCode || '49008').trim().replace(/\D/g, '').substring(0, 5);
        const isDungTuyen = Boolean((dungTuyenCheck && dungTuyenCheck.checked && (!thongTuyenCheck || !thongTuyenCheck.checked)) || (curDkbd && cleanCskcb && curDkbd === cleanCskcb));

        if (isDungTuyen) {
          applyDoiTuongKcb(curDkbd || cleanCskcb);
          return;
        }

        let idx112 = -1;
        for (let i = 0; i < currentSelect.options.length; i++) {
          const opt = currentSelect.options[i];
          const v = String(opt.value || '').trim();
          const t = String(opt.text || '').trim();
          if (
            v === '1.12' ||
            v === '112' ||
            v === '01.12' ||
            v.includes('1.12') ||
            t.includes('1.12') ||
            /^1\.12([^\d]|$)/.test(v) ||
            /^1\.12([^\d]|$)/.test(t) ||
            t.toLowerCase().includes('dưới 50') ||
            t.toLowerCase().includes('duoi 50') ||
            t.toLowerCase().includes('dưới 50 điểm')
          ) {
            idx112 = i;
            break;
          }
        }

        // Nếu trong select chưa có option 1.12 thì tự tạo mới và thêm vào
        if (idx112 < 0) {
          const opt112 = document.createElement('option');
          opt112.value = '1.12';
          opt112.text = '1.12 - Tự đến KCB ngoại trú cấp cơ bản đạt dưới 50 điểm';
          currentSelect.appendChild(opt112);
          idx112 = currentSelect.options.length - 1;
        }

        if (idx112 >= 0 && currentSelect.selectedIndex !== idx112) {
          console.log('[BHYT Extension] Phát hiện mã 3.3 Thông tuyến, tự động ưu tiên chuyển sang mã 1.12 chuẩn xác:', currentSelect.options[idx112].text);
          currentSelect.selectedIndex = idx112;
          currentSelect.value = currentSelect.options[idx112].value;
          currentSelect.dispatchEvent(new Event('change', { bubbles: true }));
          syncSelect2(currentSelect.options[idx112].text);
          currentSelect.classList.remove('bhyt-ext-field-success', 'bhyt-ext-field-mismatch');
          currentSelect.style.removeProperty('background-color');
          currentSelect.style.removeProperty('border-color');
        }
      }
    };

    doituongSelect.addEventListener('change', enforce112Over33);
    doituongSelect.addEventListener('input', enforce112Over33);
    doituongSelect.addEventListener('blur', enforce112Over33);
  }

  // Bảo vệ triệt để ô Ngày sinh (*), Từ ngày / Đến ngày khi người dùng rê chuột (mouseenter, mouseover) hoặc focus
  // Ngăn chặn hoàn toàn EasyUI Datebox tự động format lùi về ngày cũ hoặc làm rỗng (chỉ hiện placeholder dd/mm/yyyy)
  function setupDateboxHoverGuard() {
    if (window.__bhytDateboxHoverGuardAttached) return;
    window.__bhytDateboxHoverGuardAttached = true;

    const syncDateFields = (e) => {
      const t = e.target;
      if (!t) return;

      // 1. BẢO VỆ Ô NGÀY SINH (*) (#namsinh, #ngaysinh)
      const dobVal = activeVerifiedDob || lastScannedQrDob || (currentBhytCardData ? formatBhxhDate(currentBhytCardData.ngaySinh) : '') || (lastTiepNhanFormSnapshot?.activeVerifiedDob);
      // Không đụng vào ô khi người dùng đang tự nhập; chỉ khôi phục khi ô bị HIS làm trống / placeholder
      if (dobVal && dobVal.toLowerCase() !== 'dd/mm/yyyy' && !isUserEditingDob()) {
        const isNs = isDobInputElement(t);
        if (isNs) {
          const curVal = (t.value || '').trim();
          if (curVal.toLowerCase() === 'dd/mm/yyyy' || curVal === '__/__/____') {
            t.value = dobVal;
            fillNgaySinhFields(dobVal, dobVal);
          }
        }
      }

      // 2. BẢO VỆ Ô TỪ NGÀY
      if (activeVerifiedTuNgay) {
        const isTu = t.id === 'tungay' || t.name === 'tungay' ||
                     t.id === 'the_tungay' || t.name === 'the_tungay' ||
                     (t.classList && (t.classList.contains('datebox-text') || t.classList.contains('textbox-text')) &&
                      (t.closest('.textbox, .combo')?.previousElementSibling?.id === 'tungay' ||
                       t.closest('.textbox, .combo')?.previousElementSibling?.name === 'tungay' ||
                       t.closest('tr, .form-group, td')?.querySelector('#tungay, input[name="tungay"]')));
        if (isTu) {
          const curVal = (t.value || '').trim();
          if (curVal && curVal !== activeVerifiedTuNgay) {
            t.value = activeVerifiedTuNgay;
            const tuEl = findTuNgayInput();
            if (tuEl && tuEl.value !== activeVerifiedTuNgay) {
              tuEl.value = activeVerifiedTuNgay;
            }
          }
        }
      }

      // 3. BẢO VỆ Ô ĐẾN NGÀY
      if (activeVerifiedDenNgay) {
        const isDen = t.id === 'denngay' || t.name === 'denngay' ||
                      t.id === 'the_denngay' || t.name === 'the_denngay' ||
                      (t.classList && (t.classList.contains('datebox-text') || t.classList.contains('textbox-text')) &&
                       (t.closest('.textbox, .combo')?.previousElementSibling?.id === 'denngay' ||
                        t.closest('.textbox, .combo')?.previousElementSibling?.name === 'denngay' ||
                        t.closest('tr, .form-group, td')?.querySelector('#denngay, input[name="denngay"]')));
        if (isDen) {
          const curVal = (t.value || '').trim();
          if (curVal && curVal !== activeVerifiedDenNgay) {
            t.value = activeVerifiedDenNgay;
            const denEl = findDenNgayInput();
            if (denEl && denEl.value !== activeVerifiedDenNgay) {
              denEl.value = activeVerifiedDenNgay;
            }
          }
        }
      }
    };

    ['mouseenter', 'mouseover', 'focus', 'focusin'].forEach((evtType) => {
      document.addEventListener(evtType, syncDateFields, true);
    });
  }

  function setupFormListeners() {
    setupGlobalQrScannerListener();
    setupCccdListener();
    setupSobhytListener();
    setupDiachiListener();
    setupChuoiNhanDangListener();
    setupNamsinhListener();
    setupNamsinhCheckboxUserListener();
    setupTuoiListener();
    setupMayteListener();
    setupNghenghiepListener();
    setupTimBnButtonListener();
    interceptExistingCheckButtons();
    setupKtraMcctButtonListener();
    setupCapcuuListener();
    setupDoiTuongKcbListener();
    setupDateboxHoverGuard();
    setupDanhSachTiepNhanListener();
    startTiepNhanMayteSupervisor();

    // BẢO VỆ HIỆU NĂNG: Singleton guard kiểm tra định kỳ nhẹ nhàng 3.5s (chỉ chạy khi đã có dữ liệu BHYT đã xác thực)
    if (!window.__bhytDobAddressGuardStarted) {
      window.__bhytDobAddressGuardStarted = true;
      setInterval(() => {
        if (activeVerifiedDob || activeVerifiedTuNgay || currentBhytCardData) {
          enforceVerifiedDobAndAddress();
        }
      }, 3500);
    }

    // Khôi phục TỨC THÌ Từ ngày / Đến ngày khi HIS ghi đè (vd 01/01/2026) lúc rê chuột / focus / change,
    // tránh hiện tượng ô nhảy sai giá trị rồi mới nhảy về đúng (chỉ giới hạn đúng các ô ngày tháng)
    if (!window.__bhytInstantDateGuardStarted) {
      window.__bhytInstantDateGuardStarted = true;
      let busy = false;
      let dateGuardDebounce = null;
      const instantRestore = () => {
        if (busy || !currentBhytCardData || !isTiepNhanPage()) return;
        if (!activeVerifiedTuNgay && !activeVerifiedDenNgay) return;
        busy = true;
        try {
          enforceVerifiedBhytCardFields();
        } finally {
          setTimeout(() => { busy = false; }, 0);
        }
      };
      ['mouseover', 'focusin'].forEach((evName) => {
        document.addEventListener(evName, (e) => {
          const t = e.target;
          if (!t || !t.matches) return;
          const isDateTarget = t.matches('#tungay, #denngay, input[name="tungay"], input[name="denngay"], #the_tungay, #the_denngay') ||
                              (t.classList && (t.classList.contains('datebox-text') || t.classList.contains('textbox-text')) &&
                               Boolean(t.closest('.textbox, .combo')?.previousElementSibling?.matches?.('#tungay, #denngay, input[name="tungay"], input[name="denngay"]')));
          if (isDateTarget) {
            if (dateGuardDebounce) clearTimeout(dateGuardDebounce);
            dateGuardDebounce = setTimeout(instantRestore, 50);
          }
        }, true);
      });
    }
  }

