  // =========================================================================
  // LÀM SẠCH FORM TIẾP NHẬN BỆNH NHÂN CŨ (TRÁNH LƯU/TÁI HIỂN THỊ DỮ LIỆU CŨ)
  // =========================================================================
  let isClearingForm = false;
  let lastCheckedPatientSignature = '';
  let lastRenderedResultBoxesArgs = null;

  function hasVisibleLichSuKhamModal() {
    try {
      const windows = document.querySelectorAll('.window:not(.window-shadow), .ui-dialog, .modal');
      for (const w of windows) {
        if (w.offsetWidth > 0 && w.offsetHeight > 0 && window.getComputedStyle(w).display !== 'none' && window.getComputedStyle(w).visibility !== 'hidden') {
          const header = w.querySelector('.panel-header .panel-title, .panel-title, .ui-dialog-title, .modal-title, .window-title');
          const titleText = (header ? header.textContent : '').toLowerCase();
          if (titleText.includes('lịch sử khám') || titleText.includes('lich su kham') || titleText.includes('lịch sử kcb') || titleText.includes('lskcb')) {
            return true;
          }
        }
      }
    } catch (e) {}
    return false;
  }

  function isLichSuKhamModalOpen() {
    if (hasVisibleLichSuKhamModal()) {
      return true;
    }
    return Boolean(window.__bhytIsViewingLichSuKham);
  }

  // =========================================================================
  // BẢO VỆ TUYỆT ĐỐI FORM / MODAL KÝ SỐ (SMARTCA / VNPT-CA / CHỮ KÝ SỐ / TOKEN)
  // Giữ nguyên 100% layout, kích thước, thanh công cụ, nút bấm theo mặc định của HIS
  // =========================================================================
  function isKySoOrSmartCaModal(modalOrDialog) {
    if (!modalOrDialog) return false;
    try {
      // 1. Quét ID và Class
      const idAndClass = ((modalOrDialog.id || '') + ' ' + (modalOrDialog.className || '')).toLowerCase();
      if (
        idAndClass.includes('kyso') || idAndClass.includes('ky_so') ||
        idAndClass.includes('smartca') || idAndClass.includes('smart_ca') ||
        idAndClass.includes('chuky') || idAndClass.includes('chu_ky') ||
        idAndClass.includes('casign') || idAndClass.includes('ca_sign') ||
        idAndClass.includes('vnptca') || idAndClass.includes('viettelca') ||
        idAndClass.includes('digitalsign')
      ) {
        return true;
      }

      // 2. Quét tiêu đề header / window-title / panel-title / dialog-title
      const titleEls = modalOrDialog.querySelectorAll ? modalOrDialog.querySelectorAll('.ui-dialog-title, .modal-title, .panel-title, .title, .window-title, h3, h4, legend, .panel-header') : [];
      let titleText = '';
      for (const el of titleEls) {
        titleText += ' ' + (el.textContent || '');
      }
      if (!titleText && modalOrDialog.textContent) {
        titleText = modalOrDialog.textContent.substring(0, 400);
      }
      const t = titleText.toLowerCase();
      if (
        t.includes('ký số') || t.includes('ky so') ||
        t.includes('chữ ký') || t.includes('chu ky') ||
        t.includes('smartca') || t.includes('smart ca') ||
        t.includes('chứng thư') || t.includes('chung thu') ||
        t.includes('xác thực ký') || t.includes('xac thuc ky') ||
        t.includes('cán bộ y tế ký') || t.includes('can bo y te ky') ||
        t.includes('ký tài liệu') || t.includes('ky tai lieu') ||
        t.includes('ký văn bản') || t.includes('ky van ban') ||
        t.includes('ký bệnh án') || t.includes('ky benh an') ||
        t.includes('ký hồ sơ') || t.includes('ky ho so') ||
        t.includes('ký toa') || t.includes('ky toa') ||
        t.includes('ký phiếu') || t.includes('ky phieu') ||
        t.includes('vnpt-ca') || t.includes('vnptca') ||
        t.includes('viettel-ca') || t.includes('viettelca') ||
        t.includes('ca sign') || t.includes('casign') ||
        t.includes('chứng thư số') || t.includes('token ký')
      ) {
        return true;
      }

      // 3. Quét iframes bên trong hoặc nguồn iframe
      const iframes = modalOrDialog.querySelectorAll ? modalOrDialog.querySelectorAll('iframe') : [];
      for (const ifr of iframes) {
        const src = (ifr.src || ifr.contentWindow?.location?.href || '').toLowerCase();
        if (src.includes('kyso') || src.includes('smartca') || src.includes('chuky') || src.includes('casign') || src.includes('vnptca')) {
          return true;
        }
      }

      // 4. Quét phần tử con đặc thù của Form Ký số
      if (modalOrDialog.querySelector?.('[id*="kyso"], [class*="kyso"], [id*="smartca"], [class*="smartca"], [id*="chuky"], [class*="chuky"], [id*="casign"], [class*="casign"], input[name*="mapin"], input[name*="otp"], [id*="pin"], [name*="pin"]')) {
        return true;
      }
    } catch (e) {}
    return false;
  }

  function hasVisibleKySoOrSmartCa(doc = document) {
    try {
      const rootDoc = doc || document;
      if (document.body?.classList.contains('bhyt-kyso-open') || document.documentElement?.classList.contains('bhyt-kyso-open')) {
        return true;
      }
      const candidates = rootDoc.querySelectorAll('.window:not(.window-shadow), .panel.window, .ui-dialog, .modal.show, .modal:not([style*="display: none"]), iframe');
      for (const el of candidates) {
        if (!el.classList.contains('window-closed') && !el.hasAttribute('hidden') && !el.style.display.includes('none')) {
          if (isKySoOrSmartCaModal(el)) {
            return true;
          }
        }
      }
      const curHref = (rootDoc.location?.href || '').toLowerCase();
      if (curHref.includes('smartca') || curHref.includes('kyso') || curHref.includes('chuky') || curHref.includes('casign')) {
        return true;
      }
    } catch (e) {}
    return false;
  }

  function isAnyModalOpen() {
    try {
      // 1. Kiểm tra lớp phủ nền đặc trưng của cửa sổ modal (EasyUI .window-mask, jQuery UI .ui-widget-overlay, Bootstrap .modal-backdrop)
      const hasOverlay = document.querySelector('.window-mask:not([style*="display: none"]):not([style*="display:none"]), .ui-widget-overlay:not([style*="display: none"]):not([style*="display:none"]), .modal-backdrop');
      if (hasOverlay) return true;

      // 2. Kiểm tra các modal nổi thực sự có tiêu đề hoặc vai trò dialog (loại trừ các panel layout của HIS)
      const openModals = document.querySelectorAll('.ui-dialog:not([style*="display: none"]):not([style*="display:none"]), .modal.show, .modal.in, div[role="dialog"]:not(.combo-panel)');
      for (const w of openModals) {
        if (!w.classList.contains('window-closed') && !w.hasAttribute('hidden') && w.offsetHeight > 0 && w.offsetWidth > 0) {
          return true;
        }
      }
      if (hasVisibleKySoOrSmartCa()) return true;
    } catch (e) {}
    return false;
  }

  function updateModalOpenState() {
    const isKySo = hasVisibleKySoOrSmartCa();
    const hasModal = isKySo || isAnyModalOpen();
    if (document.body) {
      document.body.classList.toggle('bhyt-modal-open', hasModal);
      document.body.classList.toggle('bhyt-kyso-open', isKySo);
    }
    if (document.documentElement) {
      document.documentElement.classList.toggle('bhyt-modal-open', hasModal);
      document.documentElement.classList.toggle('bhyt-kyso-open', isKySo);
    }

    // Ẩn/hiện nút nổi mép phải trên Form Tiếp nhận
    const floatingTiepNhanBtn = document.getElementById('bhytExtFloatingRightBtn');
    if (floatingTiepNhanBtn) {
      floatingTiepNhanBtn.style.setProperty('display', hasModal ? 'none' : '', 'important');
      floatingTiepNhanBtn.style.setProperty('visibility', hasModal ? 'hidden' : '', 'important');
      floatingTiepNhanBtn.style.setProperty('opacity', hasModal ? '0' : '', 'important');
      floatingTiepNhanBtn.style.setProperty('pointer-events', hasModal ? 'none' : '', 'important');
    }

    // Ẩn/hiện nút nổi mép phải trên Form Bảng kê
    const floatingBangKeBtn = document.getElementById('bhytExtBangKeFloatingBtn');
    if (floatingBangKeBtn) {
      floatingBangKeBtn.style.setProperty('display', hasModal ? 'none' : '', 'important');
      floatingBangKeBtn.style.setProperty('visibility', hasModal ? 'hidden' : '', 'important');
      floatingBangKeBtn.style.setProperty('opacity', hasModal ? '0' : '', 'important');
      floatingBangKeBtn.style.setProperty('pointer-events', hasModal ? 'none' : '', 'important');
    }

    // Nút Kiểm tra BHYT cạnh 'Xem thông tin' (bảng kê) là nút inline trên thanh tác vụ, tuyệt đối luôn hiển thị
    const inlineBangKeBtn = document.getElementById('bhytExtBangKeInlineBtn');
    if (inlineBangKeBtn) {
      inlineBangKeBtn.style.setProperty('display', 'inline-flex', 'important');
      inlineBangKeBtn.style.setProperty('visibility', 'visible', 'important');
      inlineBangKeBtn.style.setProperty('opacity', '1', 'important');
      inlineBangKeBtn.style.setProperty('pointer-events', 'auto', 'important');
    }

    // Xóa mọi nút BHYT vô tình lọt vào bên trong bất kỳ cửa sổ modal / dialog nào
    if (hasModal) {
      document.querySelectorAll('.window #bhytExtInlineBtnWrapper, .window #bhytExtInlineBtn, .panel.window #bhytExtInlineBtnWrapper, .panel.window #bhytExtInlineBtn, .window #bhytExtFloatingRightBtn, .window #bhytExtBangKeFloatingBtn, .window .bhyt-ext-floating-right-btn').forEach((el) => {
        try { el.remove(); } catch (e) {}
      });
      // Nếu là modal ký số, đảm bảo sạch 100% không để sót bất kỳ phần tử nào của plugin
      if (isKySo) {
        document.querySelectorAll('[class*="kyso"] #btnCheckTheBHYT_modal, [class*="smartca"] #btnCheckTheBHYT_modal, [id*="kyso"] #btnCheckTheBHYT_modal, [id*="smartca"] #btnCheckTheBHYT_modal, [class*="kyso"] #bhyt_modal_btn_wrapper, [class*="smartca"] #bhyt_modal_btn_wrapper, [class*="kyso"] #bhyt_modal_msg_box, [class*="smartca"] #bhyt_modal_msg_box').forEach((el) => {
          try { el.remove(); } catch (e) {}
        });
      }
    }
    return hasModal;
  }

