  function ensureTiepNhanResultBoxesPersisted() {
    const args = lastRenderedResultBoxesArgs || savedPatientBhytResult;
    if (!args || !args.data) return;

    // Chỉ khôi phục nếu form tiếp nhận vẫn có thông tin bệnh nhân
    const currentSig = getTiepNhanPatientSig();
    if (!currentSig && !window.__bhytIsViewingLichSuKham) return;

    const currentBox = document.getElementById('bhytExtResultContainer');
    if (!currentBox || !currentBox.querySelector('.bhyt-notification-text, .bhyt-ext-fieldset')) {
      console.log('[BHYT Extension] Khôi phục lại hộp thông báo & Lịch sử KCB/Kiểm tra thẻ trên form tiếp nhận.');
      lastRenderedResultBoxesArgs = args;
      renderHisResultBoxes(
        args.data,
        args.lichSuKcb,
        args.lichSuKiemTraThe,
        args.ghiChuCổng,
        args.discrepancies
      );
    }
  }

  function getTiepNhanPatientSig() {
    if ((isLichSuKhamModalOpen() || isAnyModalOpen()) && lastCheckedPatientSignature) {
      return lastCheckedPatientSignature;
    }
    const getVal = (id) => {
      // Chỉ tìm ô input bên ngoài mọi modal / popup / dialog nổi
      const inputs = document.querySelectorAll(`#${id}, input[name="${id}"]`);
      for (const el of inputs) {
        if (!el.closest('.window, .panel.window, .ui-dialog, .modal, [role="dialog"], #suattModal')) {
          return (el?.value || '').trim().toUpperCase();
        }
      }
      return '';
    };
    const mayte = getVal('mayte') || getVal('mabn') || getVal('mabenhnhan') || (document.querySelector('#lbl_mayte:not(.window #lbl_mayte)')?.textContent || '').trim().toUpperCase();
    const sovaovien = getVal('sovaovien') || getVal('sophieu') || getVal('so_vaovien') || getVal('soba');
    const socmt = getVal('socmt') || getVal('so_cccd') || getVal('cccd');
    const sobhyt = getVal('sobhyt');
    const hoten = getVal('hoten') || getVal('tenbn') || getVal('ten_benh_nhan') || (document.querySelector('#lbl_hoten:not(.window #lbl_hoten)')?.textContent || '').trim().toUpperCase();
    const dob = getVal('namsinh') || getVal('ngaysinh');
    if (!mayte && !sovaovien && !socmt && !sobhyt && !hoten) {
      return '';
    }
    return `${mayte}|${sovaovien}|${socmt}|${sobhyt}|${hoten}|${dob}`;
  }

