  // Kiểm tra chuỗi QR CCCD đầy đủ theo định dạng của Bộ Công An
  function isCompleteQrCccd(raw) {
    if (!raw || typeof raw !== 'string') return false;
    const s = raw.replace(/[\r\n]+/g, '').trim();
    if (!s.includes('|')) return false;
    const parts = s.split('|');
    // Chuẩn CCCD Bộ Công An có ít nhất 7 trường: CCCD|CMND|Họ tên|Ngày sinh|Giới tính|Địa chỉ|Ngày cấp...
    if (parts.length < 7) return false;
    const cccd = (parts[0] || '').trim();
    const hoTen = (parts[2] || '').trim();
    const dob = (parts[3] || '').trim();
    const address = (parts[5] || '').trim();
    const ngayCap = (parts[6] || '').trim();
    const currentYear = new Date().getFullYear();
    let isValidDob = false;
    if (/^\d{8}$/.test(dob)) {
      const y1 = parseInt(dob.substring(4, 8), 10);
      const y2 = parseInt(dob.substring(0, 4), 10);
      isValidDob = (y1 >= 1900 && y1 <= currentYear) || (y2 >= 1900 && y2 <= currentYear);
    } else if (/^\d{4}$/.test(dob)) {
      const y = parseInt(dob, 10);
      isValidDob = (y >= 1900 && y <= currentYear);
    }
    const isValidNgayCap = /^\d{8}$/.test(ngayCap) || /^\d{2}\/\d{2}\/\d{4}$/.test(ngayCap);
    return /^\d{9,12}$/.test(cccd) && hoTen.length >= 2 && isValidDob && address.length >= 2 && isValidNgayCap;
  }

  // Giải mã chuỗi HEX UTF-8 (dùng cho Họ tên và Địa chỉ trong mã QR thẻ giấy BHYT)
  function decodeHexUtf8(hex) {
    if (!hex || typeof hex !== 'string') return '';
    const clean = hex.replace(/\s+/g, '');
    if (clean.length % 2 !== 0) return hex;
    try {
      const bytes = new Uint8Array(clean.match(/.{1,2}/g).map(byte => parseInt(byte, 16)));
      return new TextDecoder('utf-8').decode(bytes);
    } catch (e) {
      return hex;
    }
  }

  // Kiểm tra chuỗi QR Thẻ giấy BHYT theo định dạng chuẩn của BHXH Việt Nam
  // Format: MA_THE|HO_TEN_HEX|NGAY_SINH|GIOI_TINH|DIA_CHI_HEX|MA_CSKCB|GT_TU|GT_DEN|NGAY_CAP|MA_BHXH|...|NGAY_DU_5_NAM|CHUOI_KT|$
  // Ví dụ: TS2494920738521|4e677579e1bb856e205468e1bb8b204261|23/09/1954|2|48c3b261204e616d2c2058c3a320447579205472756e672c20487579e1bb876e2044757920587579c3aa6e2c2054e1bb896e68205175e1baa36e67204e616d|49 - 006|01/06/2021|-|30/06/2021|49074920738521|-|4| 01/04/2017|6073cc49a85a820d-1202|$
  function isCompleteQrTheGiayBhyt(raw) {
    if (!raw || typeof raw !== 'string') return false;
    const s = raw.replace(/[\r\n]+/g, '').trim();
    if (!s.includes('|')) return false;
    const parts = s.split('|');
    if (parts.length < 6) return false;

    const f0 = (parts[0] || '').trim();
    const f1 = (parts[1] || '').trim();
    const f2 = (parts[2] || '').trim();
    const f3 = (parts[3] || '').trim();

    if (s.endsWith('$')) return true;

    const isMaTheBhyt = /^[A-Z]{2}[1-9]\d{2}\d{12}$/i.test(f0) || /^[A-Z]{2}\d{15}$/i.test(f0) || /^[A-Z]{2}[1-9]\d{2}\d{10}$/i.test(f0) || /^[A-Z]{2}\d{13}$/i.test(f0) || /^[A-Z]{2}\d{8,15}$/i.test(f0);
    const isHexName = /^[0-9a-fA-F]{4,}$/.test(f1) && f1.length % 2 === 0;
    const isDateDob = /^\d{1,2}\/\d{1,2}\/\d{4}$/.test(f2) || /^\d{4}$/.test(f2);
    const isGenderCode = f3 === '1' || f3 === '2';

    return Boolean(isMaTheBhyt || (isHexName && isDateDob));
  }

  function isAnyCompleteQr(raw) {
    return isCompleteQrCccd(raw) || isCompleteQrTheGiayBhyt(raw);
  }

  let qrScanDebounceTimer = null;
  let lastScannerKeyTime = 0;

  // Giới hạn CMT/CCCD không quá 12 ký tự số (chỉ nhận số khi gõ tay, không phá vỡ quét mã QR, không bôi đen)
  function attachCccdMax12Enforcement(inputEl) {
    if (!inputEl || inputEl.dataset.bhytMax12Attached === 'true') return;
    inputEl.dataset.bhytMax12Attached = 'true';

    // 1. Bắt phím keydown: hỗ trợ cả nhập tay (tối đa 12 số) và máy quét QR (không chặn bất kỳ ký tự nào của chuỗi QR)
    inputEl.addEventListener('keydown', (e) => {
      const now = Date.now();
      const isHighSpeedScanner = (now - lastScannerKeyTime) < 55;
      lastScannerKeyTime = now;

      if (e.ctrlKey || e.metaKey || e.altKey) return;
      if (['Backspace', 'Delete', 'Tab', 'Escape', 'Enter', 'ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End'].includes(e.key)) return;
      if (e.key === '|') return; // Cho phép máy quét QR truyền ký tự ngăn cách

      // Nếu đã có ký tự '|' trong ô hoặc đang là máy quét tốc độ cao: TUYỆT ĐỐI KHÔNG CHẶN
      const curVal = inputEl.value || '';
      if (curVal.includes('|') || isHighSpeedScanner) return;

      // Khi người dùng gõ tay thông thường từng phím (không phải máy quét QR):
      if (e.key && e.key.length === 1) {
        // Chặn nếu gõ ký tự không phải chữ số khi chưa có dấu '|'
        if (!/^\d$/.test(e.key)) {
          e.preventDefault();
          return;
        }

        // Giới hạn không quá 12 số khi nhập tay nếu chưa bôi đen text
        const selStart = inputEl.selectionStart;
        const selEnd = inputEl.selectionEnd;
        const hasSelection = selStart !== null && selEnd !== null && selStart !== selEnd;
        if (!hasSelection && curVal.replace(/\D/g, '').length >= 12) {
          e.preventDefault();
          return;
        }
      }
    });

    // 2. Bắt sự kiện dán (paste): chỉ lấy tối đa 12 số nếu không phải chuỗi QR
    inputEl.addEventListener('paste', (e) => {
      const pasteText = (e.clipboardData || window.clipboardData)?.getData('text') || '';
      if (pasteText && pasteText.includes('|')) {
        return; // Để sự kiện xử lý QR tiếp nhận đầy đủ
      }
      e.preventDefault();
      const digits = pasteText.replace(/\D/g, '').slice(0, 12);
      inputEl.value = digits;
      updateCccdCounter(digits);
      inputEl.dispatchEvent(new Event('input', { bubbles: true }));
      inputEl.dispatchEvent(new Event('change', { bubbles: true }));
    });

    // 3. Bắt sự kiện input: tự động lọc chỉ giữ chữ số và cắt tối đa 12 ký tự khi nhập tay (giữ nguyên con trỏ, tuyệt đối không bôi đen)
    inputEl.addEventListener('input', () => {
      if (isClearingForm) return;
      const val = inputEl.value || '';
      if (val.includes('|')) return; // Bỏ qua khi đang nhận chuỗi QR

      const digitsOnly = val.replace(/\D/g, '').slice(0, 12);
      if (inputEl.value !== digitsOnly) {
        const selStart = inputEl.selectionStart;
        inputEl.value = digitsOnly;
        if (selStart !== null) {
          try { inputEl.setSelectionRange(selStart, selStart); } catch (e) {}
        }
      }
    });
  }

  function setupCccdListener() {
    const cccdEl = getCccdInput();
    if (!cccdEl || cccdEl.dataset.bhytListenerAttached === 'true') return;

    cccdEl.dataset.bhytListenerAttached = 'true';
    console.log('[BHYT Extension] Gắn listener thành công vào ô CCCD:', cccdEl.id || cccdEl.name);

    const wrap = findEasyUiWrapper(cccdEl);
    const txtInp = wrap ? wrap.querySelector('.textbox-text') : null;

    // Cập nhật số đếm ban đầu nếu ô đã có giá trị
    updateCccdCounter(cccdEl.value || (txtInp ? txtInp.value : ''));

    let lastEnterTs = 0;
    const handleEnterKey = async (e) => {
      if (e.key === 'Enter') {
        const now = Date.now();
        if (now - lastEnterTs < 800) {
          e.preventDefault();
          return;
        }
        lastEnterTs = now;

        if (isClearingForm) return;
        clearTimeout(debounceTimer);
        clearTimeout(qrScanDebounceTimer);
        const curEl = e.currentTarget || cccdEl;
        const val = (curEl.value || cccdEl.value || '').trim();
        updateCccdCounter(val);
        console.log('[BHYT Extension] Bắt phím Enter trên ô CCCD:', val);

        if (val.includes('|')) {
          e.preventDefault();
          e.stopPropagation();
          e.stopImmediatePropagation();
          handleQrScan(val, curEl);
          return;
        }

        // Nếu vừa xử lý quét mã QR trong vòng 1000ms, nuốt phím Enter từ đầu đọc barcode để tránh gọi trùng lặp
        if (typeof lastProcessedQrTime !== 'undefined' && (now - lastProcessedQrTime) < 1000) {
          console.log('[BHYT Extension] Bỏ qua Enter từ đầu đọc barcode sau khi quét QR (< 1s)');
          e.preventDefault();
          return;
        }

        const digitsOnly = val.replace(/\D/g, '').slice(0, 12);
        if (!digitsOnly) {
          renderErrorBanner('⚠️ Vui lòng nhập số CCCD hoặc quét mã QR trước khi bấm Enter.');
          return;
        }

        // BƯỚC 1: ƯU TIÊN KIỂM TRA HỒ SƠ LƯU GẦN NHẤT TRONG BỘ NHỚ LƯU TRỮ (0ms)
        let bnFound = hisPatientCache.get(digitsOnly) || cachedPatientsFromStorage[digitsOnly] || null;

        // Xác thực hồ sơ lấy từ cache phải khớp với số CCCD người dùng nhập
        if (bnFound) {
          const cachedCmt = (bnFound.CMT_BENHNHAN || bnFound.SO_CCCD || bnFound.SOCMT || bnFound.socmt || '').replace(/\D/g, '');
          if (cachedCmt && cachedCmt !== digitsOnly) {
            console.warn('[BHYT Extension] Phát hiện cache CCCD không khớp hồ sơ bệnh nhân, loại bỏ cache:', { digitsOnly, cachedCmt });
            hisPatientCache.delete(digitsOnly);
            if (cachedPatientsFromStorage[digitsOnly]) delete cachedPatientsFromStorage[digitsOnly];
            bnFound = null;
          }
        }

        const currentCmt = currentHisPatient?.CMT_BENHNHAN || currentHisPatient?.socmt;
        const isNewPatient = digitsOnly !== currentCmt || !currentHisPatient;

        if (bnFound) {
          console.log('[BHYT Extension] Ưu tiên nạp hồ sơ bệnh nhân lưu gần nhất (0ms):', bnFound);
          currentHisPatient = bnFound;
          applyHisPatientToForm(bnFound);
          const cachedCard = bnFound.SO_THE_BAOHIEM_YTE || bnFound.SO_THE_BHYT || bnFound.sobhyt || bnFound.maThe || '';
          showBannerChecking(`⏳ Đã nạp thông tin lưu gần nhất (Thẻ BHYT: ${cachedCard || 'Chưa có'}). Đang đối soát với Cổng BHXH...`);
        } else {
          // Bệnh nhân chưa có trong cache, dọn dẹp form bệnh nhân cũ trước khi tra cứu mới
          if (isNewPatient) {
            clearPreviousPatientForm(true);
          }
          showBannerChecking('⏳ Đang tìm kiếm hồ sơ trong HIS & kiểm tra Cổng BHXH...');
        }

        lastCheckedCccd = digitsOnly;

        // WATCHDOG: nếu sau 15s banner vẫn treo ở trạng thái "đang tìm kiếm" và không có phép kiểm tra nào đang chạy
        clearTimeout(window.__bhytSearchWatchdog);
        window.__bhytSearchWatchdog = setTimeout(() => {
          try {
            const box = document.getElementById('bhytExtResultContainer');
            const stuck = box && /Đang tìm kiếm hồ sơ|Đã nạp thông tin lưu gần nhất/.test(box.textContent || '');
            if (stuck && !isChecking) {
              console.warn('[BHYT Extension] Watchdog: banner treo quá 15s, gỡ treo');
              renderErrorBanner('⚠️ Không nhận được phản hồi từ HIS / Cổng BHXH. Vui lòng bấm Enter ở ô CCCD để thử lại.');
            }
          } catch (e) {}
        }, 15000);
        syncQuocTich('01');
        applyCapcuuRuleByUrl();

        // Giữ nguyên 100% màu sắc mặc định của HIS
        cccdEl.classList.remove('bhyt-ext-field-success', 'bhyt-ext-field-mismatch');
        cccdEl.style.removeProperty('background-color');
        cccdEl.style.removeProperty('border-color');
        cccdEl.style.removeProperty('color');
        if (txtInp) {
          txtInp.classList.remove('bhyt-ext-field-success', 'bhyt-ext-field-mismatch');
          txtInp.style.removeProperty('background-color');
          txtInp.style.removeProperty('border-color');
          txtInp.style.removeProperty('color');
        }

        // BƯỚC 2: TRA CỨU THÊM TRONG CSDL NỘI BỘ HIS ĐỂ LÀM GIÀU DỮ LIỆU
        try {
          const hisResult = await lookupPatientInHis(digitsOnly);
          if (hisResult) {
            bnFound = hisResult;
            currentHisPatient = hisResult;
            applyHisPatientToForm(hisResult);
            savePatientToPersistentCache(hisResult);
          }
        } catch (err) {
          console.log('[BHYT Extension] Lỗi khi tra cứu bệnh nhân trong HIS:', err);
        }

        // BƯỚC 3: KÍCH HOẠT ĐỐI SOÁT VỚI CỔNG BHXH & TỰ ĐỘNG ĐỐI SOÁT MÃ Y TẾ
        if (bnFound) {
          console.log('[BHYT Extension] Kích hoạt đối soát Cổng cho bệnh nhân:', bnFound.TEN_BENH_NHAN || bnFound.tenbenhnhan);
          triggerBhytCheckFromForm();
        } else {
          // Trường hợp bệnh nhân chưa liên kết CCCD trong HIS nhưng đã có Thẻ BHYT trên form:
          const existingCard = (document.getElementById('sobhyt')?.value || '').trim().replace(/\s+/g, '').toUpperCase();
          if (existingCard && existingCard.length >= 10 && !existingCard.includes('|')) {
            console.log('[BHYT Extension] Chưa tìm thấy qua CCCD, tiến hành tra cứu ngay qua Thẻ BHYT có sẵn:', existingCard);
            const codes = [existingCard];
            if (existingCard.length > 10) codes.push(existingCard.slice(-10));
            const foundByCard = await lookupPatientInHis(...codes);
            if (foundByCard) {
              bnFound = foundByCard;
              currentHisPatient = foundByCard;
              applyHisPatientToForm(foundByCard);
              savePatientToPersistentCache(foundByCard);
              triggerBhytCheckFromForm();
              return;
            }
          }

          // Theo dõi liên tục xem HIS hoặc Cổng có nạp Thẻ BHYT / Thông tin bệnh nhân không
          let pollCount = 0;
          let hasAttemptedCardLookup = false;
          if (window._cccdPollInterval) {
            clearInterval(window._cccdPollInterval);
            window._cccdPollInterval = null;
          }
          window._cccdPollInterval = setInterval(async () => {
            pollCount++;
            const curMayte = (document.getElementById('mayte')?.value || '').trim();
            const curCard = (document.getElementById('sobhyt')?.value || '').trim().replace(/\s+/g, '').toUpperCase();
            const curHoten = (document.getElementById('hoten')?.value || '').trim();
            const curNamsinh = (document.getElementById('namsinh')?.value || '').trim();

            if (!hasAttemptedCardLookup && curCard && curCard.length >= 10 && !curCard.includes('|') && (!curMayte || curMayte === '0')) {
              hasAttemptedCardLookup = true;
              console.log('[BHYT Extension] Phát hiện Thẻ BHYT sau khi nhập CCCD, tự động tra cứu Mã y tế:', curCard);
              await autoLookupPatientByCardIfNeeded(curCard);
            }

            if (!isChecking && curHoten && (curNamsinh || curCard)) {
              if (window._cccdPollInterval) {
                clearInterval(window._cccdPollInterval);
                window._cccdPollInterval = null;
              }
              triggerBhytCheckFromForm();
              return;
            }

            if (pollCount >= 10 || (curMayte && curMayte !== '0' && curCard)) {
              if (window._cccdPollInterval) {
                clearInterval(window._cccdPollInterval);
                window._cccdPollInterval = null;
              }
            }
          }, 300);

          // Fallback sau 1500ms nếu form vẫn hoàn toàn trống
          setTimeout(() => {
            if (isChecking) return;
            const hotenVal = (document.getElementById('hoten')?.value || '').trim();
            const namsinhVal = (document.getElementById('namsinh')?.value || '').trim();
            const sobhytVal = (document.getElementById('sobhyt')?.value || '').trim();

            if (!hotenVal && !namsinhVal && !sobhytVal) {
              const existingBox = document.getElementById('bhytExtResultContainer');
              const hasSuccessResult = existingBox && existingBox.querySelector('.bhyt-ext-fieldset[style*="22c55e"], .bhyt-ext-fieldset[style*="10b981"]');
              if (!hasSuccessResult) {
                renderErrorBanner('⚠️ Bệnh nhân mới chưa có thông tin trong HIS. Vui lòng nhập Họ tên và Ngày sinh (hoặc quét mã QR trên CCCD) để thực hiện Kiểm tra BHYT.');
              }
            }
          }, 1500);
        }
      }
    };

    const attachHandlersToInput = (inp) => {
      if (!inp || inp.dataset.bhytCccdEventsAttached === 'true') return;
      inp.dataset.bhytCccdEventsAttached = 'true';

      attachCccdMax12Enforcement(inp);

      inp.addEventListener('input', () => {
        if (isClearingForm) return;
        const val = (inp.value || '').trim();

        // Đồng bộ giữa cccdEl và txtInp (nếu có EasyUI)
        if (inp !== cccdEl) {
          cccdEl.value = inp.value;
        } else if (txtInp && txtInp !== cccdEl) {
          txtInp.value = inp.value;
        }

        // Quét QR CCCD hoặc Thẻ giấy BHYT (có dấu '|')
        if (val.includes('|')) {
          updateCccdCounter(val);
          clearTimeout(qrScanDebounceTimer);
          // Hỗ trợ trọn vẹn máy quét barcode phần cứng truyền chuỗi dài (kể cả CCCD trẻ em có Họ tên Cha, Mẹ):
          // Nếu chuỗi đang kết thúc bằng dấu '|' (đang trong quá trình truyền trường tiếp theo), kéo dài debounce để nhận đủ toàn bộ chuỗi
          const debounceMs = val.endsWith('|') ? 450 : 350;
          qrScanDebounceTimer = setTimeout(() => {
            const currentVal = (inp.value || '').trim();
            if (currentVal.includes('|') && isAnyCompleteQr(currentVal)) {
              handleQrScan(currentVal, inp);
            }
          }, debounceMs);
          return;
        }

        // Nhập tay không quá 12 số CCCD: chỉ giữ tối đa 12 số
        const digitsOnly = val.replace(/\D/g, '').slice(0, 12);
        if (inp.value !== digitsOnly) {
          const selStart = inp.selectionStart;
          inp.value = digitsOnly;
          if (selStart !== null) {
            try { inp.setSelectionRange(selStart, selStart); } catch (e) {}
          }
        }
        if (inp !== cccdEl) cccdEl.value = digitsOnly;
        if (txtInp && inp !== txtInp) txtInp.value = digitsOnly;

        updateCccdCounter(digitsOnly);
        if (digitsOnly.length === 12) {
          syncQuocTich('01');
        }
      });

      inp.addEventListener('keyup', () => {
        if (!isClearingForm) updateCccdCounter(inp.value);
      });

      inp.addEventListener('change', () => {
        if (!isClearingForm) updateCccdCounter(inp.value);
      });

      inp.addEventListener('paste', (e) => {
        const pasteText = (e.clipboardData || window.clipboardData)?.getData('text') || '';
        if (pasteText && pasteText.includes('|')) {
          e.preventDefault();
          clearTimeout(qrScanDebounceTimer);
          handleQrScan(pasteText, inp);
          return;
        }
        // Dán số thông thường: chỉ lấy tối đa 12 chữ số
        e.preventDefault();
        const digits = pasteText.replace(/\D/g, '').slice(0, 12);
        inp.value = digits;
        if (inp !== cccdEl) cccdEl.value = digits;
        if (txtInp && inp !== txtInp) txtInp.value = digits;
        updateCccdCounter(digits);
        inp.dispatchEvent(new Event('input', { bubbles: true }));
        inp.dispatchEvent(new Event('change', { bubbles: true }));
      });

      // Chỉ lắng nghe keydown, KHÔNG nghe keypress để tránh kích hoạt 2 lần cho 1 lần bấm Enter
      inp.addEventListener('keydown', handleEnterKey, true);
    };

    attachHandlersToInput(cccdEl);
    if (txtInp && txtInp !== cccdEl) {
      attachHandlersToInput(txtInp);
    }
  }

  // Xóa toàn bộ khối thông tin thẻ BHYT trên form tiếp nhận (Số BHYT, ĐT thẻ, Chuỗi nhận dạng, TL miễn giảm, Từ ngày, Đến ngày, Nơi ĐK)
  let isClearingReceptionBhyt = false;
  function clearReceptionBhytFields(force = false) {
    if (isClearingReceptionBhyt) return;
    // BẢO VỆ TUYỆT ĐỐI: Không xóa hạn thẻ nếu đang kiểm tra hoặc đã có kết quả Cổng BHYT xác thực
    if (!force && (activeVerifiedTuNgay || isChecking || window._bhytIsCheckingOrStreaming)) {
      return;
    }
    isClearingReceptionBhyt = true;

    try {
      lastCheckedMaThe = '';
      currentBhytCardData = null;
      savedPatientBhytResult = null;
      window.__lastBhytVerifiedData = null;
      lastTiepNhanFormSnapshot = null;
      activeVerifiedTuNgay = '';
      activeVerifiedDenNgay = '';

      const sobhytEl = document.getElementById('sobhyt') || document.querySelector('input[name="sobhyt"]');
      if (sobhytEl) {
        delete sobhytEl.dataset.lastAutoLookupCard;
        delete sobhytEl.dataset.lastAutoLookupFailed;
      }

      const clearSingleField = (el) => {
        if (!el) return;
        el.value = '';
        if (window.$) {
          try { window.$(el).val(''); } catch (e) {}
          try { window.$(el).textbox('setValue', ''); } catch (e) {}
          try { window.$(el).combobox('setValue', ''); } catch (e) {}
          try { window.$(el).datebox('setValue', ''); } catch (e) {}
        }
        const tbWrapper = (typeof findEasyUiWrapper === 'function') ? findEasyUiWrapper(el) : null;
        if (tbWrapper) {
          tbWrapper.querySelectorAll('.textbox-text, .combo-text, .datebox-text').forEach((txtInp) => {
            if (txtInp && txtInp !== el) {
              txtInp.value = '';
              try { txtInp.dispatchEvent(new Event('input', { bubbles: true })); } catch (e) {}
              try { txtInp.dispatchEvent(new Event('change', { bubbles: true })); } catch (e) {}
            }
          });
        }
        try { el.dispatchEvent(new Event('input', { bubbles: true })); } catch (e) {}
        try { el.dispatchEvent(new Event('change', { bubbles: true })); } catch (e) {}

        el.classList.remove('bhyt-ext-field-success', 'bhyt-ext-field-mismatch');
        el.style.removeProperty('background-color');
        el.style.removeProperty('border-color');
        el.style.removeProperty('border-width');
        el.style.removeProperty('color');
        if (typeof removeTick === 'function') removeTick(el);
        if (typeof suamauinput === 'function') suamauinput(el, 4);
        if (el.parentNode) {
          const badge = el.parentNode.querySelector(`.bhyt-ext-tick-${el.id || el.name}`);
          if (badge) badge.remove();
        }
      };

      const fieldsToClear = [
        '#chuoinhandang', 'input[name="chuoinhandang"]',
        '#chuoinhandang_hc', 'input[name="chuoinhandang_hc"]',
        '#chuoind', 'input[name="chuoind"]',
        '#chuoind_hc', 'input[name="chuoind_hc"]',
        '#txt_chuoinhandang', 'input[name="txt_chuoinhandang"]',
        '#suatt_chuoinhandang', 'input[name="suatt_chuoinhandang"]',
        '#sua_chuoinhandang', 'input[name="sua_chuoinhandang"]',
        '#tungay', 'input[name="tungay"]', '#gttungay', 'input[name="gttungay"]',
        '#the_tungay', 'input[name="the_tungay"]', '#gtthetu', 'input[name="gtthetu"]', '#gtTheTu',
        '#hanthe_tu', 'input[name="hanthe_tu"]', '#tu_ngay', 'input[name="tu_ngay"]',
        '#txt_tungay', 'input[name="txt_tungay"]', '#suatt_tungay', '#the_tu_ngay', '#han_tu',
        '#denngay', 'input[name="denngay"]', '#gtdenngay', 'input[name="gtdenngay"]',
        '#the_denngay', 'input[name="the_denngay"]', '#gttheden', 'input[name="gttheden"]', '#gtTheDen',
        '#hanthe_den', 'input[name="hanthe_den"]', '#den_ngay', 'input[name="den_ngay"]',
        '#txt_denngay', 'input[name="txt_denngay"]', '#suatt_denngay', '#the_den_ngay', '#han_den',
        '#noidk', '#noidangky', '#noidangkykcb', 'input[name="noidangky"]', 'input[name="noidangkykcb"]',
        '#noidangky_hienthi', 'input[name="noidangky_hienthi"]', '#noidangky_ten', 'input[name="noidangky_ten"]',
        '#madoituongkcb', 'input[name="madoituongkcb"]',
        '#tlmiengiam', 'input[name="tlmiengiam"]', '#tlmiengiam_hc', 'input[name="tlmiengiam_hc"]',
        '#tilemiengiam', 'input[name="tilemiengiam"]', '#tilemiengiam_hc', 'input[name="tilemiengiam_hc"]',
        '#muchuong', 'input[name="muchuong"]', '#muchuong_hc', 'input[name="muchuong_hc"]',
        '#txt_tlmiengiam', 'input[name="txt_tlmiengiam"]', '#suatt_tlmiengiam', '#sua_tlmiengiam',
        '#doituongthe', '#dt_the', '#tendoituongthe', 'input[name="doituongthe"]'
      ];

      fieldsToClear.forEach(sel => {
        document.querySelectorAll(sel).forEach(el => clearSingleField(el));
      });

      if (typeof findChuoiNhanDangInputs === 'function') {
        findChuoiNhanDangInputs().forEach(el => clearSingleField(el));
      }
      if (typeof findTlMienGiamInputs === 'function') {
        findTlMienGiamInputs().forEach(el => clearSingleField(el));
      }
      if (typeof findTuNgayInput === 'function') {
        clearSingleField(findTuNgayInput());
      }
      if (typeof findDenNgayInput === 'function') {
        clearSingleField(findDenNgayInput());
      }

      if (sobhytEl && (!sobhytEl.value || !sobhytEl.value.trim())) {
        clearSingleField(sobhytEl);
      }

      clearResultBoxes();
      updateSobhytCounter('');
      console.log('[BHYT Extension] Đã làm rỗng hoàn toàn các ô phụ thuộc thẻ BHYT (chuoinhandang, tungay, denngay, noidangky, noidangky_hienthi, tlmiengiam).');
    } catch (err) {
      console.warn('[BHYT Extension] Lỗi trong clearReceptionBhytFields:', err);
    } finally {
      setTimeout(() => {
        isClearingReceptionBhyt = false;
      }, 80);
    }
  }

  function setupSobhytListener() {
    const sobhytEl = document.getElementById('sobhyt') || document.querySelector('input[name="sobhyt"]');
    if (!sobhytEl) return;

    ensureSobhytCounter();

    if (sobhytEl.dataset.bhytListenerAttached === 'true') return;
    sobhytEl.dataset.bhytListenerAttached = 'true';
    console.log('[BHYT Extension] Gắn listener thành công vào ô Thẻ BHYT (#sobhyt)');

    const handleSobhytValueChange = (raw) => {
      const v = String(raw !== undefined ? raw : sobhytEl.value || '').trim();
      updateSobhytCounter(v);
      if (!v && !isClearingReceptionBhyt && !isClearingForm) {
        if (sobhytEl && sobhytEl.value) {
          sobhytEl.value = '';
          try { sobhytEl.dispatchEvent(new Event('change', { bubbles: true })); } catch (e) {}
        }
        clearReceptionBhytFields();
      }
    };

    // Lắng nghe trực tiếp trên ô hiển thị EasyUI (.textbox-text) nếu có
    const tbWrapper = (typeof findEasyUiWrapper === 'function') ? findEasyUiWrapper(sobhytEl) : null;
    const txtInp = tbWrapper ? tbWrapper.querySelector('.textbox-text') : null;
    if (txtInp && txtInp !== sobhytEl && !txtInp._sobhytCounterBound) {
      txtInp._sobhytCounterBound = true;
      txtInp.addEventListener('input', () => {
        const val = (txtInp.value || '').trim();
        handleSobhytValueChange(val);
        if (val.includes('|')) {
          clearTimeout(qrScanDebounceTimer);
          const debounceMs = val.endsWith('|') ? 450 : 350;
          qrScanDebounceTimer = setTimeout(() => {
            const currentVal = (txtInp.value || '').trim();
            if (currentVal.includes('|') && isAnyCompleteQr(currentVal)) {
              handleQrScan(currentVal, txtInp);
            }
          }, debounceMs);
        }
      });
      txtInp.addEventListener('keyup', () => handleSobhytValueChange(txtInp.value));
      txtInp.addEventListener('change', () => handleSobhytValueChange(txtInp.value));
      txtInp.addEventListener('blur', () => handleSobhytValueChange(txtInp.value));
      txtInp.addEventListener('paste', (e) => {
        const pasteText = (e.clipboardData || window.clipboardData)?.getData('text') || '';
        if (pasteText && pasteText.includes('|')) {
          e.preventDefault();
          clearTimeout(qrScanDebounceTimer);
          handleQrScan(pasteText, txtInp);
          handleSobhytValueChange(pasteText);
        }
      });
      txtInp.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') {
          const val = (txtInp.value || '').trim();
          if (val.includes('|')) {
            e.preventDefault();
            e.stopPropagation();
            e.stopImmediatePropagation();
            clearTimeout(qrScanDebounceTimer);
            handleQrScan(val, txtInp);
          }
        }
      }, true);
    }

    let sobhytInputDebounce = null;
    sobhytEl.addEventListener('input', () => {
      handleSobhytValueChange(sobhytEl.value);
      if (isClearingReceptionBhyt) return;
      const val = (sobhytEl.value || '').trim();
      // Đối với trường hợp người dùng xóa thẻ BHYT (hoặc thẻ hết hạn người dùng xóa đi):
      // Tự động xóa hoàn toàn toàn bộ vùng thông tin BHYT khoanh đỏ
      if (!val) {
        clearReceptionBhytFields();
        return;
      }
      // Quét QR CCCD hoặc Thẻ giấy BHYT vào ô sobhyt
      if (val.includes('|')) {
        clearTimeout(qrScanDebounceTimer);
        const debounceMs = val.endsWith('|') ? 450 : 350;
        qrScanDebounceTimer = setTimeout(() => {
          const currentVal = (sobhytEl.value || '').trim();
          if (currentVal.includes('|') && isAnyCompleteQr(currentVal)) {
            handleQrScan(currentVal, sobhytEl);
          }
        }, debounceMs);
        return;
      }

      // Tự động tra cứu Mã y tế khi ô Thẻ BHYT nhận đủ mã thẻ (>= 10 ký tự)
      if (val.length >= 10) {
        clearTimeout(sobhytInputDebounce);
        sobhytInputDebounce = setTimeout(() => {
          autoLookupPatientByCardIfNeeded(val);
        }, 300);
      }
    });

    sobhytEl.addEventListener('keyup', () => {
      handleSobhytValueChange(sobhytEl.value);
    });

    sobhytEl.addEventListener('change', () => {
      handleSobhytValueChange(sobhytEl.value);
      if (isClearingReceptionBhyt) return;
      const val = (sobhytEl.value || '').trim();
      if (!val) {
        clearReceptionBhytFields();
      } else if (val.length >= 10 && !val.includes('|')) {
        autoLookupPatientByCardIfNeeded(val);
      }
    });

    sobhytEl.addEventListener('blur', () => {
      handleSobhytValueChange(sobhytEl.value);
      const val = (sobhytEl.value || '').trim();
      if (!val) {
        clearReceptionBhytFields();
      }
    });

    sobhytEl.addEventListener('paste', (e) => {
      const pasteText = (e.clipboardData || window.clipboardData)?.getData('text') || '';
      if (pasteText && pasteText.includes('|')) {
        e.preventDefault();
        clearTimeout(qrScanDebounceTimer);
        handleQrScan(pasteText, sobhytEl);
        handleSobhytValueChange(pasteText);
        return;
      }
      if (pasteText) {
        setTimeout(() => handleSobhytValueChange(sobhytEl.value || pasteText), 50);
      }
      if (pasteText && pasteText.trim().length >= 10) {
        setTimeout(() => {
          autoLookupPatientByCardIfNeeded((sobhytEl.value || pasteText).trim());
        }, 100);
      }
    });

    const handleSobhytEnter = (e) => {
      if (!e.isTrusted) return;
      if (e.key === 'Enter') {
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();
        clearTimeout(qrScanDebounceTimer);
        const val = (sobhytEl.value || '').trim();
        if (val.includes('|')) {
          handleQrScan(val, sobhytEl);
        } else {
          const currentThe = currentHisPatient?.SO_THE_BAOHIEM_YTE || currentHisPatient?.SO_THE_BHYT;
          if (currentThe && val.toUpperCase() !== currentThe.toUpperCase()) {
            clearPreviousPatientForm(false);
            setFieldSuccess('sobhyt', val.toUpperCase());
          }
          const codes = [val];
          if (val.length > 10) codes.push(val.slice(-10));
          lookupPatientInHis(...codes).finally(() => {
            triggerBhytCheckFromForm();
          });
        }
      }
    };
    sobhytEl.addEventListener('keypress', handleSobhytEnter, true);
    sobhytEl.addEventListener('keydown', handleSobhytEnter, true);
  }

  function setupChuoiNhanDangListener() {
    // 1. Tự động tô xanh Chuỗi nhận dạng & TL miễn giảm khi người dùng nhập hoặc thay đổi Số thẻ BHYT (#sobhyt)
    const sobhytEl = document.getElementById('sobhyt') || document.querySelector('input[name="sobhyt"]');
    if (sobhytEl && !sobhytEl._cndSyncBound) {
      sobhytEl._cndSyncBound = true;
      const syncFromSobhyt = () => {
        if (isClearingReceptionBhyt || isClearingForm) return;
        const v = (sobhytEl.value || '').trim().replace(/\s+/g, '').toUpperCase();
        if (v.length >= 3) {
          fillAndHighlightChuoiNhanDang(v);
          fillAndHighlightTlMienGiam(v, currentBhytCardData?.mucHuong);
        } else if (!v) {
          clearReceptionBhytFields();
        }
      };
      sobhytEl.addEventListener('input', syncFromSobhyt);
      sobhytEl.addEventListener('change', syncFromSobhyt);
      sobhytEl.addEventListener('blur', syncFromSobhyt);
    }

    // Tự động tô xanh Chuỗi nhận dạng & TL miễn giảm khi HIS hoặc người dùng điền giá trị
    ['chuoinhandang', 'tlmiengiam'].forEach((fId) => {
      const fieldEl = document.getElementById(fId) || document.querySelector(`input[name="${fId}"]`);
      if (fieldEl && !fieldEl._bhytGreenGuardBound) {
        fieldEl._bhytGreenGuardBound = true;
        const onHisChange = () => {
          if (!isTiepNhanPage() || isClearingForm || isClearingReceptionBhyt) return;
          const sobhytVal = (document.getElementById('sobhyt')?.value || '').trim();
          if (!sobhytVal) return;
          if ((fieldEl.value || '').trim()) {
            highlightFieldSuccessOnly(fieldEl);
          }
        };
        fieldEl.addEventListener('input', onHisChange);
        fieldEl.addEventListener('change', onHisChange);
        fieldEl.addEventListener('blur', onHisChange);
      }
    });

    // 2. Lắng nghe ô Chuỗi nhận dạng (#chuoinhandang)
    const el = document.getElementById('chuoinhandang') || document.querySelector('input[name="chuoinhandang"], [id*="chuoinhandang"], [id*="chuoi_nhandang"]');
    if (!el || el.dataset.bhytListenerAttached === 'true') return;

    el.dataset.bhytListenerAttached = 'true';
    console.log('[BHYT Extension] Gắn listener thành công vào ô Chuỗi nhận dạng (#chuoinhandang)');

    el.addEventListener('input', () => {
      const val = (el.value || '').trim();
      if (val.includes('|')) {
        clearTimeout(qrScanDebounceTimer);
        if (isAnyCompleteQr(val)) {
          qrScanDebounceTimer = setTimeout(() => {
            handleQrScan(el.value || val, el);
          }, 80);
        } else {
          qrScanDebounceTimer = setTimeout(() => {
            const currentVal = (el.value || '').trim();
            if (currentVal.includes('|')) {
              handleQrScan(currentVal, el);
            }
          }, 250);
        }
      }
    });

    el.addEventListener('paste', (e) => {
      const pasteText = (e.clipboardData || window.clipboardData)?.getData('text') || '';
      if (pasteText && pasteText.includes('|')) {
        e.preventDefault();
        clearTimeout(qrScanDebounceTimer);
        handleQrScan(pasteText, el);
      }
    });

    el.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        const val = (el.value || '').trim();
        if (val.includes('|')) {
          e.preventDefault();
          clearTimeout(qrScanDebounceTimer);
          handleQrScan(val, el);
        }
      }
    });
  }

  // Tìm ô text input thực tế của Ngày sinh / Năm sinh trên form (loại trừ mọi checkbox)
  // Kiểm tra loại trừ triệt để: không bao giờ gán ngày sinh vào các ô tuổi, tháng, ngày, giờ sinh, họ tên...
  function isExcludedFromNgaySinh(el) {
    if (!el) return true;
    if (el.type === 'checkbox' || el.type === 'radio' || el.type === 'hidden') return true;
    const id = (el.id || '').toLowerCase();
    const name = (el.name || '').toLowerCase();

    // TUYỆT ĐỐI LOẠI TRỪ CÁC Ô TUỔI, THÁNG, NGÀY, GIỜ SINH, GIỚI TÍNH, HỌ TÊN, CCCD, BHYT, ĐỊA CHỈ...
    if (id === 'tuoi' || name === 'tuoi' || id === 'txt_tuoi' || id === 'txttuoi' || name === 'txt_tuoi') return true;
    if (id === 'thang' || name === 'thang' || id === 'txt_thang' || id === 'txtthang' || name === 'txt_thang') return true;
    if (id === 'ngay' || name === 'ngay' || id === 'txt_ngay' || id === 'txtngay' || name === 'txt_ngay') return true;
    if (id.includes('gio') || name.includes('gio') || id === 'gio-sinh-cv130') return true;
    if (id.includes('gioitinh') || name.includes('gioitinh') || id.includes('cbgioitinh')) return true;
    if (id.includes('hoten') || name.includes('hoten') || id.includes('tenbn')) return true;
    if (id.includes('socmt') || id.includes('cccd') || id.includes('cmnd')) return true;
    if (id.includes('sobhyt') || name.includes('sobhyt')) return true;
    if (id.includes('diachi') || id.includes('sonha')) return true;
    if (id.includes('mayte') || id.includes('mabn')) return true;
    if (id.includes('sodt') || id.includes('dienthoai')) return true;
    if (id.includes('nghenghiep') || id.includes('dantoc') || id.includes('quoctich')) return true;
    if (id.includes('chinamsinh') || name.includes('chinamsinh') || id.includes('hien_namsinh')) return true;

    return false;
  }

  // Tìm ô text input thực tế của Ngày sinh / Năm sinh trên form (loại trừ mọi checkbox & ô tuổi, tháng, ngày)
  function findDobTextInput(scope = document) {
    if (!scope) scope = document;
    const selectors = [
      'input#namsinh',
      'input[name="namsinh"]',
      'input#ngaysinh',
      'input[name="ngaysinh"]',
      'input#txt_namsinh',
      'input#txt_ngaysinh',
      'input#suatt_namsinh',
      'input#suatt_ngaysinh',
      'input#txtNamSinh',
      'input#txtNgaySinh',
      'input#dt_ngaysinh'
    ];
    for (const sel of selectors) {
      try {
        const el = scope.querySelector(sel);
        if (el && !isExcludedFromNgaySinh(el)) return el;
      } catch (e) {}
    }
    return null;
  }

  // =========================================================================
  // BÓC TÁCH VÀ ĐIỀN CHÍNH XÁC VÀO Ô "NGÀY SINH (*)" (KHÔNG ĐỔ SANG CÁC Ô KHÁC)
  // Ưu tiên tuyệt đối ô name="namsinh", id="namsinh" trên form tiếp nhận
  // =========================================================================
  function fillNgaySinhFields(formattedDob, rawDob, scope = document) {
    if (!scope) scope = document;
    let inputVal = String(formattedDob || rawDob || '').trim();
    if (!inputVal) return;

    const currentYear = new Date().getFullYear();

    // Chuẩn hóa ngày sinh dạng DD/MM/YYYY trước
    let dobFull = inputVal;
    if (/^\d{8}$/.test(inputVal)) {
      const p1 = parseInt(inputVal.substring(0, 4), 10);
      const p2 = parseInt(inputVal.substring(4, 8), 10);
      if (p2 >= 1900 && p2 <= currentYear) {
        dobFull = `${inputVal.substring(0, 2)}/${inputVal.substring(2, 4)}/${inputVal.substring(4, 8)}`;
      } else if (p1 >= 1900 && p1 <= currentYear) {
        dobFull = `${inputVal.substring(6, 8)}/${inputVal.substring(4, 6)}/${inputVal.substring(0, 4)}`;
      } else {
        dobFull = `${inputVal.substring(0, 2)}/${inputVal.substring(2, 4)}/${inputVal.substring(4, 8)}`;
      }
    }

    // 0. KIỂM TRA NĂM SINH HỢP LỆ VỀ MẶT SINH HỌC
    // Bóc tách đúng phần năm sinh từ đuôi DD/MM/YYYY hoặc chuỗi năm hợp lệ
    let parsedRawYear = 0;
    if (dobFull.includes('/')) {
      const parts = dobFull.split('/');
      parsedRawYear = parseInt(parts[parts.length - 1], 10) || 0;
    } else {
      const rawYearMatch = dobFull.match(/\b(19\d{2}|20\d{2})\b/);
      parsedRawYear = rawYearMatch ? parseInt(rawYearMatch[0], 10) : 0;
    }

    if (parsedRawYear > currentYear || (parsedRawYear > 0 && parsedRawYear < 1900)) {
      console.warn(`[BHYT Extension] Phát hiện năm sinh bất thường/tương lai (${parsedRawYear}):`, inputVal);
      if (activeVerifiedDob && activeVerifiedDob !== inputVal) {
        const aYearMatch = activeVerifiedDob.match(/\b(19\d{2}|20\d{2})\b/);
        if (aYearMatch) {
          console.log('[BHYT Extension] Khôi phục ngay ngày sinh chuẩn đã xác thực:', activeVerifiedDob);
          inputVal = activeVerifiedDob;
          dobFull = activeVerifiedDob;
        } else {
          return;
        }
      } else if (lastScannedQrDob && lastScannedQrDob !== inputVal) {
        const qYearMatch = lastScannedQrDob.match(/\b(19\d{2}|20\d{2})\b/);
        if (qYearMatch) {
          inputVal = lastScannedQrDob;
          dobFull = lastScannedQrDob;
        } else {
          return;
        }
      } else {
        return; // Từ chối gán năm sinh tương lai không hợp lệ
      }
    }

    const yearMatch = dobFull.match(/\b(19\d{2}|20\d{2})\b/);
    const yearVal = yearMatch ? yearMatch[0] : '';
    const isYearOnly = /^\d{4}$/.test(dobFull) || /^00\/00\/\d{4}$/.test(dobFull);
    // Khi có đầy đủ ngày/tháng/năm từ QR CCCD hoặc Cổng BHXH -> valToSet luôn là DD/MM/YYYY đầy đủ (ví dụ 05/07/1986, 01/01/1974)
    const valToSet = isYearOnly ? (yearVal ? `01/01/${yearVal}` : dobFull) : dobFull;

    // Kiểm tra lại lần cuối năm sinh của valToSet
    const finalYearMatch = valToSet.match(/\b(19\d{2}|20\d{2})\b/);
    const finalYear = finalYearMatch ? parseInt(finalYearMatch[0], 10) : 0;
    if (finalYear > currentYear || (finalYear > 0 && finalYear < 1900)) {
      console.warn(`[BHYT Extension] Hủy bỏ gán valToSet vì năm sinh ${finalYear} không hợp lệ:`, valToSet);
      return;
    }

    // Lưu khóa bảo vệ toàn cục cho phiên bệnh nhân hiện tại
    if (finalYear >= 1900 && finalYear <= currentYear) {
      setVerifiedDob(valToSet);
    }

    console.log('[BHYT Extension] Bóc tách chuỗi gán vào ô Ngày sinh (*):', {
      inputVal,
      dobFull,
      valToSet,
      isYearOnly,
      activeVerifiedDob
    });

    // LẤY CHÍNH XÁC Ô ĐÚNG LÀ NGÀY SINH / NĂM SINH (Ưu tiên tuyệt đối id="namsinh" và name="namsinh")
    const targets = [];
    const exactSelectors = [
      '#namsinh',
      'input[name="namsinh"]',
      '#suatt_namsinh',
      '#ngaysinh',
      'input[name="ngaysinh"]',
      '#suatt_ngaysinh',
      '#txt_namsinh',
      '#txt_ngaysinh',
      '#txtNamSinh',
      '#txtNgaySinh',
      '#dt_ngaysinh'
    ];

    for (const sel of exactSelectors) {
      try {
        const found = scope.querySelectorAll(sel);
        found.forEach((el) => {
          if (el && !isExcludedFromNgaySinh(el) && !targets.includes(el)) {
            targets.push(el);
          }
        });
      } catch (e) {}
    }

    // Nếu không khớp selector ID chuẩn, tìm 1 ô duy nhất
    if (targets.length === 0) {
      const fallback = findDobTextInput(scope);
      if (fallback && !isExcludedFromNgaySinh(fallback)) {
        targets.push(fallback);
      }
    }

    // Hàm áp dụng giá trị vào toàn bộ ô Ngày sinh đã xác định chính xác
    const applyToTargets = () => {
      targets.forEach((el) => {
        try {
          ensureInputEditable(el);

          // Nếu có ngày sinh đầy đủ, mở rộng hoặc gỡ bỏ giới hạn maxlength=4 nếu có
          if (!isYearOnly) {
            if (el.maxLength && el.maxLength < 10) {
              el.maxLength = 10;
            }
            el.removeAttribute('maxlength');
          }

          // 1. Gán native DOM
          el.value = valToSet;

          // 2. Gán qua jQuery & EasyUI plugin (datebox, textbox) kèm cấu hình Parser/Formatter chuẩn dd/mm/yyyy
          const jq = el.ownerDocument?.defaultView?.$ || window.$;
          if (jq) {
            try { jq(el).val(valToSet); } catch (e) {}
          }

          // 3. Đồng bộ trực tiếp visible input của EasyUI Datebox (.textbox-text)
          const tbWrapper = findEasyUiWrapper(el);
          if (tbWrapper) {
            tbWrapper.classList.add('bhyt-ext-field-success');
            tbWrapper.style.backgroundColor = '#ddf5dd';
            tbWrapper.style.borderColor = '#28a745';
            const txtInp = tbWrapper.querySelector('.textbox-text, .combo-text, .datebox-text');
            if (txtInp && txtInp !== el) {
              ensureInputEditable(txtInp);
              if (!isYearOnly) {
                if (txtInp.maxLength && txtInp.maxLength < 10) txtInp.maxLength = 10;
                txtInp.removeAttribute('maxlength');
              }
              txtInp.value = valToSet;
              txtInp.dispatchEvent(new Event('input', { bubbles: true }));
              txtInp.dispatchEvent(new Event('change', { bubbles: true }));
              txtInp.classList.add('bhyt-ext-field-success');
              txtInp.style.backgroundColor = '#ddf5dd';
              txtInp.style.borderColor = '#28a745';
              txtInp.style.color = '#0b4f1b';
            }
            const valInp = tbWrapper.querySelector('.textbox-value, .combo-value');
            if (valInp && valInp !== el) {
              valInp.value = valToSet;
            }
          }

          // 4. Phát sự kiện DOM chuẩn (KHÔNG gọi blur() để tránh mask plugin reset)
          el.dispatchEvent(new Event('input', { bubbles: true }));
          el.dispatchEvent(new Event('change', { bubbles: true }));

          // 5. Tô màu xanh lá và đánh dấu tick (✔) theo đúng chuẩn v1.2.82
          el.classList.add('bhyt-ext-field-success');
          el.classList.remove('bhyt-ext-field-mismatch');
          el.style.backgroundColor = '#ddf5dd';
          el.style.borderColor = '#28a745';
          el.style.color = '#0b4f1b';
          markTick(tbWrapper || el);
        } catch (err) {
          console.log('[BHYT Extension] Lỗi khi gán ngày sinh:', err);
        }
      });

      // Đồng bộ trực tiếp vào Main World qua jQuery
      try {
        const evt = new CustomEvent('bhyt-ext-fill-field', {
          bubbles: true,
          composed: true,
          detail: { field: 'namsinh', value: valToSet }
        });
        document.dispatchEvent(evt);
        window.dispatchEvent(evt);
      } catch (e) {}
    };

    // Xử lý trạng thái Checkbox "Chỉ có năm sinh": nếu có ngày sinh đầy đủ thì uncheck trước
    setNamsinhCheckboxState(isYearOnly, scope);

    applyToTargets();

    // Gia cố chống HIS can thiệp ngầm hoặc reset lại trường ngày sinh một cách êm dịu, không phát lại sự kiện gây giật lag
    const reinforceDobSilent = () => {
      targets.forEach((el) => {
        if (!el || isExcludedFromNgaySinh(el)) return;
        if ((el.value || '').trim() !== valToSet) {
          el.value = valToSet;
          const tbWrapper = findEasyUiWrapper(el);
          if (tbWrapper) {
            const txtInp = tbWrapper.querySelector('.textbox-text, .combo-text, .datebox-text');
            if (txtInp && (txtInp.value || '').trim() !== valToSet) {
              txtInp.value = valToSet;
            }
          }
        }
        if (!el.classList.contains('bhyt-ext-field-success')) {
          el.classList.add('bhyt-ext-field-success');
          el.classList.remove('bhyt-ext-field-mismatch');
          el.style.backgroundColor = '#ddf5dd';
          el.style.borderColor = '#28a745';
          el.style.color = '#0b4f1b';
        }
        const tbWrapper = findEasyUiWrapper(el);
        if (tbWrapper) {
          if (!tbWrapper.classList.contains('bhyt-ext-field-success')) {
            tbWrapper.classList.add('bhyt-ext-field-success');
            tbWrapper.style.backgroundColor = '#ddf5dd';
            tbWrapper.style.borderColor = '#28a745';
          }
          const txtInp = tbWrapper.querySelector('.textbox-text, .combo-text, .datebox-text');
          if (txtInp && !txtInp.classList.contains('bhyt-ext-field-success')) {
            txtInp.classList.add('bhyt-ext-field-success');
            txtInp.classList.remove('bhyt-ext-field-mismatch');
            txtInp.style.backgroundColor = '#ddf5dd';
            txtInp.style.borderColor = '#28a745';
            txtInp.style.color = '#0b4f1b';
          }
        }
        markTick(tbWrapper || el);
      });
    };
    setTimeout(reinforceDobSilent, 300);
    setTimeout(reinforceDobSilent, 1000);

    // Tính tuổi và điền CHÍNH XÁC vào ô Tuổi (#tuoi)
    const ageObj = calculateAge(valToSet);
    if (ageObj && ageObj.tuoi !== null) {
      setFieldSuccess('tuoi', ageObj.tuoi);
      if (ageObj.isUnder6) {
        if (ageObj.thang) setFieldSuccess('thang', ageObj.thang);
        if (ageObj.ngay) setFieldSuccess('ngay', ageObj.ngay);
      } else {
        // Trên 6 tuổi: Nếu ô Tháng hoặc Ngày còn sót số rác > 0 từ bệnh nhân trẻ em trước đó thì xóa sạch một cách êm ái
        // TUYỆT ĐỐI KHÔNG dispatch sự kiện 'change' trên ô Tháng để tránh xung đột với VNPT HIS gây giật lag và nhấp nháy ô Tháng
        const thangEl = document.getElementById('thang') || document.querySelector('input[name="thang"]');
        if (thangEl && thangEl.value && parseInt(thangEl.value, 10) > 0) {
          thangEl.value = '';
          if (window.$) { try { window.$(thangEl).val(''); } catch (e) {} }
        }
        const ngayEl = document.getElementById('ngay') || document.querySelector('input[name="ngay"]');
        if (ngayEl && ngayEl.value && parseInt(ngayEl.value, 10) > 0) {
          ngayEl.value = '';
          if (window.$) { try { window.$(ngayEl).val(''); } catch (e) {} }
        }
      }
    }
  }

  // =========================================================================
  // BẢO VỆ TOÀN VẸN NGÀY SINH & ĐỊA CHỈ CV30 (CHỐNG HIS GHI ĐÈ LỖI/RÁC DỮ LIỆU)
  // Ngăn chặn 100% tình trạng HIS tự ý đổ năm sinh tương lai (2088) hoặc xã sai
  // =========================================================================
  function enforceVerifiedDobAndAddress() {
    if (!isTiepNhanPage()) return;
    const currentYear = new Date().getFullYear();

    // 1. Kiểm tra và bảo vệ ô Ngày sinh (*)
    let correctDob = activeVerifiedDob || lastScannedQrDob || (currentBhytCardData ? formatBhxhDate(currentBhytCardData.ngaySinh) : '');
    // Xác thực tính hợp lệ của correctDob: phải chứa năm sinh trong khoảng 1900 đến năm hiện tại
    if (correctDob) {
      const yM = correctDob.match(/\b(19\d{2}|20\d{2})\b/);
      if (!yM) {
        correctDob = '';
      }
    }
    const candidateDobEls = [
      document.getElementById('namsinh'),
      document.querySelector('input[name="namsinh"]'),
      document.getElementById('suatt_namsinh'),
      document.getElementById('ngaysinh'),
      document.querySelector('input[name="ngaysinh"]')
    ];

    for (const el of candidateDobEls) {
      if (isUserEditingDob()) break; // Người dùng đang tự nhập ngày sinh -> không khôi phục
      if (!el || isExcludedFromNgaySinh(el)) continue;
      const curVal = (el.value || '').trim();
      const fourDigitMatch = curVal.match(/\b\d{4}\b/);
      const any4Digit = fourDigitMatch ? parseInt(fourDigitMatch[0], 10) : 0;

      // CHỈ xử lý khi năm sinh thực sự bị lỗi kỹ thuật: năm sinh tương lai (> currentYear như 2088)
      // TUYỆT ĐỐI không coi các số khác (như 1506) là lỗi năm sinh vì đó có thể là ngày/tháng
      const isFutureYear = any4Digit > currentYear;
      const isBlankOrPlaceholder = !curVal || curVal === '' || curVal.toLowerCase() === 'dd/mm/yyyy';

      if (isBlankOrPlaceholder && correctDob) {
        const hasActivePatient = Boolean(
          (document.getElementById('hoten')?.value || '').trim() ||
          (getCccdInput()?.value || '').trim() ||
          (document.getElementById('sobhyt')?.value || '').trim()
        );
        if (hasActivePatient) {
          console.warn('[BHYT Extension] Liveness Guard: Phát hiện ô Ngày sinh bị mất/placeholder dd/mm/yyyy, khôi phục lại:', correctDob);
          fillNgaySinhFields(correctDob, correctDob);
          break;
        }
      }

      if (isFutureYear) {
        if (correctDob) {
          const cYearMatch = correctDob.match(/\b(19\d{2}|20\d{2})\b/);
          const cYear = cYearMatch ? parseInt(cYearMatch[0], 10) : 0;
          if (cYear >= 1900 && cYear <= currentYear) {
            console.warn(`[BHYT Extension] Liveness Guard: Phát hiện năm sinh tương lai (${curVal}), khôi phục về giá trị chuẩn:`, correctDob);
            fillNgaySinhFields(correctDob, correctDob);
            break;
          }
        }
        // Năm sinh trong tương lai (như 2088) -> dọn sạch ô bị lỗi
        el.value = '';
        el.dispatchEvent(new Event('input', { bubbles: true }));
        el.dispatchEvent(new Event('change', { bubbles: true }));
      }
    }

    // 2. Bảo vệ ô Địa chỉ (#diachi) từ Cổng BHXH nếu bị xóa trống hoặc bị HIS ghi đè
    if (activeVerifiedAddress) {
      const diachiEl = document.getElementById('diachi') || document.querySelector('input[name="diachi"]');
      if (diachiEl && (!diachiEl.value?.trim() || (diachiEl.value.trim() !== activeVerifiedAddress && !diachiEl._userManuallyEdited))) {
        diachiEl.value = activeVerifiedAddress;
        markTick(diachiEl);
        diachiEl.classList.remove('bhyt-ext-field-mismatch');
        diachiEl.classList.add('bhyt-ext-field-success');
      }
    }

    // 3. Bảo vệ Số thẻ BHYT, Hạn thẻ Từ ngày - Đến ngày và Nơi ĐKKCB từ Cổng BHXH
    enforceVerifiedBhytCardFields();
  }

  // Bảo vệ thông tin Thẻ BHYT, Hạn thẻ và Nơi ĐKKCB từ Cổng BHXH (chống script HIS ghi đè dữ liệu cũ)
  function enforceVerifiedBhytCardFields() {
    if (!isTiepNhanPage() || (!currentBhytCardData && !activeVerifiedTuNgay && !activeVerifiedDenNgay)) return;
    const d = currentBhytCardData || {};
    const ghiChu = d.ghiChu || '';
    const eff = currentBhytCardData ? resolveEffectiveBhytCardForReception(d, ghiChu, userForcedNewBhytCard) : {};
    const cleanMaThe = eff.maThe || (document.getElementById('sobhyt')?.value || '').trim();
    const tuNgay = eff.tuNgay || activeVerifiedTuNgay;
    const denNgay = eff.denNgay || activeVerifiedDenNgay;
    const maDkbd = eff.maDkbd;

    // 1. Bảo vệ số thẻ BHYT (#sobhyt) & Chuỗi nhận dạng (#chuoinhandang)
    if (cleanMaThe) {
      const sobhytEl = document.getElementById('sobhyt') || document.querySelector('input[name="sobhyt"]');
      if (sobhytEl) {
        const curVal = (sobhytEl.value || '').replace(/\s+/g, '').toUpperCase();
        if (curVal && curVal !== cleanMaThe) {
          console.warn(`[BHYT Extension] Liveness Guard: Phát hiện số thẻ BHYT bị HIS ghi đè (${curVal}), khôi phục về thẻ mới từ Cổng:`, cleanMaThe);
          setFieldSuccess('sobhyt', cleanMaThe);
        }
      }
      if (cleanMaThe.length >= 3) {
        fillAndHighlightChuoiNhanDang(cleanMaThe);
        fillAndHighlightTlMienGiam(cleanMaThe, d.mucHuong);
      }
    }

    // 2. Bảo vệ Hạn thẻ Từ ngày (#tungay)
    const effectiveTu = tuNgay || activeVerifiedTuNgay;
    if (effectiveTu) {
      const tuEl = findTuNgayInput();
      if (tuEl) {
        const curTu = formatBhxhDate((tuEl.value || '').trim());
        const tbWrap = findEasyUiWrapper(tuEl);
        const txtVal = tbWrap ? formatBhxhDate((tbWrap.querySelector('.textbox-text')?.value || '').trim()) : '';
        if ((curTu && curTu !== effectiveTu) || (txtVal && txtVal !== effectiveTu)) {
          console.warn(`[BHYT Extension] Liveness Guard: Phát hiện Từ ngày bị HIS ghi đè (${curTu || txtVal}), khôi phục về Cổng:`, effectiveTu);
          setFieldSuccess('tungay', effectiveTu);
        }
      }
    }

    // 3. Bảo vệ Hạn thẻ Đến ngày (#denngay)
    const effectiveDen = denNgay || activeVerifiedDenNgay;
    if (effectiveDen) {
      const denEl = findDenNgayInput();
      if (denEl) {
        const curDen = formatBhxhDate((denEl.value || '').trim());
        const tbWrap = findEasyUiWrapper(denEl);
        const txtVal = tbWrap ? formatBhxhDate((tbWrap.querySelector('.textbox-text')?.value || '').trim()) : '';
        if ((curDen && curDen !== effectiveDen) || (txtVal && txtVal !== effectiveDen)) {
          console.warn(`[BHYT Extension] Liveness Guard: Phát hiện Đến ngày bị HIS ghi đè (${curDen || txtVal}), khôi phục về Cổng:`, effectiveDen);
          setFieldSuccess('denngay', effectiveDen);
        }
      }
    }

    // 4. Bảo vệ Nơi ĐK KCB BĐ (#noidangky)
    if (maDkbd) {
      const dkEl = document.getElementById('noidangky') || document.querySelector('input[name="noidangky"]');
      if (dkEl) {
        const curDk = (dkEl.value || '').trim();
        // Chỉ khôi phục khi ô Nơi ĐKKCB bị xóa trắng hoặc bằng 0; TUYỆT ĐỐI KHÔNG ghi đè khi HIS hoặc người dùng đã chọn điểm trạm/nơi KCB hợp lệ
        if (!curDk || curDk === '0') {
          console.warn(`[BHYT Extension] Liveness Guard: Ô Nơi ĐKKCB bị trống (0), khôi phục về Cổng:`, maDkbd);
          setFieldSuccess('noidangky', maDkbd);
        }
      }
    }

    // 5. Bảo vệ Số điện thoại (#sodt) từ hồ sơ bệnh nhân trong HIS nếu ô bị reset/trống
    const expectedSdt = extractPatientSdt(currentHisPatient) || extractPatientSdt(lastSelectedGridPatient);
    if (expectedSdt) {
      const elSdt = findSdtInput();
      if (elSdt && (!elSdt.value || !elSdt.value.trim())) {
        elSdt.value = expectedSdt;
        setFieldSuccess(elSdt, expectedSdt);
        if (window.$) try { window.$(elSdt).val(expectedSdt).trigger('input').trigger('change'); } catch (e) {}
      }
    }
  }

  // Trích xuất ngày sinh / năm sinh chuẩn xác từ form hoặc bộ nhớ fallback đa tầng
  function extractTiepNhanDob() {
    // Lớp 1: Đọc từ các ô text input ngày sinh trên form tiếp nhận
    const dobInput = findDobTextInput(document);
    if (dobInput) {
      let v = (dobInput.value || '').replace(/\s+\d{1,2}:\d{2}(:\d{2})?.*$/, '').trim();
      v = v.replace(/^[^\d]+/, '').trim();
      if (v && v.toLowerCase() !== 'on' && v.toLowerCase() !== 'off' && v.toLowerCase() !== 'dd/mm/yyyy' && v !== '__/__/____' && /\d/.test(v)) {
        if (/^\d{1,2}[\/.-]\d{1,2}[\/.-]\d{4}$/.test(v) || /^\d{4}$/.test(v)) {
          return v;
        }
      }
    }

    // Lớp 2: Quét tất cả các ô input có thể
    const candidateSelectors = [
      'input#namsinh:not([type="checkbox"]):not([type="radio"])',
      'input[name="namsinh"]:not([type="checkbox"]):not([type="radio"])',
      'input#ngaysinh:not([type="checkbox"]):not([type="radio"])',
      'input[name="ngaysinh"]:not([type="checkbox"]):not([type="radio"])',
      'input#suatt_namsinh:not([type="checkbox"]):not([type="radio"])',
      'input#suatt_ngaysinh:not([type="checkbox"]):not([type="radio"])',
      'input#txt_namsinh:not([type="checkbox"]):not([type="radio"])',
      'input#txt_ngaysinh:not([type="checkbox"]):not([type="radio"])',
      'input#txtNamSinh:not([type="checkbox"]):not([type="radio"])',
      'input#txtNgaySinh:not([type="checkbox"]):not([type="radio"])',
      '.datebox-text',
      '.textbox-text'
    ];
    for (const sel of candidateSelectors) {
      const els = document.querySelectorAll(sel);
      for (const el of els) {
        let v = (el.value || '').replace(/\s+\d{1,2}:\d{2}(:\d{2})?.*$/, '').trim();
        v = v.replace(/^[^\d]+/, '').trim();
        if (v && v.toLowerCase() !== 'on' && v.toLowerCase() !== 'off' && v.toLowerCase() !== 'dd/mm/yyyy' && v !== '__/__/____' && /\d/.test(v)) {
          if (/^\d{1,2}[\/.-]\d{1,2}[\/.-]\d{4}$/.test(v) || /^\d{4}$/.test(v)) {
            return v;
          }
        }
      }
    }

    // Lớp 3: Dữ liệu BHYT đã kiểm tra thành công trước đó trong cùng phiên
    if (currentBhytCardData && currentBhytCardData.ngaySinh) {
      const cardDob = String(currentBhytCardData.ngaySinh).replace(/\s+\d{1,2}:\d{2}(:\d{2})?.*$/, '').trim();
      if (cardDob && cardDob.toLowerCase() !== 'on' && /\d/.test(cardDob)) {
        console.log('[BHYT Extension] Trích xuất ngày sinh từ currentBhytCardData:', cardDob);
        return cardDob;
      }
    }

    // Lớp 4: Dữ liệu bệnh nhân trong HIS đã nạp
    if (currentHisPatient) {
      const hisDob = currentHisPatient.NGAY_SINH || currentHisPatient.ngaysinh || currentHisPatient.NGAYSINH || currentHisPatient.NAMSINH;
      if (hisDob) {
        const fmtDob = formatBhxhDate(hisDob);
        if (fmtDob && fmtDob.toLowerCase() !== 'on' && /\d/.test(fmtDob)) {
          console.log('[BHYT Extension] Trích xuất ngày sinh từ currentHisPatient:', fmtDob);
          return fmtDob;
        }
      }
    }

    // Lớp 5: Fallback tính năm sinh từ ô Tuổi (#tuoi) hoặc Tháng (#thang) trên form
    const thangEl = document.getElementById('thang') || document.querySelector('input[name="thang"]') || document.getElementById('txt_thang');
    const thangVal = (thangEl?.value || '').trim();
    const thangNum = parseInt(thangVal, 10);

    const tuoiEl = document.getElementById('tuoi') || document.querySelector('input[name="tuoi"]') || document.getElementById('txt_tuoi');
    const tuoiVal = (tuoiEl?.value || '').trim();
    const tuoiNum = parseInt(tuoiVal, 10);

    if (!isNaN(thangNum) && thangNum > 0 && (isNaN(tuoiNum) || tuoiNum === 0 || thangNum >= 12)) {
      const years = Math.floor(thangNum / 12);
      const estimatedYear = String(new Date().getFullYear() - years);
      console.log('[BHYT Extension] Trích xuất năm sinh fallback từ Tháng tuổi:', estimatedYear);
      return estimatedYear;
    }

    if (tuoiNum > 0 && tuoiNum <= 130) {
      const estimatedYear = String(new Date().getFullYear() - tuoiNum);
      console.log('[BHYT Extension] Trích xuất năm sinh fallback từ Tuổi:', estimatedYear);
      return estimatedYear;
    }

    // Lớp 6: Fallback tính năm sinh từ số CCCD (12 số)
    const cccdEl = getCccdInput();
    const cccdVal = (cccdEl?.value || '').replace(/\D/g, '');
    if (cccdVal.length === 12) {
      const cGender = parseInt(cccdVal.charAt(3), 10);
      const cYear = cccdVal.substring(4, 6);
      let century = 1900;
      if (cGender === 0 || cGender === 1) century = 1900;
      else if (cGender === 2 || cGender === 3) century = 2000;
      else if (cGender === 4 || cGender === 5) century = 2100;
      else if (cGender === 6 || cGender === 7) century = 2200;
      else if (cGender === 8 || cGender === 9) century = 2300;
      const cccdYear = String(century + parseInt(cYear, 10));
      console.log('[BHYT Extension] Trích xuất năm sinh fallback từ số CCCD:', cccdYear);
      return cccdYear;
    }

    return '';
  }

  function setupNamsinhCheckboxUserListener() {
    const chk = findNamsinhCheckbox(document);
    if (!chk || chk.dataset.bhytUserListenerAttached === 'true') return;
    chk.dataset.bhytUserListenerAttached = 'true';

    const handleCheckboxToggle = () => {
      console.log('[BHYT Extension] Checkbox Năm sinh vừa thay đổi trạng thái:', chk.checked);
      if (!chk.checked) {
        // Bỏ tích checkbox Năm sinh -> Khôi phục ngày sinh đầy đủ nếu trước đó có
        let fullDob = '';
        if (lastScannedQrDob && /^\d{2}\/\d{2}\/\d{4}$/.test(lastScannedQrDob)) {
          fullDob = lastScannedQrDob;
        } else if (currentBhytCardData && currentBhytCardData.ngaySinh && /^\d{1,2}[\/.-]\d{1,2}[\/.-]\d{4}$/.test(currentBhytCardData.ngaySinh)) {
          fullDob = currentBhytCardData.ngaySinh;
        } else if (currentHisPatient && (currentHisPatient.NGAY_SINH || currentHisPatient.ngaysinh)) {
          const fmt = formatBhxhDate(currentHisPatient.NGAY_SINH || currentHisPatient.ngaysinh);
          if (fmt && /^\d{1,2}[\/.-]\d{1,2}[\/.-]\d{4}$/.test(fmt)) fullDob = fmt;
        }

        if (fullDob) {
          setFieldSuccess('namsinh', fullDob);
        }
      } else {
        // Tích checkbox Năm sinh -> Giữ năm sinh 4 số
        const curDob = extractTiepNhanDob();
        const yMatch = curDob.match(/\b(19\d{2}|20\d{2})\b/);
        if (yMatch) {
          setFieldSuccess('namsinh', yMatch[0]);
        }
      }
    };

    chk.addEventListener('change', handleCheckboxToggle);
    chk.addEventListener('click', () => setTimeout(handleCheckboxToggle, 50));
  }

  function setupNamsinhListener() {
    const nsEl = findDobTextInput(document) || document.getElementById('namsinh') || document.querySelector('input[name="namsinh"]');
    if (!nsEl || nsEl.type === 'checkbox' || nsEl.dataset.bhytListenerAttached === 'true') return;

    nsEl.dataset.bhytListenerAttached = 'true';
    const handleNsEnter = (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();
        triggerBhytCheckFromForm();
      }
    };
    nsEl.addEventListener('keypress', handleNsEnter, true);
    nsEl.addEventListener('keydown', handleNsEnter, true);

    nsEl.addEventListener('change', (e) => {
      // TUYỆT ĐỐI chỉ xử lý khi người dùng trực tiếp gõ tay trên giao diện (chống đệ quy vô hạn với HIS)
      if (!e.isTrusted) return;

      const val = (nsEl.value || '').trim();
      const ageObj = calculateAge(val);
      if (ageObj && ageObj.tuoi !== null) {
        setFieldSuccess('tuoi', ageObj.tuoi);
        if (ageObj.isUnder6) {
          if (ageObj.thang) setFieldSuccess('thang', ageObj.thang);
          if (ageObj.ngay) setFieldSuccess('ngay', ageObj.ngay);
        }
        if (!isUserModifiedNgheNghiep) {
          const cardNo = (document.getElementById('sobhyt')?.value || '').trim();
          const inferred = inferNgheNghiep(cardNo, ageObj.tuoi);
          syncNgheNghiep(inferred.code, inferred.text);
        }
      }

      // Nếu đang có dữ liệu BHYT trả về chỉ có năm sinh, luôn bảo toàn trạng thái đã tích:
      if (currentBhytCardData && currentBhytCardData.ngaySinh) {
        const bNs = String(currentBhytCardData.ngaySinh).trim();
        const bNote = String(currentBhytCardData.ghiChu || '');
        const isCardYearOnly = /^\d{4}$/.test(bNs) || /^00\/00\/\d{4}$/.test(bNs) || /ngày\s*sinh\s*:\s*\d{4}/i.test(bNote);
        if (isCardYearOnly) {
          setNamsinhCheckboxState(true, document);
          return;
        }
      }

      if (val) {
        const isYearOnly = /^\d{4}$/.test(val) || /^00\/00\/\d{4}$/.test(val);
        if (isYearOnly) {
          setNamsinhCheckboxState(true, document);
        } else if (!val.startsWith('01/01/')) {
          setNamsinhCheckboxState(false, document);
        }
      }
    });

    nsEl.addEventListener('blur', () => {
      enforceVerifiedDobAndAddress();
    });
  }

  // =========================================================================
  // TÌM VÀ ĐIỀU KHIỂN CHECKBOX "NĂM SINH" TRÊN FORM TIẾP NHẬN HOẶC MODAL
  // =========================================================================
  function findNamsinhCheckbox(scope = document) {
    if (!scope) scope = document;

    // 1. Selector trực tiếp phổ biến nhất trên VNPT HIS
    const directSelectors = [
      '#namsinh_hc',
      'input[name="namsinh_hc"]',
      '#chk_namsinh_hc',
      'input[type="checkbox"]#namsinh_hc',
      '#chinamsinh',
      'input[name="chinamsinh"]',
      'input[type="checkbox"][id*="chinamsinh"]',
      'input[type="checkbox"][name*="chinamsinh"]',
      '#chk_chinamsinh',
      '#hien_namsinh',
      'input[name="hien_namsinh"]',
      'input[type="checkbox"][id*="hien_namsinh"]',
      'input[type="checkbox"][name*="hien_namsinh"]',
      '#chk_namsinh',
      '#chkNamsinh',
      '#chk_nam_sinh',
      '#chknamsinh',
      '#is_namsinh',
      '#isnamsinh',
      '#namsinh_chk',
      '#chinamsinh',
      '#sua_chinamsinh',
      '#suatt_chinamsinh',
      '#sua_namsinh',
      '#chk_sua_namsinh',
      'input[type="checkbox"]#namsinh',
      'input[type="checkbox"]#suatt_namsinh',
      'input[type="checkbox"]#sua_namsinh',
      'input[type="checkbox"]#chinamsinh',
      'input[type="checkbox"]#sua_chinamsinh',
      'input[type="checkbox"][id*="namsinh"]',
      'input[type="checkbox"][name*="namsinh"]',
      'input[type="checkbox"][id*="nam_sinh"]',
      'input[type="checkbox"][name*="nam_sinh"]',
      'input[type="checkbox"][id*="chinamsinh"]',
      'input[type="checkbox"][name*="chinamsinh"]'
    ];

    for (const sel of directSelectors) {
      const el = scope.querySelector(sel);
      if (el && (el.type === 'checkbox' || el.getAttribute('type') === 'checkbox')) return el;
    }

    // 1.1 Kiểm tra nút Sửa Chỉ 5 (#sua_chi5) - script HIS chèn ngay trước checkbox #chinamsinh
    const btnSuaChi5 = scope.querySelector ? scope.querySelector('#sua_chi5') : document.getElementById('sua_chi5');
    if (btnSuaChi5) {
      if (btnSuaChi5.nextElementSibling && (btnSuaChi5.nextElementSibling.type === 'checkbox' || btnSuaChi5.nextElementSibling.getAttribute('type') === 'checkbox')) {
        return btnSuaChi5.nextElementSibling;
      }
      const p = btnSuaChi5.parentElement;
      if (p) {
        const pChk = p.querySelector('input[type="checkbox"]');
        if (pChk) return pChk;
      }
    }

    // 2. Tìm checkbox nằm trong cùng dòng (tr, .row, .form-group) với ô Ngày sinh
    const dobInput = scope.querySelector('#namsinh, #suatt_namsinh, #txt_namsinh, #ngaysinh, input[name="namsinh"], input[name="ngaysinh"]');
    if (dobInput) {
      const rowContainer = dobInput.closest('tr, .row, .form-group, .datagrid-row') ||
                           dobInput.parentElement?.closest('tr, .row, .form-group') ||
                           dobInput.parentElement?.parentElement;
      if (rowContainer) {
        const cks = rowContainer.querySelectorAll('input[type="checkbox"]');
        for (const c of cks) {
          const cid = (c.id || '').toLowerCase();
          const cname = (c.name || '').toLowerCase();
          if (cid.includes('capcuu') || cname.includes('capcuu') || cid.includes('dungtuyen') || cname.includes('dungtuyen') || cid.includes('ngoaikieu') || cname.includes('ngoaikieu') || cid.includes('uutien') || cname.includes('uutien')) {
            continue;
          }
          if (cid.includes('namsinh') || cname.includes('namsinh') || cid.includes('chi') || cname.includes('chi')) {
            return c;
          }
        }
        for (const c of cks) {
          const cid = (c.id || '').toLowerCase();
          const cname = (c.name || '').toLowerCase();
          if (!cid.includes('capcuu') && !cname.includes('capcuu') && !cid.includes('dungtuyen') && !cname.includes('dungtuyen') && !cid.includes('ngoaikieu') && !cname.includes('ngoaikieu')) {
            return c;
          }
        }
      }
    }

    // 3. Quét tất cả các checkbox và kiểm tra nhãn / chữ đi liền ("Năm sinh", "Chỉ năm sinh")
    const allChecks = scope.querySelectorAll('input[type="checkbox"]');
    for (const c of allChecks) {
      const cid = (c.id || '').toLowerCase();
      const cname = (c.name || '').toLowerCase();
      if (cid.includes('capcuu') || cname.includes('capcuu') || cid.includes('dungtuyen') || cname.includes('dungtuyen') || cid.includes('ngoaikieu') || cname.includes('ngoaikieu')) continue;

      const parentText = (c.parentElement?.textContent || '').toLowerCase();
      const nextText = (c.nextSibling?.textContent || c.nextElementSibling?.textContent || '').toLowerCase();
      const prevText = (c.previousSibling?.textContent || c.previousElementSibling?.textContent || '').toLowerCase();
      const combined = `${parentText} ${nextText} ${prevText}`;

      if (combined.includes('năm sinh') || combined.includes('nam sinh') || combined.includes('chỉ năm')) {
        return c;
      }
    }

    // 4. Quét các hàng (tr, .form-group, .row) có chứa chữ "năm sinh" hoặc "chỉ năm sinh"
    const rows = scope.querySelectorAll('tr, .form-group, .row');
    for (const row of rows) {
      const txt = (row.textContent || '').toLowerCase();
      if ((txt.includes('năm sinh') || txt.includes('chỉ năm sinh')) && !txt.includes('cấp cứu') && !txt.includes('ngoại kiều')) {
        const c = row.querySelector('input[type="checkbox"]');
        if (c) return c;
      }
    }

    return null;
  }

  function setNamsinhCheckboxState(isYearOnly, scope = document) {
    if (!scope) scope = document;
    const chk = findNamsinhCheckbox(scope);
    if (!chk) {
      return;
    }

    const shouldCheck = Boolean(isYearOnly);

    const applyState = (targetChk, checkState) => {
      if (!targetChk) return;
      targetChk.disabled = false;
      targetChk.removeAttribute('disabled');
      targetChk.readOnly = false;
      targetChk.removeAttribute('readonly');
      targetChk.checked = checkState;
      if (checkState) {
        targetChk.setAttribute('checked', 'checked');
      } else {
        targetChk.removeAttribute('checked');
      }

      const jq = targetChk.ownerDocument?.defaultView?.$ || window.$;
      if (jq) {
        try {
          jq(targetChk).prop('disabled', false).prop('checked', checkState);
          if (checkState) {
            jq(targetChk).attr('checked', 'checked');
          } else {
            jq(targetChk).removeAttr('checked');
          }
        } catch (e) {}
      }

      // Giữ nguyên 100% màu sắc mặc định của HIS
      targetChk.classList.remove('bhyt-ext-field-success', 'bhyt-modal-field-filled');
      targetChk.style.outline = '';
      targetChk.style.accentColor = '';
      targetChk.style.backgroundColor = '';
      removeTick(targetChk);
    };

    applyState(chk, shouldCheck);

    // Phát các sự kiện DOM chuẩn
    chk.dispatchEvent(new Event('input', { bubbles: true }));
    chk.dispatchEvent(new Event('change', { bubbles: true }));

    // Gia cố trạng thái chống lại sự can thiệp ngầm / reset của HIS hoặc các script khác
    [50, 150, 300, 600, 1000].forEach((delay) => {
      setTimeout(() => {
        const c = findNamsinhCheckbox(scope) || chk;
        applyState(c, shouldCheck);
      }, delay);
    });
  }

  function setupMayteListener() {
    const mayteEl = document.getElementById('mayte') || document.querySelector('input[name="mayte"]');
    if (!mayteEl || mayteEl.dataset.bhytListenerAttached === 'true') return;

    mayteEl.dataset.bhytListenerAttached = 'true';
    const handleMayteEnter = (e) => {
      if (e.key === 'Enter') {
        const val = (mayteEl.value || '').trim();
        if (val) {
          const curMaBn = currentHisPatient?.MA_BENH_NHAN || currentHisPatient?.mabenhnhan;
          if (val !== curMaBn) {
            activeVerifiedDob = '';
            activeVerifiedAddressCv30 = null;
            currentBhytCardData = null;
            lastScannedQrDob = '';
          }
          lookupPatientInHis(val);
        }
      }
    };
    mayteEl.addEventListener('keydown', handleMayteEnter, true);
  }

  function setupTimBnButtonListener() {
    const directBtn = document.getElementById('timbn') || document.getElementById('btn_timbn') || document.querySelector('button[id*="timbn"], input[value*="Tìm BN"]');
    const buttons = directBtn ? [directBtn] : document.querySelectorAll('button, input[type="button"]');
    buttons.forEach((btn) => {
      if (btn.dataset.bhytListenerAttached === 'true') return;
      const text = (btn.value || btn.textContent || '').trim();
      if (text === 'Tìm BN' || text === 'Tìm bệnh nhân' || btn.id === 'timbn' || btn.id === 'btn_timbn') {
        btn.dataset.bhytListenerAttached = 'true';
        btn.addEventListener('click', async () => {
          const cccdVal = getCccdInput()?.value?.replace(/\D/g, '');
          const bhytVal = document.getElementById('sobhyt')?.value?.trim();
          const mayteVal = document.getElementById('mayte')?.value?.trim();
          console.log('[BHYT Extension] Bấm nút Tìm BN -> tìm hồ sơ trong HIS với:', { bhytVal, cccdVal, mayteVal });
          const searchKey = cccdVal || bhytVal || mayteVal;
          if (searchKey) {
            await lookupPatientInHis(searchKey);
          }
        });
      }
    });
  }

  function interceptExistingCheckButtons() {
    // BẢO VỆ HIỆU NĂNG: Chỉ truy vấn các phần tử button hoặc id/name nghi vấn thay vì toàn bộ thẻ a, [onclick], .btn trên toàn trang
    const allButtons = document.querySelectorAll('button, input[type="button"], input[type="submit"], [id*="kiemtra"], [id*="ktra"], [name*="kiemtra"]');
    allButtons.forEach((btn) => {
      if (btn.dataset.bhytIntercepted === 'true') return;
      if (btn.id === 'bhytExtInlineBtn' || btn.id === 'bhytExtFloatingRightBtn' || btn.id === 'sua_CCCD' || btn.id === 'sua_5nam') return;

      const txt = (btn.value || btn.textContent || '').trim().toLowerCase();
      const id = (btn.id || '').toLowerCase();
      const name = (btn.name || '').toLowerCase();
      const onclickAttr = (btn.getAttribute('onclick') || '').toLowerCase();

      const isCheckBtn =
        id.includes('kiemtrathe') ||
        id.includes('kiemtra_bhyt') ||
        id.includes('btn_kiemtrabhyt') ||
        id.includes('ktratt_bhyt') ||
        id.includes('kiemtra_the') ||
        name.includes('kiemtrathe') ||
        name.includes('kiemtra_bhyt') ||
        onclickAttr.includes('kiemtrathe') ||
        onclickAttr.includes('kiemtra_bhyt') ||
        txt === 'kiểm tra bhyt' ||
        txt === 'ktra tt thẻ bhyt' ||
        txt === 'kiểm tra thẻ bhyt' ||
        txt === 'kiểm tra thẻ bảo hiểm' ||
        txt === 'ktthẻ bhyt' ||
        txt === 'kt thẻ';

      if (isCheckBtn && btn.dataset.bhytIntercepted !== 'true') {
        btn.dataset.bhytIntercepted = 'true';
        btn.removeAttribute('onclick');
        btn.onclick = null;

        // Clone node để triệt tiêu toàn bộ listener cũ do HIS gắn vào bằng jQuery hoặc addEventListener
        const clone = btn.cloneNode(true);
        clone.removeAttribute('onclick');
        clone.onclick = null;
        clone.dataset.bhytIntercepted = 'true';

        if (btn.parentNode) {
          btn.parentNode.replaceChild(clone, btn);
        }

        console.log('[BHYT Extension] Đã thay thế và chặn nút kiểm tra thẻ của HIS:', clone);
        clone.addEventListener('click', (e) => {
          e.preventDefault();
          e.stopPropagation();
          e.stopImmediatePropagation();
          triggerBhytCheckFromForm();
        }, true);
      }
    });
  }

  // =========================================================================
  // 2. TỰ ĐỘNG TÌM HỒ SƠ TIẾP NHẬN TRƯỚC ĐÓ TRONG HIS (TỐI ƯU HÓA SONG SONG & CACHE)
  // =========================================================================
  const hisPatientCache = new Map();
  const hisInflightLookups = new Map();
  const MAX_CACHED_PATIENTS = 500;
  let cachedPatientsFromStorage = {};

  async function initPersistentPatientCache() {
    try {
      if (typeof chrome !== 'undefined' && chrome.storage && chrome.storage.local) {
        chrome.storage.local.get(['bhyt_cached_patients_map'], (res) => {
          if (res && res.bhyt_cached_patients_map) {
            cachedPatientsFromStorage = res.bhyt_cached_patients_map || {};
            for (const [key, p] of Object.entries(cachedPatientsFromStorage)) {
              if (p && extractMaBn(p) && !hisPatientCache.has(key)) {
                hisPatientCache.set(key, p);
              }
            }
            console.log('[BHYT Extension] Đã nạp danh bạ hồ sơ bệnh nhân từ Bộ nhớ lưu trữ:', Object.keys(cachedPatientsFromStorage).length);
          }
        });
      }
    } catch (e) {
      console.warn('[BHYT Extension] Không thể đọc cache lưu trữ:', e);
    }
  }

  function savePatientToPersistentCache(patient) {
    if (!patient || typeof patient !== 'object') return;
    const maBn = extractMaBn(patient);
    // BẢO VỆ TUYỆT ĐỐI: CHỈ lưu vào cache HIS nếu hồ sơ thực sự có Mã bệnh nhân / Mã y tế
    if (!maBn) return;

    const cccd = (patient.CMT_BENHNHAN || patient.SO_CCCD || patient.SOCMT || patient.socmt || patient.soCccd || '').replace(/\D/g, '');
    const card = (patient.SO_THE_BAOHIEM_YTE || patient.SO_THE_BHYT || patient.sobhyt || patient.maThe || patient.MA_THE || '').replace(/\s+/g, '').toUpperCase();

    const sdt = extractPatientSdt(patient);
    const record = {
      ...patient,
      CMT_BENHNHAN: cccd || patient.CMT_BENHNHAN || '',
      SO_CCCD: cccd || patient.SO_CCCD || '',
      socmt: cccd || patient.socmt || '',
      MA_BENH_NHAN: maBn,
      mayte: maBn,
      SO_THE_BAOHIEM_YTE: card || patient.SO_THE_BAOHIEM_YTE || '',
      sobhyt: card || patient.sobhyt || '',
      maThe: card || patient.maThe || '',
      SO_DIEN_THOAI: sdt || patient.SO_DIEN_THOAI || '',
      sodt: sdt || patient.sodt || '',
      savedAt: Date.now()
    };

    if (cccd) {
      hisPatientCache.set(cccd, record);
      cachedPatientsFromStorage[cccd] = record;
    }
    if (maBn) {
      hisPatientCache.set(String(maBn), record);
      cachedPatientsFromStorage[String(maBn)] = record;
    }
    if (card) {
      hisPatientCache.set(card, record);
      cachedPatientsFromStorage[card] = record;
      if (card.length > 10) {
        hisPatientCache.set(card.slice(-10), record);
        cachedPatientsFromStorage[card.slice(-10)] = record;
      }
    }

    try {
      if (typeof chrome !== 'undefined' && chrome.storage && chrome.storage.local) {
        const keys = Object.keys(cachedPatientsFromStorage);
        if (keys.length > MAX_CACHED_PATIENTS * 2) {
          const sorted = keys.sort((a, b) => (cachedPatientsFromStorage[b]?.savedAt || 0) - (cachedPatientsFromStorage[a]?.savedAt || 0));
          const keepKeys = sorted.slice(0, MAX_CACHED_PATIENTS);
          const trimmed = {};
          keepKeys.forEach(k => { trimmed[k] = cachedPatientsFromStorage[k]; });
          cachedPatientsFromStorage = trimmed;
        }
        chrome.storage.local.set({ bhyt_cached_patients_map: cachedPatientsFromStorage });
      }
    } catch (e) {}
  }

  async function fetchJsonWithTimeout(url, timeoutMs = 2000) {
    try {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), timeoutMs);
      const res = await fetch(url, { signal: controller.signal });
      clearTimeout(timer);
      if (!res.ok) return null;
      const text = await res.text();
      if (!text || !text.trim() || text.trim().startsWith('<')) return null;
      return JSON.parse(text);
    } catch (e) {
      return null;
    }
  }

  function extractPatientFromResponse(data) {
    if (!data) return null;
    let list = [];
    if (Array.isArray(data)) list = data;
    else if (Array.isArray(data.data)) list = data.data;
    else if (Array.isArray(data.rows)) list = data.rows;
    else if (Array.isArray(data.result)) list = data.result;
    else if (Array.isArray(data.list)) list = data.list;
    else if (extractMaBn(data) || extractPatientSdt(data) || data.TEN_BENH_NHAN || data.tenbenhnhan || data.HOTEN || data.hoten || data.CMT_BENHNHAN || data.SO_CCCD) list = [data];
    else if (data.data && (extractMaBn(data.data) || extractPatientSdt(data.data) || data.data.TEN_BENH_NHAN || data.data.HOTEN || data.data.CMT_BENHNHAN || data.data.SO_CCCD)) list = [data.data];

    if (list.length > 0) {
      const p = Object.assign({}, list[0]);
      for (const item of list) {
        const nn = extractNgheNghiepFromHis(item);
        if (nn && !p.MA_NGHE_NGHIEP) {
          p.MA_NGHE_NGHIEP = nn;
        }
        const sdt = extractPatientSdt(item);
        if (sdt && !p.SO_DIEN_THOAI) {
          p.SO_DIEN_THOAI = sdt;
          p.sodt = sdt;
        }
        const mb = extractMaBn(item);
        if (mb && !p.MA_BENH_NHAN) {
          p.MA_BENH_NHAN = mb;
          p.MABENHNHAN = mb;
          p.mayte = mb;
        }
      }
      const pMb = extractMaBn(p);
      if (pMb) {
        p.MA_BENH_NHAN = pMb;
        p.MABENHNHAN = pMb;
        p.mayte = pMb;
      }
      const pSdt = extractPatientSdt(p);
      if (pSdt) {
        p.SO_DIEN_THOAI = pSdt;
        p.sodt = pSdt;
      }
      return p;
    }
    return null;
  }

  async function lookupPatientInHis(...codes) {
    const validCodes = [];
    for (const c of codes) {
      if (Array.isArray(c)) {
        c.forEach((x) => {
          const cl = String(x || '').trim().replace(/\s+/g, '');
          if (cl && !validCodes.includes(cl)) validCodes.push(cl);
        });
      } else {
        const cl = String(c || '').trim().replace(/\s+/g, '');
        if (cl && !validCodes.includes(cl)) validCodes.push(cl);
      }
    }
    if (validCodes.length === 0) return null;

    // 1. Kiểm tra cache tức thì (0ms) - CHỈ chấp nhận bản ghi có Mã bệnh nhân / Mã y tế hợp lệ
    for (const code of validCodes) {
      if (hisPatientCache.has(code)) {
        const cached = hisPatientCache.get(code);
        const cachedMaBn = extractMaBn(cached);
        if (cachedMaBn) {
          console.log('[BHYT Extension] Lấy nhanh hồ sơ bệnh nhân từ Cache có Mã y tế:', code, cachedMaBn);
          currentHisPatient = cached;
          applyHisPatientToForm(cached);
          return cached;
        } else {
          // Xóa bản ghi không có Mã y tế để không cản trở việc tra cứu HIS thực tế
          hisPatientCache.delete(code);
        }
      }
    }

    const inflightKey = validCodes[0];
    if (hisInflightLookups.has(inflightKey)) {
      return await hisInflightLookups.get(inflightKey);
    }

    const lookupPromise = (async () => {
      let foundPatient = null;

      for (const code of validCodes) {
        const isCccdOrCmt = /^\d{9,12}$/.test(code);
        const isBhyt15 = code.length === 15 && /^[a-zA-Z0-9]+$/.test(code);
        const isBhyt10 = code.length === 10 && /^\d{10}$/.test(code);
        const isMaYte = /^\d{1,8}$/.test(code);

        // Tạo danh sách endpoint truy vấn song song có định hướng
        const candidateUrls = [];

        if (isCccdOrCmt) {
          candidateUrls.push(
            `${window.location.origin}/web_his/timkiembntheocmt?socmt=${encodeURIComponent(code)}&mabn=0`,
            `${window.location.origin}/web_his/timkiembntheocccd?cccd=${encodeURIComponent(code)}`
          );
        }
        if (isBhyt15 || isBhyt10 || code.length >= 10) {
          candidateUrls.push(
            `${window.location.origin}/web_his/timkiembntheobhyt?bhyt=${encodeURIComponent(code)}&mabn=0`
          );
          if (code.length > 10) {
            const code10 = code.slice(-10);
            candidateUrls.push(
              `${window.location.origin}/web_his/timkiembntheobhyt?bhyt=${encodeURIComponent(code10)}&mabn=0`
            );
          }
        }
        if (isMaYte) {
          candidateUrls.push(
            `${window.location.origin}/web_his/laythongtinhcbn_theomabn?mabn=${encodeURIComponent(code)}`,
            `${window.location.origin}/web_his/timkiembntheobhyt?bhyt=0&mabn=${encodeURIComponent(code)}`
          );
        }

        // Gọi song song 2 endpoint chính xác nhất với timeout siêu tốc 1200ms (tránh nghẽn connection pool)
        const results = await Promise.allSettled(
          candidateUrls.map((u) => fetchJsonWithTimeout(u, 1200))
        );

        for (const r of results) {
          if (r.status === 'fulfilled' && r.value) {
            const p = extractPatientFromResponse(r.value);
            if (p && (extractMaBn(p) || extractPatientSdt(p) || p.TEN_BENH_NHAN || p.HOTEN || p.CMT_BENHNHAN || p.SO_CCCD)) {
              foundPatient = p;
              break;
            }
          }
        }

        if (foundPatient) break;
      }

      if (!foundPatient) {
        console.log('[BHYT Extension] Không tìm thấy dữ liệu tiếp nhận trước đó trong HIS cho:', validCodes);
        return null;
      }

      // Áp dụng ngay lập tức Mã y tế, Số ĐT và thông tin bệnh nhân lên form để phản hồi siêu tốc (0ms)
      const maBn = extractMaBn(foundPatient);
      if (maBn) {
        setFieldSuccess('mayte', maBn);
      }
      const sdt = extractPatientSdt(foundPatient);
      if (sdt) {
        foundPatient.SO_DIEN_THOAI = sdt;
        foundPatient.sodt = sdt;
        const elSdt = findSdtInput();
        if (elSdt) {
          elSdt.value = sdt;
          setFieldSuccess(elSdt, sdt);
          if (window.$) try { window.$(elSdt).val(sdt).trigger('input').trigger('change'); } catch (e) {}
        }
        setFieldSuccess('sodt', sdt);
      }

      // Lưu cache theo các mã định danh CHÍNH XÁC của bệnh nhân tìm thấy
      if (foundPatient.MA_BENH_NHAN || maBn) hisPatientCache.set(String(foundPatient.MA_BENH_NHAN || maBn).trim(), foundPatient);
      if (foundPatient.CMT_BENHNHAN) {
        const cleanCmt = String(foundPatient.CMT_BENHNHAN).trim().replace(/\D/g, '');
        if (cleanCmt) hisPatientCache.set(cleanCmt, foundPatient);
      }
      if (foundPatient.SO_THE_BAOHIEM_YTE) {
        const cCard = String(foundPatient.SO_THE_BAOHIEM_YTE).trim().toUpperCase();
        hisPatientCache.set(cCard, foundPatient);
        if (cCard.length > 10) hisPatientCache.set(cCard.slice(-10), foundPatient);
      }

      console.log('[BHYT Extension] ĐÃ TÌM THẤY BỆNH NHÂN TRONG HIS (SIÊU TỐC):', foundPatient);
      currentHisPatient = foundPatient;
      applyHisPatientToForm(foundPatient);
      savePatientToPersistentCache(foundPatient);

      // Chạy ngầm làm giàu thêm thông tin hành chính (SĐT, Thân nhân, 5 năm...) không block luồng chính
      if (maBn) {
        foundPatient._hasEnrichedAdminData = true;
        const extraUrls = [
          `${window.location.origin}/web_his/laythongtinhcbn_theomabn?mabn=${encodeURIComponent(maBn)}`,
          `${window.location.origin}/web_his/laythongtinhcbn_theomabn?mabenhnhan=${encodeURIComponent(maBn)}`,
          `${window.location.origin}/web_his/lay_thongtin_benhnhan?mabn=${encodeURIComponent(maBn)}`,
          `${window.location.origin}/web_his/lay_thongtin_benhnhan?mabenhnhan=${encodeURIComponent(maBn)}`,
          `${window.location.origin}/web_his/thongtinhanhchinh_nhapvien_theomabenhnhan?mabenhnhan=${encodeURIComponent(maBn)}`,
          `${window.location.origin}/web_his/laylichsukcb?mabn=${encodeURIComponent(maBn)}`
        ];
        Promise.allSettled(extraUrls.map((u) => fetchJsonWithTimeout(u, 1500))).then((resList) => {
          for (const item of resList) {
            if (item.status === 'fulfilled' && item.value) {
              const list = Array.isArray(item.value) ? item.value : [item.value];
              for (const obj of list) {
                if (obj && typeof obj === 'object') {
                  const extraSdt = extractPatientSdt(obj);
                  if (extraSdt) {
                    foundPatient.SO_DIEN_THOAI = extraSdt;
                    foundPatient.sodt = extraSdt;
                    const elSdt = findSdtInput();
                    if (elSdt && (!elSdt.value || !elSdt.value.trim())) {
                      setFieldSuccess('sodt', extraSdt);
                    }
                  }
                  const nn = extractNgheNghiepFromHis(obj);
                  if (nn && !foundPatient.MA_NGHE_NGHIEP) {
                    foundPatient.MA_NGHE_NGHIEP = nn;
                  }
                  if ((obj.NT_THOIDIEM_5NAM_LIENTUC || obj.KB_THOIDIEM_5NAM_LIENTUC) && !foundPatient.KB_THOIDIEM_5NAM_LIENTUC) {
                    foundPatient.KB_THOIDIEM_5NAM_LIENTUC = obj.NT_THOIDIEM_5NAM_LIENTUC || obj.KB_THOIDIEM_5NAM_LIENTUC;
                  }
                  for (const [k, v] of Object.entries(obj)) {
                    if (v != null && v !== '' && (foundPatient[k] == null || foundPatient[k] === '')) {
                      foundPatient[k] = v;
                    }
                  }
                }
              }
            }
          }
          savePatientToPersistentCache(foundPatient);
        }).catch(() => {});
      }

      return foundPatient;
    })();

    hisInflightLookups.set(inflightKey, lookupPromise);
    try {
      return await lookupPromise;
    } finally {
      hisInflightLookups.delete(inflightKey);
    }
  }

  function applyHisPatientToForm(bn) {
    if (!bn) return;

    const currentPatientSig = (extractMaBn(bn) || bn.CMT_BENHNHAN || bn.SO_CCCD || bn.SOCMT || bn.socmt || bn.MA_THE || bn.sobhyt || '').trim();
    if (currentPatientSig && currentPatientSig !== lastAppliedPatientSig) {
      lastAppliedPatientSig = currentPatientSig;
      // Chuẩn hóa CCCD, Thẻ BHYT, Họ tên để so sánh chính xác giữa dữ liệu Thẻ BHYT và hồ sơ HIS
      const cardCccd = (currentBhytCardData?.soCCCD || currentBhytCardData?.soCccd || currentBhytCardData?.cccd || currentBhytCardData?.socmt || (typeof lastScannedQrCccd !== 'undefined' ? lastScannedQrCccd : '') || (typeof activeVerifiedCccd !== 'undefined' ? activeVerifiedCccd : '') || (typeof lastCheckedCccd !== 'undefined' ? lastCheckedCccd : '') || '').replace(/\D/g, '');
      const hisCccd = (bn.CMT_BENHNHAN || bn.SO_CCCD || bn.SOCMT || bn.socmt || bn.soCccd || bn.cccd || bn.CMND || '').replace(/\D/g, '');

      const cardThe = (currentBhytCardData?.maTheMoi || currentBhytCardData?.maThe || currentBhytCardData?.sobhyt || '').replace(/\s+/g, '').toUpperCase();
      const hisThe = (bn.MA_THE || bn.SO_THE_BAOHIEM_YTE || bn.SO_THE_BHYT || bn.SOBHYT || bn.sobhyt || bn.maThe || '').replace(/\s+/g, '').toUpperCase();

      const cardName = (currentBhytCardData?.hoTen || currentBhytCardData?.hoten || (typeof lastScannedQrHoTen !== 'undefined' ? lastScannedQrHoTen : '') || '').trim().toUpperCase();
      const hisName = (bn.TEN_BENH_NHAN || bn.HOTEN || bn.tenbenhnhan || bn.hoTen || bn.hoten || bn.TEN_BN || '').trim().toUpperCase();

      // BẢO VỆ TUYỆT ĐỐI: Tra cứu hồ sơ cũ từ HIS chỉ dùng để làm giàu thêm Mã y tế & SĐT.
      // TUYỆT ĐỐI KHÔNG BAO GIỜ xóa hoặc làm suy giảm dữ liệu thẻ BHYT và Hạn thẻ vừa xác thực từ Cổng BHXH!
    }

    // 1. Mã y tế (#mayte)
    const maBn = extractMaBn(bn);
    if (maBn) {
      setFieldSuccess('mayte', maBn);
    }

    // 2. Họ và tên (#hoten)
    const hoTen = (bn.TEN_BENH_NHAN || bn.HOTEN || bn.tenbenhnhan || bn.hoTen || bn.hoten || bn.TEN_BN || '').trim();
    if (hoTen) {
      setFieldSuccess('hoten', hoTen.toUpperCase());
    }

    // 3. Số CCCD/CMT (#socmt)
    const cccd = (bn.CMT_BENHNHAN || bn.SO_CCCD || bn.SOCMT || bn.socmt || bn.soCccd || bn.cccd || bn.CMND || '').replace(/\D/g, '');
    if (cccd) {
      setFieldSuccess('socmt', cccd);
      updateCccdCounter(cccd);
    }

    // 4. Ngày sinh (#namsinh) & Tính tuổi (#tuoi, #thang, #ngay)
    const rawNs = bn.NGAY_SINH || bn.NGAYSINH || bn.NAMSINH || bn.ngaySinh || bn.ngaysinh;
    if (isUserEditingDob()) {
      console.log('[BHYT Extension] Người dùng đang tự nhập Ngày sinh -> giữ nguyên giá trị đã nhập');
    } else if (activeVerifiedDob) {
      console.log('[BHYT Extension] Bảo toàn ngày sinh đã xác thực:', activeVerifiedDob);
      fillNgaySinhFields(activeVerifiedDob, activeVerifiedDob);
    } else if (lastScannedQrDob && /^\d{2}\/\d{2}\/\d{4}$/.test(lastScannedQrDob)) {
      console.log('[BHYT Extension] Bảo toàn ngày sinh đầy đủ từ QR CCCD:', lastScannedQrDob);
      fillNgaySinhFields(lastScannedQrDob, lastScannedQrDob);
    } else if (currentBhytCardData && currentBhytCardData.ngaySinh) {
      const cardNs = formatBhxhDate(currentBhytCardData.ngaySinh);
      fillNgaySinhFields(cardNs, cardNs);
    } else if (rawNs) {
      const formattedDob = formatBhxhDate(rawNs);
      const cleanNs = String(formattedDob || '').trim();
      const yearMatch = cleanNs.match(/\b\d{4}\b/);
      const yearVal = yearMatch ? parseInt(yearMatch[0], 10) : 0;
      const currentYear = new Date().getFullYear();

      // CHỈ chấp nhận ngày sinh từ HIS nếu năm sinh hợp lệ (1900 <= yearVal <= currentYear)
      if (yearVal >= 1900 && yearVal <= currentYear) {
        const isYearOnly = (bn.HIEN_NAMSINH != null && (String(bn.HIEN_NAMSINH) === '1' || String(bn.HIEN_NAMSINH) === 'true')) ||
                           /^\d{4}$/.test(cleanNs) || /^00\/00\/\d{4}$/.test(cleanNs);
        const valToFill = isYearOnly ? (String(yearVal) || cleanNs) : cleanNs;
        fillNgaySinhFields(valToFill, valToFill);
      } else {
        console.warn(`[BHYT Extension] Bỏ qua ngày sinh HIS bất thường (${cleanNs}) vì năm sinh ${yearVal} > ${currentYear}`);
      }
    } else if (bn.TUOI != null) {
      setFieldSuccess('tuoi', bn.TUOI);
      if (bn.THANG != null) setFieldSuccess('thang', bn.THANG);
    }

    // 5. Giới tính (#gioitinh & #cbgioitinh)
    const rawGt = bn.GIOI_TINH != null ? bn.GIOI_TINH : (bn.GIOITINH != null ? bn.GIOITINH : bn.gioiTinh);
    if (rawGt != null) {
      const gtStr = String(rawGt).toLowerCase();
      const isNam = gtStr === '1' || gtStr === 'true' || gtStr === 'nam' || gtStr === 'yes';
      setFieldSuccess('gioitinh', isNam ? '1' : '0');
      const cbGt = document.getElementById('cbgioitinh');
      if (cbGt) {
        setSelectValue(cbGt, isNam ? 'true' : 'false');
        cbGt.classList.remove('bhyt-ext-field-success', 'bhyt-ext-field-mismatch');
        cbGt.style.removeProperty('background-color');
        cbGt.style.removeProperty('border-color');
        cbGt.style.removeProperty('color');
      }
    }

    // 6. Số thẻ BHYT (#sobhyt) & Hạn thẻ (#tungay, #denngay)
    const cardNo = (currentBhytCardData && (currentBhytCardData.maTheMoi || currentBhytCardData.maThe))
      ? resolveEffectiveBhytCardForReception(currentBhytCardData, currentBhytCardData.ghiChu, userForcedNewBhytCard).maThe
      : (bn.SO_THE_BAOHIEM_YTE || bn.SO_THE_BHYT || bn.SOBHYT || bn.MA_THE || bn.maThe || bn.sobhyt || '');

    if (currentBhytCardData && (currentBhytCardData.maTheMoi || currentBhytCardData.maThe)) {
      const eff = resolveEffectiveBhytCardForReception(currentBhytCardData, currentBhytCardData.ghiChu, userForcedNewBhytCard);
      if (eff.maThe) {
        setFieldSuccess('sobhyt', eff.maThe);
        if (eff.maThe.length >= 3) {
          fillAndHighlightChuoiNhanDang(eff.maThe);
          fillAndHighlightTlMienGiam(eff.maThe, currentBhytCardData.mucHuong);
        }
      }
      if (eff.tuNgay || activeVerifiedTuNgay) setFieldSuccess('tungay', eff.tuNgay || activeVerifiedTuNgay);
      if (eff.denNgay || activeVerifiedDenNgay) setFieldSuccess('denngay', eff.denNgay || activeVerifiedDenNgay);
    } else if (cardNo) {
      const cleanCn = cardNo.toUpperCase();
      setFieldSuccess('sobhyt', cleanCn);
      if (cleanCn.length >= 3) {
        fillAndHighlightChuoiNhanDang(cleanCn);
        fillAndHighlightTlMienGiam(cleanCn, bn.MUC_HUONG || bn.muchuong);
      }

      // Điền hạn thẻ từ ngày - đến ngày: Ưu tiên tuyệt đối ngày đã xác thực từ Cổng BHYT
      if (activeVerifiedTuNgay) {
        setFieldSuccess('tungay', activeVerifiedTuNgay);
      } else {
        const rawTu = bn.GT_THE_TU || bn.TUNGAY || bn.NGAY_BATDAU_BHYT || bn.gtTheTu || bn.tungay || bn.GT_TU || bn.tuNgay;
        if (rawTu) {
          const fmtTu = formatBhxhDate(rawTu);
          if (fmtTu) setFieldSuccess('tungay', fmtTu);
        }
      }

      if (activeVerifiedDenNgay) {
        setFieldSuccess('denngay', activeVerifiedDenNgay);
      } else {
        const rawDen = bn.GT_THE_DEN || bn.DENNGAY || bn.NGAY_HETHAN_BHYT || bn.gtTheDen || bn.denngay || bn.GT_DEN || bn.denNgay;
        if (rawDen) {
          const fmtDen = formatBhxhDate(rawDen);
          if (fmtDen) setFieldSuccess('denngay', fmtDen);
        }
      }

      fillAndHighlightTlMienGiam(cleanCn, bn.MUC_HUONG || bn.muchuong);
    }

    // 7. Địa chỉ (#diachi)
    if (activeVerifiedAddress) {
      setFieldSuccess('diachi', activeVerifiedAddress);
    } else {
      const dc = bn.DIA_CHI || bn.DIACHI || bn.diaChi || bn.diachi || '';
      if (dc) {
        setFieldSuccess('diachi', dc);
      }
    }

    // 8. Ngày đủ 5 năm liên tục (#thoigian_du5namlientuc)
    const n5 = bn.NT_THOIDIEM_5NAM_LIENTUC || bn.KB_THOIDIEM_5NAM_LIENTUC || bn.THOIDIE_5NAM || bn.NGAY_DU_5_NAM || bn.NGAYDU5NAM || bn.ngayDu5Nam || '';
    if (n5 && hasValidBhytInfoOnForm()) {
      const fmt5 = formatBhxhDate(n5);
      if (fmt5) apply5NamValue(fmt5);
    } else if (!hasValidBhytInfoOnForm()) {
      apply5NamValue('');
    }

    // 9. Nơi đăng ký KCB ban đầu (#noidangky & #noidangkykcb)
    if (currentBhytCardData && (currentBhytCardData.maDKBDMoi || currentBhytCardData.maDKBD)) {
      const eff = resolveEffectiveBhytCardForReception(currentBhytCardData, currentBhytCardData.ghiChu, userForcedNewBhytCard);
      if (eff.maDkbd) {
        setFieldSuccess('noidangky', eff.maDkbd);
        setFieldSuccess('noidangkykcb', eff.maDkbd);
      }
    } else {
      const ndk = bn.NOIDANGKY_KCB || bn.MA_NOIDANGKY || bn.maKcbBd || bn.noidangky || bn.maDKBD || bn.MADKBD || '';
      if (ndk) {
        setFieldSuccess('noidangkykcb', ndk);
        setFieldSuccess('noidangky', ndk);
      }
    }

    // 7. Dân tộc (#dantoc & #cbdantoc)
    if (bn.MA_DANTOC != null) {
      setFieldSuccess('dantoc', bn.MA_DANTOC);
      const cbDt = document.getElementById('cbdantoc') || document.querySelector('select[name="cbdantoc"]');
      if (cbDt) {
        setSelectValue(cbDt, bn.MA_DANTOC);
      }
      try {
        fetch(`${window.location.origin}/web_his/laymadantoc_4069`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8' },
          body: `madantoc=${encodeURIComponent(bn.MA_DANTOC)}`
        })
          .then((r) => r.text())
          .then((code4069) => {
            const el4069 = document.getElementById('dantoc_4069') || document.querySelector('input[name="dantoc_4069"]');
            if (el4069 && code4069 && code4069.trim()) el4069.value = code4069.trim();
          })
          .catch(() => {});
      } catch (e) {}
    }

    // 8. Nghề nghiệp (#nghenghiep & #cbnghenghiep): áp dụng chuẩn xác quy tắc tuổi và tiền tố thẻ BHYT
    if (!isUserModifiedNgheNghiep) {
      const patAge = bn.TUOI ? parseInt(bn.TUOI, 10) : (calculateAge(bn.NGAY_SINH || bn.NAMSINH || '')?.tuoi || 0);
      const cardStr = bn.SO_THE_BAOHIEM_YTE || bn.SO_THE_BHYT || bn.MA_THE || (document.getElementById('sobhyt')?.value || '');
      const inferred = inferNgheNghiep(cardStr, patAge);
      syncNgheNghiep(inferred.code, inferred.text);
    }

    // 8.1. Ngày BH đủ 5 năm từ lịch sử tiếp nhận HIS (#thoigian_du5namlientuc)
    const his5Nam = bn.NT_THOIDIEM_5NAM_LIENTUC || bn.KB_THOIDIEM_5NAM_LIENTUC || bn.THOIDIE_5NAM || bn.NGAY_DU_5NAM || '';
    if (his5Nam && hasValidBhytInfoOnForm()) {
      apply5NamValue(extract5NamDate(his5Nam));
    } else if (!hasValidBhytInfoOnForm()) {
      apply5NamValue('');
    }

    // 9. Thân nhân & Liên hệ (SĐT, Người LH, CMND Người LH, Họ tên cha, Họ tên mẹ, BHXH cha, BHXH mẹ, Quốc tịch)
    applyFamilyAndContact(bn);

    // 10. Địa chỉ & Số nhà
    if (activeVerifiedAddress) {
      setFieldSuccess('diachi', activeVerifiedAddress);
    } else if (bn.DIA_CHI) {
      setFieldSuccess('diachi', bn.DIA_CHI);
    }
    // Bỏ tự điền thông tin Ấp/ Số nhà vào ô sonha trên form tiếp nhận
    // if (bn.SO_NHA) setFieldSuccess('sonha', bn.SO_NHA);

    // 11. Mã khu vực (#manoidoituong)
    if (bn.MANOI_SINH_SONG) {
      setFieldSuccess('manoidoituong', bn.MANOI_SINH_SONG);
    } else if (bn.MA_BENH_NHAN && cardNo) {
      fetch(`${window.location.origin}/web_his/tiepnhan_select_manoisinhsong?mabenhnhan=${encodeURIComponent(bn.MA_BENH_NHAN)}&sothe=${encodeURIComponent(cardNo)}`)
        .then((r) => r.text())
        .then((val) => {
          if (val && val.trim()) setFieldSuccess('manoidoituong', val.trim());
        })
        .catch(() => {});
    }

    // 12. Địa chỉ CV30: Tỉnh / Huyện / Xã
    // YÊU CẦU: Nếu bệnh nhân có dữ liệu Địa chỉ (CV30) (*) đã lưu trong HIS thì ƯU TIÊN LẤY THEO HIS!
    // TUY NHIÊN: Khi vừa quét CCCD hoặc đã có địa chỉ chuẩn từ thẻ CCCD/BHYT (activeVerifiedAddress),
    // địa chỉ trên thẻ CCCD mới là căn cứ chuẩn xác hiện tại của công dân -> BẮT BUỘC nhận dạng theo thẻ CCCD!
    const hasFreshCardAddress = Boolean(activeVerifiedAddress && activeVerifiedAddress.trim().length >= 3);
    const hisHasCv30 = Boolean(bn.MAXA_CU_TRU && String(bn.MAXA_CU_TRU) !== '0');

    if (hasFreshCardAddress) {
      fillAddressAndCv30(activeVerifiedAddress);
    } else if (hisHasCv30) {
      if (bn.MATINH_CU_TRU) {
        const tinhEl = document.getElementById('matinh_cu_tru');
        if (tinhEl) {
          setSelectValue(tinhEl, bn.MATINH_CU_TRU);
          markTick(tinhEl);
        }
      }
      if (bn.MAHUYEN_CU_TRU) {
        const huyenEl = document.getElementById('mahuyen_cu_tru');
        if (huyenEl) {
          setSelectValue(huyenEl, bn.MAHUYEN_CU_TRU);
          markTick(huyenEl);
        }
      }
      if (bn.MAXA_CU_TRU) {
        const xaEl = document.getElementById('maxa_cu_tru');
        if (xaEl) {
          setSelectValue(xaEl, bn.MAXA_CU_TRU);
          markTick(xaEl);
        }
      }
      if (typeof window.reloadDataSelHuyen === 'function' && bn.MATINH_CU_TRU && bn.MAHUYEN_CU_TRU && bn.MAXA_CU_TRU && String(bn.MAXA_CU_TRU) !== '0') {
        try {
          window.reloadDataSelHuyen(
            bn.MATINH_CU_TRU,
            bn.MAHUYEN_CU_TRU,
            bn.MAXA_CU_TRU
          );
        } catch (e) {}
      }
      activeVerifiedAddressCv30 = {
        tinh: bn.MATINH_CU_TRU,
        huyen: bn.MAHUYEN_CU_TRU,
        xa: bn.MAXA_CU_TRU,
        fromHis: true,
        patientMaBn: extractMaBn(bn),
        patientCccd: (bn.CMT_BENHNHAN || bn.SO_CCCD || bn.SOCMT || bn.socmt || '').replace(/\D/g, ''),
        patientCard: (bn.MA_THE || bn.sobhyt || '').trim().toUpperCase()
      };
    } else {
      activeVerifiedAddressCv30 = null;
      // Bệnh nhân chưa có CV30 lưu trong HIS -> Tự động nhận dạng diaChi theo danh mục 2 cấp NSO
      const addrToParse = currentBhytCardData?.diaChi || bn.DIA_CHI || bn.DIACHI;
      if (addrToParse) {
        fillAddressAndCv30(addrToParse);
      }
    }

    // 13. Nơi ĐK KCB BĐ
    const hisDkbd = bn.NOIDANGKY_KCB || bn.NOI_DKKCB_BD || bn.MA_DKBD || bn.MADKBD || bn.MA_NOIDANGKY || bn.maKcbBd || bn.noidangky;
    if (hisDkbd) {
      setFieldSuccess('noidangky', hisDkbd);
      resolveHospitalName(hisDkbd, bn.TEN_NOIDANGKY_KCB || bn.TEN_CSKCB).then((name) => {
        if (name && name.trim()) setFieldSuccess('noidangky_hienthi', name.trim());
      }).catch(() => {});
    }

    // 14. Ngày đủ 5 năm từ hồ sơ HIS (nếu có)
    const d5 = extract5NamDate(bn.NT_THOIDIEM_5NAM_LIENTUC || bn.KB_THOIDIEM_5NAM_LIENTUC);
    if (d5 && hasValidBhytInfoOnForm()) {
      apply5NamValue(d5);
    } else if (!hasValidBhytInfoOnForm()) {
      apply5NamValue('');
    }

    // 15. Áp dụng quy tắc ô Cấp cứu theo URL
    applyCapcuuRuleByUrl();

    // 16. Xử lý Checkbox Đúng tuyến / Thông tuyến / Cấp cứu và chọn chuẩn Đối tượng KCB khi tìm thấy hồ sơ HIS
    // CHỈ thực hiện khi form đang mở (editable), TUYỆT ĐỐI không can thiệp thay đổi khi form đang bị khóa (view mode)
    if (!isTiepNhanFormLocked()) {
      const maDkbdVal = bn.NOIDANGKY_KCB || bn.NOI_DKKCB_BD || bn.MA_DKBD || bn.MADKBD || bn.MA_NOIDANGKY || bn.maKcbBd || bn.noidangky || currentBhytCardData?.maDKBD || document.getElementById('noidangky')?.value || '';
      const cleanDkbd5 = String(maDkbdVal || '').trim().replace(/\D/g, '').substring(0, 5);
      const cleanCskcb5 = String(cachedCskcbCode || '49008').trim().replace(/\D/g, '').substring(0, 5);

      // CHỈ can thiệp Checkbox và Đối tượng KCB khi ĐÃ BIẾT mã nơi ĐKKCB (đủ 5 số) hoặc đang Cấp cứu / Chuyển tuyến
      // TUYỆT ĐỐI KHÔNG can thiệp nếu chưa có mã ĐKKCB vì sẽ gây giật nhảy sang 1.12 rồi lại nhảy về 1.1
      if (checkIsCapCuu() || checkHasGiayChuyenTuyen() || (cleanDkbd5 && cleanDkbd5.length === 5)) {
        const isSameDkbdNow = Boolean(cleanDkbd5 && cleanCskcb5 && cleanDkbd5 === cleanCskcb5);
        const dungTuyenCheck = getDungTuyenCheckbox();
        const thongTuyenCheck = getThongTuyenCheckbox();

        if (checkIsCapCuu()) {
          if (dungTuyenCheck) { dungTuyenCheck.checked = true; markTick(dungTuyenCheck); }
        } else if (isSameDkbdNow || checkHasGiayChuyenTuyen()) {
          if (dungTuyenCheck) { dungTuyenCheck.checked = true; markTick(dungTuyenCheck); }
          if (thongTuyenCheck) { thongTuyenCheck.checked = false; removeTick(thongTuyenCheck); }
        } else {
          if (dungTuyenCheck) { dungTuyenCheck.checked = false; removeTick(dungTuyenCheck); }
          if (thongTuyenCheck) { thongTuyenCheck.checked = true; markTick(thongTuyenCheck); }
        }

        applyDoiTuongKcb(cleanDkbd5);
      }
    }
  }

  // Tự động đối soát và điền Mã y tế (#mayte) từ Thẻ BHYT nếu Mã y tế trên form chưa có
  let isAutoLookingUpCard = false;
  async function autoLookupPatientByCardIfNeeded(cardValue = null) {
    if (!isTiepNhanPage() || isAutoLookingUpCard) return;

    const mayteEl = document.getElementById('mayte') || document.querySelector('input[name="mayte"]');
    const curMayte = (mayteEl?.value || '').trim();
    if (curMayte && curMayte !== '0') return;

    const sobhytEl = document.getElementById('sobhyt') || document.querySelector('input[name="sobhyt"]');
    const rawCard = (cardValue || sobhytEl?.value || '').trim().replace(/\s+/g, '').toUpperCase();
    if (!rawCard || rawCard.length < 10 || rawCard.includes('|')) return;

    const now = Date.now();
    const lastAttemptTime = parseInt(sobhytEl?.dataset?.lastAutoLookupAttemptTime || '0', 10);
    // Nếu vừa thử tra cứu thẻ này trong vòng 2 giây trước, không spam network
    if (sobhytEl && sobhytEl.dataset.lastAutoLookupCard === rawCard && (now - lastAttemptTime < 2000)) {
      return;
    }
    if (sobhytEl) {
      sobhytEl.dataset.lastAutoLookupCard = rawCard;
      sobhytEl.dataset.lastAutoLookupAttemptTime = String(now);
    }

    const cccdVal = (getCccdInput()?.value || '').replace(/\D/g, '');
    const codes = [rawCard];
    if (rawCard.length > 10) {
      codes.push(rawCard.slice(-10));
    }
    if (cccdVal) {
      codes.push(cccdVal);
    }

    try {
      isAutoLookingUpCard = true;
      console.log('[BHYT Extension] Tự động tra cứu Mã y tế trong HIS từ Thẻ BHYT/CCCD (chỉ dùng định danh duy nhất):', rawCard);
      let found = await lookupPatientInHis(...codes);
      if (found) {
        const maBn = extractMaBn(found);
        if (maBn) {
          console.log('[BHYT Extension] Tự động đổ Mã y tế vào form thành công:', maBn);
          setFieldSuccess('mayte', maBn);
          if (sobhytEl) sobhytEl.dataset.lastAutoLookupSuccess = 'true';
        }
        currentHisPatient = found;
        savePatientToPersistentCache(found);
        // Bổ sung số điện thoại nếu trên form chưa có
        const sdtEl = findSdtInput();
        if (sdtEl && !sdtEl.value) {
          const sdt = extractPatientSdt(found);
          if (sdt) setFieldSuccess(sdtEl, sdt);
        }
      }
    } catch (err) {
      console.warn('[BHYT Extension] Lỗi khi tự động tra cứu Mã y tế qua thẻ:', err);
    } finally {
      isAutoLookingUpCard = false;
    }
  }

  // Giám sát liên tục và êm ái trên Form tiếp nhận: đảm bảo khi có Số thẻ BHYT thì Mã y tế luôn được điền tự động
  let tiepNhanMayteSupervisorInterval = null;
  function startTiepNhanMayteSupervisor() {
    if (tiepNhanMayteSupervisorInterval) return;
    tiepNhanMayteSupervisorInterval = setInterval(() => {
      if (!isTiepNhanPage() || isChecking || isClearingForm) return;

      const mayteEl = document.getElementById('mayte') || document.querySelector('input[name="mayte"]');
      const curMayte = (mayteEl?.value || '').trim();
      // Nếu đã có Mã y tế hợp lệ khác '0', không tốn tài nguyên
      if (curMayte && curMayte !== '0') return;

      const sobhytEl = document.getElementById('sobhyt') || document.querySelector('input[name="sobhyt"]');
      const rawCard = (sobhytEl?.value || '').trim().replace(/\s+/g, '').toUpperCase();
      if (!rawCard || rawCard.length < 10 || rawCard.includes('|')) return;

      // Đã có thẻ BHYT nhưng chưa có Mã y tế -> Kích hoạt tự động nạp Mã y tế ngay lập tức
      autoLookupPatientByCardIfNeeded(rawCard);
    }, 1200);
  }

  // Form tiếp nhận: Giữ nguyên 100% mặc định của HIS cho nút Lưu (không can thiệp code)

  // =========================================================================
  // 3. XỬ LÝ QUÉT QR CODE CCCD
  // Format: SO_CCCD|SO_CMND|HO_TEN|NGAY_SINH(DDMMYYYY)|GIOI_TINH|DIA_CHI|NGAY_CAP...
  // Ví dụ 1: 049086015379|205248013|Nguyễn Văn Thuận|05071986|Nam|Tổ 13, Thôn Trung Đông, Duy Xuyên, Đà Nẵng|09072026||||
  // Ví dụ 2: 049074003601|205245525|Mai Rê|01011974|Nam|Thi Lai, Duy Trinh, Duy Xuyên, Quảng Nam|31082021
  // =========================================================================
  // =========================================================================
  // DỌN SẠCH CÁC Ô NHẬP LIỆU BỊ DÍNH MÃ QR THÔ KHI NGƯỜI DÙNG QUÉT KHÔNG ĐÚNG Ô
  // =========================================================================
  function cleanAllInputsWithStrayQr(validCccd = '', validSobhyt = '') {
    try {
      const inputs = document.querySelectorAll('#socmt, input[name="socmt"], #sobhyt, input[name="sobhyt"], #chuoinhandang, #hoten, #namsinh, #diachi');
      inputs.forEach(inp => {
        const v = (inp.value || '').trim();
        if (v.includes('|')) {
          const idName = ((inp.id || '') + ' ' + (inp.name || '')).toLowerCase();
          if ((idName.includes('socmt') || idName.includes('cccd')) && validCccd) {
            inp.value = validCccd;
          } else if (idName.includes('sobhyt') && validSobhyt) {
            inp.value = validSobhyt;
          } else {
            inp.value = '';
          }
        }
      });
    } catch (err) {
      console.warn('[BHYT Extension] Lỗi dọn sạch input chứa mã QR thô:', err);
    }
  }

  // =========================================================================
  // 3.1 XỬ LÝ QUÉT QR CODE THẺ GIẤY BHYT (CHUẨN BHXH VIỆT NAM)
  // Format: MA_THE|HO_TEN_HEX|NGAY_SINH|GIOI_TINH|DIA_CHI_HEX|MA_CSKCB|GT_TU|GT_DEN|NGAY_CAP|MA_BHXH|...|NGAY_DU_5_NAM|CHUOI_KT|$
  // Ví dụ: TS2494920738521|4e677579e1bb856e205468e1bb8b204261|23/09/1954|2|48c3b261204e616d2c2058c3a320447579205472756e672c20487579e1bb876e2044757920587579c3aa6e2c2054e1bb896e68205175e1baa36e67204e616d|49 - 006|01/06/2021|-|30/06/2021|49074920738521|-|4| 01/04/2017|6073cc49a85a820d-1202|$
  // =========================================================================
  async function handleQrTheGiayBhytScan(cleanRaw, inputEl) {
    console.log('[BHYT Extension] Bắt đầu nhận dạng mã QR THẺ GIẤY BHYT:', cleanRaw);

    isUserInTiepNhanThemMoi = true;
    isCccdLockedAfterCheck = false;
    unlockCccdInput();

    const parts = cleanRaw.split('|');
    if (!parts || parts.length < 5) return;

    const maThe = (parts[0] || '').trim().toUpperCase();

    // Dọn sạch mọi ô input vô tình dính chuỗi quét QR thô (có chứa '|')
    cleanAllInputsWithStrayQr('', maThe);
    const hoTenRaw = (parts[1] || '').trim();
    // Giải mã HEX nếu chuỗi họ tên được mã hóa hex UTF-8
    const hoTen = (/^[0-9a-fA-F]{4,}$/.test(hoTenRaw) && hoTenRaw.length % 2 === 0 ? decodeHexUtf8(hoTenRaw) : hoTenRaw).trim().toUpperCase();
    const rawDob = (parts[2] || '').trim();
    const rawGender = (parts[3] || '').trim(); // 1: Nam, 2: Nữ
    const diaChiRaw = (parts[4] || '').trim();
    // Giải mã HEX nếu địa chỉ được mã hóa hex UTF-8
    const diaChi = (/^[0-9a-fA-F]{4,}$/.test(diaChiRaw) && diaChiRaw.length % 2 === 0 ? decodeHexUtf8(diaChiRaw) : diaChiRaw).trim();
    const maCskcbRaw = (parts[5] || '').trim();
    const maCskcb = maCskcbRaw.replace(/[^a-zA-Z0-9]/g, ''); // VD: '49 - 006' -> '49006'
    const gtTheTu = (parts[6] || '').trim();
    const gtTheDen = (parts[7] || '').trim();
    const ngayDu5Nam = parts.length > 12 ? (parts[12] || '').trim() : '';

    // Chuẩn hóa ngày sinh
    let formattedDob = rawDob;
    if (/^\d{8}$/.test(rawDob)) {
      formattedDob = `${rawDob.substring(0, 2)}/${rawDob.substring(2, 4)}/${rawDob.substring(4, 8)}`;
    }

    // Xóa form nếu đổi sang bệnh nhân mới
    const currentThe = currentHisPatient?.SO_THE_BAOHIEM_YTE || currentHisPatient?.SO_THE_BHYT;
    const isNewPatient = maThe !== currentThe || !currentHisPatient;
    if (isNewPatient) {
      clearPreviousPatientForm(true);
    }

    lastCheckedMaThe = maThe;
    lastScannedQrDob = formattedDob;
    setVerifiedDob(formattedDob);

    // 1. Điền Mã thẻ BHYT (15 ký tự) vào ô input và các ô thẻ trên form
    if (inputEl) {
      ensureInputEditable(inputEl);
      const inId = (inputEl.id || '').toLowerCase();
      const inName = (inputEl.name || '').toLowerCase();
      if (inId.includes('sobhyt') || inName.includes('sobhyt') || inId.includes('the') || inName.includes('the') || inId.includes('nhandang')) {
        inputEl.value = maThe;
      } else if (inId.includes('socmt') || inName.includes('socmt') || inId.includes('cccd') || inName.includes('cccd')) {
        inputEl.value = '';
      }
    }
    setFieldSuccess('sobhyt', maThe);

    // 2. Điền Họ và tên (chuyển sang IN HOA chuẩn)
    if (hoTen) {
      setFieldSuccess('hoten', hoTen);
    }

    // 3. Bóc tách và điền trực tiếp chính xác tuyệt đối vào ô Ngày sinh (*) name="namsinh", id="namsinh"
    fillNgaySinhFields(formattedDob, rawDob);

    // 4. Điền Giới tính (1 -> Nam, 2 -> Nữ)
    const isNam = rawGender === '1';
    setFieldSuccess('gioitinh', isNam ? '1' : '0');
    const cbGtEl = document.getElementById('cbgioitinh') || document.querySelector('select[name="cbgioitinh"]');
    if (cbGtEl) {
      setSelectValue(cbGtEl, isNam ? 'true' : 'false');
      if (cbGtEl.value !== (isNam ? 'true' : 'false')) {
        setSelectValue(cbGtEl, isNam ? '1' : '0');
      }
      cbGtEl.classList.remove('bhyt-ext-field-success', 'bhyt-ext-field-mismatch');
      cbGtEl.style.removeProperty('background-color');
      cbGtEl.style.removeProperty('border-color');
      cbGtEl.style.removeProperty('color');
    }
    const radioNam = document.querySelector('input[type="radio"][value="1"], input[type="radio"][id*="nam"], input[type="radio"][name*="gioitinh"][value="1"]');
    const radioNu = document.querySelector('input[type="radio"][value="0"], input[type="radio"][value="2"], input[type="radio"][id*="nu"], input[type="radio"][name*="gioitinh"][value="0"]');
    if (isNam && radioNam) {
      radioNam.checked = true;
      radioNam.dispatchEvent(new Event('change', { bubbles: true }));
    } else if (!isNam && radioNu) {
      radioNu.checked = true;
      radioNu.dispatchEvent(new Event('change', { bubbles: true }));
    }

    // 5. Điền Địa chỉ & phân tách Tỉnh/Huyện/Xã (CV30)
    if (diaChi) {
      activeVerifiedAddress = diaChi.trim();
      setFieldSuccess('diachi', diaChi.trim());
      fillAddressAndCv30(diaChi.trim());
    }

    // 6. Điền Nơi ĐK KCB ban đầu
    if (maCskcb) {
      setFieldSuccess('macskcbbd', maCskcb);
      setFieldSuccess('noicap_bhyt', maCskcb);
      resolveHospitalName(maCskcb, '').then((hName) => {
        if (hName && hName.trim()) setFieldSuccess('tennoicap_bhyt', hName.trim());
      }).catch(() => {});
    }

    // 7. Điền hạn thẻ Từ ngày / Đến ngày
    if (gtTheTu && gtTheTu !== '-') {
      setFieldSuccess('tungay_bhyt', gtTheTu);
      setFieldSuccess('gt_the_tu', gtTheTu);
    }
    if (gtTheDen && gtTheDen !== '-') {
      setFieldSuccess('denngay_bhyt', gtTheDen);
      setFieldSuccess('gt_the_den', gtTheDen);
    }

    // 7.1. Tự động xác định Nghề nghiệp theo thẻ BHYT & tuổi nếu người dùng chưa tự sửa
    if (!isUserModifiedNgheNghiep) {
      const patAge = calculateAge(formattedDob || rawDob)?.tuoi || 0;
      const inferred = inferNgheNghiep(maThe, patAge);
      syncNgheNghiep(inferred.code, inferred.text);
    }

    // 8. Điền Ngày đủ 5 năm liên tục
    if (ngayDu5Nam && ngayDu5Nam !== '-') {
      apply5NamValue(ngayDu5Nam);
    }

    // Đồng bộ Quốc tịch mặc định 01 (Việt Nam) & Quy tắc Cấp cứu theo URL
    syncQuocTich('01');
    applyCapcuuRuleByUrl();

    // Hiển thị Banner đang kiểm tra BHYT
    showBannerChecking(`⏳ Đã nhận dạng QR Thẻ giấy BHYT: ${hoTen} (${maThe}). Đang kiểm tra BHYT trên Cổng BHXH...`);

    // 9. Tra cứu hồ sơ cũ trong HIS nếu có theo mã thẻ để đồng bộ mã y tế, CCCD và Số ĐT (CHẠY SONG SONG TRÁNH BLOCK QUÉT QR)
    lookupPatientInHis(maThe).then((bn) => {
      if (bn) {
        currentHisPatient = bn;
        if (bn.MA_BENH_NHAN) {
          setFieldSuccess('mayte', bn.MA_BENH_NHAN);
        }
        const sdt = extractPatientSdt(bn);
        if (sdt) {
          const elSdt = findSdtInput();
          if (elSdt && (!elSdt.value || !elSdt.value.trim())) {
            elSdt.value = sdt;
            setFieldSuccess(elSdt, sdt);
            if (window.$) try { window.$(elSdt).val(sdt).trigger('input').trigger('change'); } catch (e) {}
          }
        }
        applyFamilyAndContact(bn);
        if (bn.CMT_BENHNHAN || bn.socmt) {
          const foundCccd = (bn.CMT_BENHNHAN || bn.socmt).replace(/\D/g, '');
          if (foundCccd && !document.getElementById('socmt')?.value) {
            setFieldSuccess('socmt', foundCccd);
            updateCccdCounter(foundCccd);
          }
        }
      }
    }).catch(() => {});

    // 10. KÍCH HOẠT GỌI CỔNG TIẾP NHẬN DỮ LIỆU BHXH VIỆT NAM THỰC TẾ NGAY TỨC THÌ (0ms)
    executeBhytCheck('', hoTen, formattedDob, maThe);
  }

  // =========================================================================
  // 3.2 XỬ LÝ QUÉT QR CODE CCCD (CHUẨN BỘ CÔNG AN)
  // Format: SO_CCCD|SO_CMND|HO_TEN|NGAY_SINH(DDMMYYYY)|GIOI_TINH|DIA_CHI|NGAY_CAP...
  // =========================================================================
  async function handleQrCccdScan(cleanRaw, inputEl) {
    console.log('[BHYT Extension] Bắt đầu nhận dạng mã QR CCCD:', cleanRaw);

    const parts = cleanRaw.split('|');
    if (!parts || parts.length < 6) return;

    const soCccd = (parts[0] || '').trim();
    const soCmnd = (parts[1] || '').trim();
    const hoTen = (parts[2] || '').trim().toUpperCase();
    const rawDob = (parts[3] || '').trim();
    const rawGender = (parts[4] || '').trim();
    const rawAddress = (parts[5] || '').trim();

    const currentYear = new Date().getFullYear();

    // Chuẩn hóa ngày sinh: 8 số DDMMYYYY -> DD/MM/YYYY, 4 số -> YYYY
    let formattedDob = rawDob;
    if (/^\d{8}$/.test(rawDob)) {
      const p1 = parseInt(rawDob.substring(0, 4), 10);
      const p2 = parseInt(rawDob.substring(4, 8), 10);
      if (p2 >= 1900 && p2 <= currentYear) {
        formattedDob = `${rawDob.substring(0, 2)}/${rawDob.substring(2, 4)}/${rawDob.substring(4, 8)}`;
      } else if (p1 >= 1900 && p1 <= currentYear) {
        formattedDob = `${rawDob.substring(6, 8)}/${rawDob.substring(4, 6)}/${rawDob.substring(0, 4)}`;
      } else {
        formattedDob = `${rawDob.substring(0, 2)}/${rawDob.substring(2, 4)}/${rawDob.substring(4, 8)}`;
      }
    } else if (/^\d{4}$/.test(rawDob)) {
      const y = parseInt(rawDob, 10);
      if (y >= 1900 && y <= currentYear) {
        formattedDob = rawDob;
      } else {
        console.warn('[BHYT Extension] Bỏ qua ngày sinh 4 số không hợp lệ từ QR CCCD:', rawDob);
        formattedDob = '';
      }
    } else if (rawDob.includes('/')) {
      const dParts = rawDob.split('/');
      const y = parseInt(dParts[dParts.length - 1], 10);
      if (y >= 1900 && y <= currentYear) {
        formattedDob = rawDob;
      } else {
        formattedDob = '';
      }
    }

    // Kiểm tra bệnh nhân mới so với lượt trước
    const currentCmt = currentHisPatient?.CMT_BENHNHAN || currentHisPatient?.socmt;
    const isNewPatient = soCccd !== currentCmt || !currentHisPatient;
    if (isNewPatient) {
      clearPreviousPatientForm(true);
    }

    lastCheckedCccd = soCccd;
    lastScannedQrCccd = soCccd;
    lastScannedQrHoTen = hoTen;
    if (formattedDob) {
      lastScannedQrDob = formattedDob;
      setVerifiedDob(formattedDob);
    }

    // 1. Điền số CCCD (12 số) vào ô input đã quét và các ô CCCD trên form tiếp nhận
    if (inputEl) {
      ensureInputEditable(inputEl);
      const inId = (inputEl.id || '').toLowerCase();
      const inName = (inputEl.name || '').toLowerCase();
      const isCccdInput = inId.includes('socmt') || inId.includes('cccd') || inId.includes('cmnd') || inName.includes('socmt') || inName.includes('cccd');
      if (isCccdInput) {
        inputEl.value = soCccd;
      } else if (inId === 'sobhyt' || inName === 'sobhyt') {
        inputEl.value = '';
      }
    }
    setFieldSuccess('socmt', soCccd);
    updateCccdCounter(soCccd);

    // 2. Điền Họ và tên (chuyển sang IN HOA chuẩn hồ sơ bệnh án)
    if (hoTen) {
      setFieldSuccess('hoten', hoTen);
    }

    // 3. Bóc tách và điền trực tiếp chính xác tuyệt đối vào ô Ngày sinh (*) name="namsinh", id="namsinh"
    fillNgaySinhFields(formattedDob, rawDob);

    // 4. Điền Giới tính (Nam -> '1' / 'true', Nữ -> '0' / 'false')
    const isNam = rawGender.toLowerCase().includes('nam') || (rawGender === '1');
    setFieldSuccess('gioitinh', isNam ? '1' : '0');
    const cbGtEl = document.getElementById('cbgioitinh') || document.querySelector('select[name="cbgioitinh"]');
    if (cbGtEl) {
      setSelectValue(cbGtEl, isNam ? 'true' : 'false');
      if (cbGtEl.value !== (isNam ? 'true' : 'false')) {
        setSelectValue(cbGtEl, isNam ? '1' : '0');
      }
      cbGtEl.classList.remove('bhyt-ext-field-success', 'bhyt-ext-field-mismatch');
      cbGtEl.style.removeProperty('background-color');
      cbGtEl.style.removeProperty('border-color');
      cbGtEl.style.removeProperty('color');
    }
    const radioNam = document.querySelector('input[type="radio"][value="1"], input[type="radio"][id*="nam"], input[type="radio"][name*="gioitinh"][value="1"]');
    const radioNu = document.querySelector('input[type="radio"][value="0"], input[type="radio"][value="2"], input[type="radio"][id*="nu"], input[type="radio"][name*="gioitinh"][value="0"]');
    if (isNam && radioNam) {
      radioNam.checked = true;
      radioNam.dispatchEvent(new Event('change', { bubbles: true }));
    } else if (!isNam && radioNu) {
      radioNu.checked = true;
      radioNu.dispatchEvent(new Event('change', { bubbles: true }));
    }

    // 5. Điền Địa chỉ & phân tách Tỉnh/Huyện/Xã (CV30)
    if (rawAddress) {
      activeVerifiedAddress = rawAddress.trim();
      setFieldSuccess('diachi', rawAddress.trim());
      // Luôn luôn nhận dạng địa chỉ mới nhất từ CCCD vừa quét để chọn đúng Tỉnh và Xã từ danh mục HIS
      fillAddressAndCv30(rawAddress.trim());
    }

    // Đồng bộ Quốc tịch mặc định 01 (Việt Nam) & Quy tắc Cấp cứu theo URL
    syncQuocTich('01');
    applyCapcuuRuleByUrl();

    // 5.1 Thông tin cha, mẹ, người liên hệ (áp dụng cho thẻ CCCD trẻ em dưới 14 tuổi, kiểm tra chuỗi tên hợp lệ)
    const isRealName = (s) => Boolean(s && s.length >= 3 && !/^\d+$/.test(s) && !/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(s));
    let hoTenCha = '';
    let hoTenMe = '';
    for (let pIdx = 7; pIdx < parts.length; pIdx++) {
      const pVal = (parts[pIdx] || '').trim().toUpperCase();
      if (isRealName(pVal)) {
        if (!hoTenCha) {
          hoTenCha = pVal;
        } else if (!hoTenMe && pVal !== hoTenCha) {
          hoTenMe = pVal;
          break;
        }
      }
    }
    
    if (hoTenCha) {
      setFieldSuccess('ho_ten_cha', hoTenCha);
    }
    if (hoTenMe) {
      setFieldSuccess('ho_ten_me', hoTenMe);
    }
    
    const nguoiLienHe = isRealName(hoTenMe) ? hoTenMe : (isRealName(hoTenCha) ? hoTenCha : '');
    if (nguoiLienHe) {
      setFieldSuccess('nguoilienhe', nguoiLienHe);
    }

    // 5.2. Tự động áp dụng quy tắc nghề nghiệp theo tuổi và thẻ BHYT
    if (!isUserModifiedNgheNghiep) {
      const patAge = calculateAge(formattedDob || rawDob)?.tuoi;
      const curCard = (document.getElementById('sobhyt')?.value || '').trim();
      const inferred = inferNgheNghiep(curCard, patAge);
      syncNgheNghiep(inferred.code, inferred.text);
    }

    // Hiển thị Banner đang kiểm tra BHYT
    showBannerChecking(`⏳ Đã nhận dạng QR CCCD: ${hoTen} (${soCccd}). Đang kiểm tra BHYT trên Cổng BHXH...`);

    // 6. Tra cứu hồ sơ cũ trong HIS nếu có để đồng bộ mã y tế và Số ĐT (CHẠY SONG SONG TRÁNH BLOCK QUÉT QR)
    lookupPatientInHis(soCccd, soCmnd).then((bn) => {
      if (bn) {
        currentHisPatient = bn;
        const mb = extractMaBn(bn);
        if (mb) {
          setFieldSuccess('mayte', mb);
        }
        const sdt = extractPatientSdt(bn);
        if (sdt) {
          setFieldSuccess('sodt', sdt);
        }
        applyFamilyAndContact(bn);
      }
    }).catch(() => {});

    // 7. KÍCH HOẠT GỌI CỔNG TIẾP NHẬN DỮ LIỆU BHXH VIỆT NAM THỰC TẾ NGAY TỨC THÌ (0ms)
    executeBhytCheck(soCccd, hoTen, formattedDob, '');
  }

  // =========================================================================
  // 3. ĐIỀU PHỐI XỬ LÝ QUÉT QR CODE (TỰ ĐỘNG PHÂN BIỆT THẺ GIẤY BHYT VÀ CCCD)
  // =========================================================================
  let lastProcessedQrRaw = '';
  let lastProcessedQrTime = 0;

  async function handleQrScan(rawText, inputEl) {
    if (!rawText) return;
    const cleanRaw = String(rawText).replace(/[\r\n]+/g, '').trim();
    if (!cleanRaw.includes('|')) return;

    // Đảm bảo mở khóa ô CCCD và đánh dấu phiên tiếp nhận để nạp dữ liệu và kiểm tra BHYT
    isUserInTiepNhanThemMoi = true;
    isCccdLockedAfterCheck = false;
    unlockCccdInput();

    const now = Date.now();
    if (cleanRaw === lastProcessedQrRaw && (now - lastProcessedQrTime) < 1000) {
      console.log('[BHYT Extension] Bỏ qua mã QR trùng lặp vừa xử lý trong 1s');
      return;
    }
    lastProcessedQrRaw = cleanRaw;
    lastProcessedQrTime = now;

    // 1. Phân loại nếu là mã QR Thẻ giấy BHYT (chuẩn BHXH Việt Nam)
    if (isCompleteQrTheGiayBhyt(cleanRaw)) {
      return handleQrTheGiayBhytScan(cleanRaw, inputEl);
    }

    // 2. Mặc định là mã QR CCCD (chuẩn Bộ Công An)
    return handleQrCccdScan(cleanRaw, inputEl);
  }

  // =========================================================================
  // 4. XỬ LÝ NHẬP TAY CCCD -> TÌM TRONG HIS & TRA CỨU CỔNG BHXH THẬT
  // =========================================================================
  async function handleManualCccd(soCccd) {
    console.log('[BHYT Extension] Nhập tay CCCD:', soCccd);
    lastCheckedCccd = soCccd;
    setFieldSuccess('socmt', soCccd);
    syncQuocTich('01');
    applyCapcuuRuleByUrl();

    triggerBhytCheckFromForm();
  }

  // =========================================================================
  // 4.1 TRÍCH XUẤT THÔNG TIN BỆNH NHÂN TỪ DANH SÁCH TIẾP NHẬN (JQGRID / DOM)
  // =========================================================================
  function extractPatientFromSelectedGridRow(doc = document, explicitRow = null) {
    if (explicitRow && explicitRow.closest && explicitRow.closest('.window, .modal, .ui-dialog, [role="dialog"], #modalLichSu, [id*="lichsu"], [id*="history"], [id*="lskcb"], [id*="kcb"], table[id*="lichsu"], [class*="history"]')) {
      return null;
    }
    let result = null;

    const clean = (val) => {
      if (!val) return '';
      const tmp = document.createElement('div');
      tmp.innerHTML = String(val);
      return (tmp.textContent || tmp.innerText || '').trim();
    };

    // 0. Kiểm tra từ dataset.selectedPatientJson do Main World (interceptor.js) ghi nhận từ jqGrid API
    try {
      const jsonStr = doc?.documentElement?.dataset?.selectedPatientJson;
      if (jsonStr) {
        const row = JSON.parse(jsonStr);
        if (row && typeof row === 'object') {
          const hoTen = clean(row.TEN_BENH_NHAN || row.HOTEN || row.hoten || row.tenbenhnhan || row.TEN_BN);
          const rawCard = clean(row.SO_THE_BHYT || row.SOBHYT || row.MA_THE || row.sobhyt || row.mathe || row.SO_THE_BAOHIEM_YTE);
          const soCccd = clean(row.CMT_BENHNHAN || row.SO_CCCD || row.SOCMT || row.socmt || row.cccd || row.CMND);
          const ngaySinh = clean(row.NGAY_SINH || row.NGAYSINH || row.NAMSINH || row.namsinh || row.ngaysinh);
          const mayte = clean(row.MA_BENH_NHAN || row.MABENHNHAN || row.MAYTE || row.mayte || row.mabn);
          const gioiTinh = clean(row.GIOI_TINH || row.GIOITINH || row.gioitinh);
          const diaChi = clean(row.DIA_CHI || row.DIACHI || row.diachi);
          const maKcbBd = clean(row.NOIDANGKY_KCB || row.MA_NOIDANGKY || row.noidangky);
          const raw5Nam = clean(row.NT_THOIDIEM_5NAM_LIENTUC || row.KB_THOIDIEM_5NAM_LIENTUC || row.THOIDIE_5NAM || row.NGAY_DU_5NAM || row.THOIGIAN_DU5NAM || row.NGAY_DU_5_NAM || row.thoigian_du5namlientuc || row.ngaydu5nam);

          if (hoTen || rawCard || soCccd || mayte) {
            result = {
              hoTen,
              maThe: rawCard,
              soCccd: (soCccd || '').replace(/\D/g, ''),
              ngaySinh: formatBhxhDate(ngaySinh),
              mayte,
              gioiTinh,
              diaChi,
              maKcbBd,
              ngayDu5Nam: formatBhxhDate(raw5Nam),
              rawData: row
            };
          }
        }
      }
    } catch (e) {}

    // 1. Dùng jqGrid API nếu hệ thống có jQuery jqGrid khả dụng
    if (!result) {
      const win = doc.defaultView || window;
      if (win.$ && typeof win.$.fn?.jqGrid === 'function') {
        try {
          const gridSelectors = ['#list200', '#danhsachtiepnhan', '.ui-jqgrid-btable', 'table[id*="danhsach"]', 'table[id*="ds_"]'];
          for (const sel of gridSelectors) {
            if (result) break;
            const $grids = win.$(sel);
            $grids.each(function () {
              if (result) return;
              const $g = win.$(this);
              const selId = explicitRow?.id || $g.jqGrid('getGridParam', 'selrow');
              if (selId) {
                const row = $g.jqGrid('getRowData', selId);
                if (row && typeof row === 'object') {
                  const hoTen = clean(row.TEN_BENH_NHAN || row.HOTEN || row.hoten || row.tenbenhnhan || row.TEN_BN);
                  const rawCard = clean(row.SO_THE_BHYT || row.SOBHYT || row.MA_THE || row.sobhyt || row.mathe || row.SO_THE_BAOHIEM_YTE);
                  const soCccd = clean(row.CMT_BENHNHAN || row.SO_CCCD || row.SOCMT || row.socmt || row.cccd || row.CMND);
                  const ngaySinh = clean(row.NGAY_SINH || row.NGAYSINH || row.NAMSINH || row.namsinh || row.ngaysinh);
                  const mayte = clean(row.MA_BENH_NHAN || row.MABENHNHAN || row.MAYTE || row.mayte || row.mabn);
                  const gioiTinh = clean(row.GIOI_TINH || row.GIOITINH || row.gioitinh);
                  const diaChi = clean(row.DIA_CHI || row.DIACHI || row.diachi);
                  const maKcbBd = clean(row.NOIDANGKY_KCB || row.MA_NOIDANGKY || row.noidangky);
                  const raw5Nam = clean(row.NT_THOIDIEM_5NAM_LIENTUC || row.KB_THOIDIEM_5NAM_LIENTUC || row.THOIDIE_5NAM || row.NGAY_DU_5NAM || row.THOIGIAN_DU5NAM || row.NGAY_DU_5_NAM || row.thoigian_du5namlientuc || row.ngaydu5nam);

                  if (hoTen || rawCard || soCccd || mayte) {
                    result = {
                      hoTen,
                      maThe: rawCard,
                      soCccd: (soCccd || '').replace(/\D/g, ''),
                      ngaySinh: formatBhxhDate(ngaySinh),
                      mayte,
                      gioiTinh,
                      diaChi,
                      maKcbBd,
                      ngayDu5Nam: formatBhxhDate(raw5Nam),
                      rawData: row
                    };
                  }
                }
              }
            });
          }
        } catch (err) {}
      }
    }

    // 2. Quét DOM trực tiếp từ dòng được chọn hoặc được highlight trong bảng
    if (!result) {
      const activeRow = explicitRow || doc.querySelector('.ui-jqgrid-btable tr.ui-state-highlight, tr.jqgrow.ui-state-highlight, #list200 tr.ui-state-highlight, #danhsachtiepnhan tr.ui-state-highlight, table[id*="danhsach"] tr.ui-state-highlight, tr.ui-state-highlight, tr[aria-selected="true"], tr.selected, tr.datagrid-row-selected');
      if (activeRow) {
        let hoTen = '', maThe = '', soCccd = '', ngaySinh = '', mayte = '', gioiTinh = '', diaChi = '', maKcbBd = '', ngayDu5Nam = '', soDienThoai = '';
        activeRow.querySelectorAll('td').forEach((td) => {
          const desc = (td.getAttribute('aria-describedby') || td.getAttribute('field') || td.getAttribute('data-field') || td.className || '').toLowerCase();
          const txt = (td.textContent || td.title || '').trim();
          if (!txt) return;

          if (desc.includes('so_the') || desc.includes('sobhyt') || desc.includes('mathe') || desc.includes('ma_the') || desc.includes('sothe')) {
            maThe = maThe || txt;
          } else if (desc.includes('hoten') || desc.includes('ten_benh_nhan') || desc.includes('tenbn') || desc.includes('ten_bn')) {
            hoTen = hoTen || txt;
          } else if (desc.includes('ngaysinh') || desc.includes('ngay_sinh') || desc.includes('namsinh')) {
            ngaySinh = ngaySinh || txt;
          } else if (desc.includes('cmt') || desc.includes('cccd') || desc.includes('cmnd')) {
            soCccd = soCccd || txt;
          } else if (desc.includes('mayte') || desc.includes('mabenhnhan') || desc.includes('mabn') || desc.includes('ma_benh_nhan') || desc.includes('ma_bn')) {
            mayte = mayte || txt;
          } else if (desc.includes('gioitinh') || desc.includes('gioi_tinh')) {
            gioiTinh = gioiTinh || txt;
          } else if (desc.includes('diachi') || desc.includes('dia_chi')) {
            diaChi = diaChi || txt;
          } else if (desc.includes('noidangky') || desc.includes('ma_kcbbd') || (desc.includes('makcb') && !desc.includes('muc') && !desc.includes('tyle'))) {
            if (txt && !txt.includes('%') && !/^\d{1,3}\s*%?$/.test(txt)) {
              maKcbBd = maKcbBd || txt;
            }
          } else if (desc.includes('5nam') || desc.includes('du_5_nam') || desc.includes('thoigian_du5nam') || desc.includes('du5nam')) {
            ngayDu5Nam = ngayDu5Nam || txt;
          } else if (desc.includes('sodt') || desc.includes('dienthoai') || desc.includes('so_dt') || desc.includes('sodienthoai') || desc.includes('tel') || desc.includes('phone')) {
            soDienThoai = soDienThoai || txt;
          }
        });

        if (!hoTen && !maThe) {
          const cells = Array.from(activeRow.querySelectorAll('td')).map(td => (td.textContent || td.title || '').trim()).filter(Boolean);
          const genericWords = ['chờ khám', 'đang khám', 'đã khám', 'chuyển phòng', 'chuyển tuyến', 'nhập viện', 'tất cả', 'khám bệnh', 'bhyt', 'viện phí', 'thu phí', 'nam', 'nữ', 'cấp cứu', 'đúng tuyến', 'trái tuyến', 'thông tuyến'];
          for (const c of cells) {
            if (isValidBhytCardFormat(c)) maThe = maThe || c.toUpperCase();
            else if (/^\d{9,12}$/.test(c)) soCccd = soCccd || c;
            else if (/^0\d{8,10}$/.test(c) && !soDienThoai) soDienThoai = c;
            else if (/^\d{1,2}\/\d{1,2}\/\d{4}$|^\d{4}$/.test(c)) ngaySinh = ngaySinh || c;
            else if (/^\d{6,8}$/.test(c) && !mayte) mayte = c;
            else if (c.length >= 4 && !/\d/.test(c) && !hoTen && !genericWords.includes(c.toLowerCase())) hoTen = c;
          }
        }

        if (hoTen || maThe || soCccd || mayte) {
          result = {
            hoTen,
            maThe,
            soCccd: (soCccd || '').replace(/\D/g, ''),
            ngaySinh: formatBhxhDate(ngaySinh),
            mayte,
            gioiTinh,
            diaChi,
            maKcbBd,
            ngayDu5Nam: formatBhxhDate(ngayDu5Nam),
            soDienThoai,
            SO_DIEN_THOAI: soDienThoai,
            sodt: soDienThoai
          };
        }
      }
    }

    // 3. Quét các iframes nếu bảng nằm bên trong iframe con
    if (!result) {
      try {
        const iframes = doc.querySelectorAll('iframe');
        for (const ifr of iframes) {
          try {
            const ifrDoc = ifr.contentDocument || ifr.contentWindow?.document;
            if (ifrDoc) {
              const r = extractPatientFromSelectedGridRow(ifrDoc);
              if (r) {
                result = r;
                break;
              }
            }
          } catch (e) {}
        }
      } catch (e) {}
    }

    // 4. Fallback thông tin bệnh nhân đã lưu lần chọn gần nhất (CHỈ khi đang ở tab Danh sách tiếp nhận)
    if (!result && lastSelectedGridPatient && isViewingDanhSachTab) {
      result = lastSelectedGridPatient;
    }

    return result;
  }

  // =========================================================================
  // 4.2 KÍCH HOẠT TRA CỨU TỪ DỮ LIỆU TRÊN FORM TIẾP ĐÓN HOẶC DANH SÁCH TIẾP NHẬN
  // =========================================================================
  let formCheckDebounceTimer = null;
  let lastCheckedFormSignature = '';
  let lastCheckedFormTime = 0;

  function triggerBhytCheckFromForm(delay = 200, force = false) {
    if (!force && (isClearingForm || isChecking)) return;
    clearTimeout(formCheckDebounceTimer);
    if (force || delay === 0) {
      doTriggerBhytCheckFromForm(true);
    } else {
      formCheckDebounceTimer = setTimeout(() => doTriggerBhytCheckFromForm(false), delay);
    }
  }

  async function doTriggerBhytCheckFromForm(force = false) {
    if (!force && (isClearingForm || isChecking)) return;
    if (force) {
      isChecking = false;
      lastCheckedFormSignature = '';
    }

    const cccdEl = getCccdInput();
    const sobhytEl = document.getElementById('sobhyt');
    const nhandangEl = document.getElementById('chuoinhandang') || document.querySelector('input[name="chuoinhandang"], [id*="chuoinhandang"], [id*="chuoi_nhandang"]');

    // Nếu ô CCCD, Thẻ BHYT hoặc Chuỗi nhận dạng đang chứa chuỗi mã QR có dấu '|' -> Chuyển ngay sang xử lý QR
    if (sobhytEl && sobhytEl.value && sobhytEl.value.includes('|')) {
      handleQrScan(sobhytEl.value, sobhytEl);
      return;
    }
    if (cccdEl && cccdEl.value && cccdEl.value.includes('|')) {
      handleQrScan(cccdEl.value, cccdEl);
      return;
    }
    if (nhandangEl && nhandangEl.value && nhandangEl.value.includes('|')) {
      handleQrScan(nhandangEl.value, nhandangEl);
      return;
    }

    const getRealVal = (elId) => {
      const el = (typeof elId === 'string') ? document.getElementById(elId) : elId;
      if (!el) return '';
      const wrap = (typeof findEasyUiWrapper === 'function') ? findEasyUiWrapper(el) : null;
      const txt = wrap ? wrap.querySelector('.textbox-text') : null;
      return (txt?.value || el.value || '').trim();
    };

    const cccdWrap = cccdEl ? findEasyUiWrapper(cccdEl) : null;
    const cccdTxt = cccdWrap ? cccdWrap.querySelector('.textbox-text') : null;
    let soCccd = (cccdTxt?.value || cccdEl?.value || '').replace(/\D/g, '');

    const sobhytWrap = sobhytEl ? findEasyUiWrapper(sobhytEl) : null;
    const sobhytTxt = sobhytWrap ? sobhytWrap.querySelector('.textbox-text') : null;
    let rawMaThe = (sobhytTxt?.value || sobhytEl?.value || '').trim().toUpperCase();

    // Đồng bộ tức thì giá trị nhập từ UI vào input ẩn để không bị mất dữ liệu
    if (cccdEl && soCccd && cccdEl.value !== soCccd) cccdEl.value = soCccd;
    if (sobhytEl && rawMaThe && sobhytEl.value !== rawMaThe) sobhytEl.value = rawMaThe;

    let hoTen = getRealVal('hoten') || (currentBhytCardData?.hoTen || currentHisPatient?.TEN_BENH_NHAN || currentHisPatient?.HOTEN || '').trim();
    let ngaySinh = extractTiepNhanDob();
    let mayteVal = getRealVal('mayte');

    // Khóa chống kích hoạt trùng lặp nhiều lần cho cùng một bệnh nhân (bỏ qua nếu force = true)
    const currentFormSig = `${soCccd}|${rawMaThe}|${hoTen}|${ngaySinh}|${mayteVal}`;
    if (!force && currentFormSig === lastCheckedFormSignature && (Date.now() - lastCheckedFormTime < 2500)) {
      console.log('[BHYT Extension] ⚡ Bỏ qua kích hoạt tra cứu trùng lặp trên form tiếp nhận:', currentFormSig);
      return;
    }
    lastCheckedFormSignature = currentFormSig;
    lastCheckedFormTime = Date.now();

    // Nếu form đã có CCCD hoặc Mã thẻ hoặc Mã y tế do người dùng nhập/quét:
    // Kiểm tra xem có khác với bệnh nhân chọn từ bảng trước đó không, nếu khác -> xóa bệnh nhân cũ khỏi bộ nhớ
    if (lastSelectedGridPatient && (soCccd || rawMaThe || mayteVal)) {
      const isMismatchWithGrid =
        (soCccd && lastSelectedGridPatient.soCccd && soCccd !== lastSelectedGridPatient.soCccd) ||
        (rawMaThe && lastSelectedGridPatient.maThe && rawMaThe !== lastSelectedGridPatient.maThe) ||
        (mayteVal && lastSelectedGridPatient.mayte && mayteVal !== lastSelectedGridPatient.mayte);
      if (isMismatchWithGrid) {
        console.log('[BHYT Extension] Dữ liệu form khác với bệnh nhân đã chọn trong bảng -> Hủy ngữ cảnh bệnh nhân cũ.');
        lastSelectedGridPatient = null;
        try { delete document.documentElement.dataset.selectedPatientJson; } catch (e) {}
      }
    }

    // CHỈ trích xuất bệnh nhân từ bảng nếu:
    // 1) Đang ở tab Danh sách tiếp nhận (isViewingDanhSachTab)
    // 2) HOẶC form Thông tin tiếp nhận hoàn toàn trống (chưa nhập CCCD, Thẻ, Mã BN, Họ tên)
    const isFormBlank = !soCccd && !rawMaThe && !mayteVal && !hoTen;
    if (isViewingDanhSachTab || isFormBlank) {
      const gridPatient = extractPatientFromSelectedGridRow(document);
      if (gridPatient) {
        if (!hoTen && gridPatient.hoTen) hoTen = gridPatient.hoTen;
        if (!rawMaThe && gridPatient.maThe) rawMaThe = gridPatient.maThe;
        if (!soCccd && gridPatient.soCccd) soCccd = gridPatient.soCccd;
        if (!ngaySinh && gridPatient.ngaySinh) ngaySinh = gridPatient.ngaySinh;
        if (!mayteVal && gridPatient.mayte) mayteVal = gridPatient.mayte;
        const gridSdt = gridPatient.soDienThoai || gridPatient.SO_DIEN_THOAI || '';
        if (gridSdt) {
          const elSdt = findSdtInput();
          if (elSdt && !elSdt.value) {
            setFieldSuccess(elSdt, gridSdt);
          }
        }

        // Đồng bộ thông tin lên form để hiển thị trực quan cho người dùng nếu form đang trống
        if (isFormBlank) {
          if (hoTen && document.getElementById('hoten')) document.getElementById('hoten').value = hoTen;
          if (rawMaThe && document.getElementById('sobhyt')) document.getElementById('sobhyt').value = rawMaThe;
          if (soCccd && cccdEl) {
            cccdEl.value = soCccd;
            updateCccdCounter(soCccd);
          }
          if (ngaySinh) {
            const dobEl = findDobTextInput(document);
            if (dobEl) dobEl.value = ngaySinh;
          }
          if (mayteVal && document.getElementById('mayte')) document.getElementById('mayte').value = mayteVal;
          if (gridSdt) {
            const elSdt = findSdtInput();
            if (elSdt) setFieldSuccess(elSdt, gridSdt);
          }
        }
      }
    }

    // Mã thẻ BHYT hợp lệ phải là 10 ký tự hoặc 15 ký tự
    let maThe = (rawMaThe.length === 12 && /^\d{12}$/.test(rawMaThe)) ? '' : rawMaThe;

    // Fallback thông tin nếu trên form bị khuyết nhưng cùng bệnh nhân đã kiểm tra trước đó
    if (!hoTen && currentBhytCardData?.hoTen) {
      hoTen = currentBhytCardData.hoTen;
    }
    if (!maThe && currentBhytCardData?.maThe) {
      maThe = currentBhytCardData.maThe;
    }

    // Khi đổi bệnh nhân: Cập nhật đối tượng ngữ cảnh, TUYỆT ĐỐI KHÔNG xóa sạch form của bệnh nhân mới
    const currentCmt = (currentHisPatient?.CMT_BENHNHAN || currentHisPatient?.SO_CCCD || currentHisPatient?.SOCMT || currentHisPatient?.socmt || '').replace(/\D/g, '');
    if (soCccd && currentCmt && soCccd !== currentCmt) {
      console.log('[BHYT Extension] Phát hiện CCCD mới khác với bệnh nhân cũ -> Reset ngữ cảnh tra cứu bệnh nhân cũ.');
      currentHisPatient = null;
      currentBhytCardData = null;
    }

    // 2. Nếu chưa có mã thẻ và CCCD, nhưng có Mã y tế (Mã BN): Tra cứu HIS để lấy thẻ BHYT và CCCD
    if (!maThe && !soCccd && mayteVal) {
      showBannerChecking('⏳ Đang tìm kiếm thông tin thẻ BHYT theo Mã bệnh nhân trong HIS...');
      try {
        const bnFound = await lookupPatientInHis(mayteVal);
        if (bnFound) {
          applyHisPatientToForm(bnFound);
          if (!hoTen) hoTen = (bnFound.TEN_BENH_NHAN || bnFound.tenbenhnhan || bnFound.HOTEN || '').trim();
          if (!ngaySinh) ngaySinh = (formatBhxhDate(bnFound.NGAY_SINH || bnFound.ngaysinh) || '').trim();
          maThe = (bnFound.SO_THE_BAOHIEM_YTE || bnFound.SO_THE_BHYT || bnFound.sobhyt || '').trim();
          soCccd = (bnFound.CMT_BENHNHAN || bnFound.socmt || bnFound.SO_CCCD || '').replace(/\D/g, '');
        }
      } catch (err) {}
    }

    const searchKey = soCccd || maThe || mayteVal;

    // Kiểm tra tính hợp lệ của tham số trước khi gửi Cổng BHXH
    if (!maThe && !soCccd) {
      renderErrorBanner('⚠️ Vui lòng chọn bệnh nhân trong danh sách, quét mã QR hoặc nhập Số CCCD / Mã thẻ BHYT trước khi kiểm tra.');
      if (cccdEl) cccdEl.focus();
      return;
    }

    showBannerChecking('⏳ Đang truy vấn hồ sơ bệnh nhân trong HIS và kiểm tra Cổng BHXH...');

    // Ưu tiên tìm hồ sơ trong HIS nếu thiếu họ tên hoặc ngày sinh hoặc mã thẻ
    const isNewSearch = !currentHisPatient ||
      (soCccd && (currentHisPatient.CMT_BENHNHAN || currentHisPatient.SO_CCCD || currentHisPatient.SOCMT || currentHisPatient.socmt || '').replace(/\D/g, '') !== soCccd) ||
      (maThe && (currentHisPatient.SO_THE_BAOHIEM_YTE || currentHisPatient.SO_THE_BHYT || currentHisPatient.MA_THE || '').trim().toUpperCase() !== maThe) ||
      (mayteVal && extractMaBn(currentHisPatient) !== mayteVal) ||
      (!hoTen || !ngaySinh);

    if (searchKey && isNewSearch && (!hoTen || !ngaySinh || !maThe)) {
      try {
        const bnFound = await lookupPatientInHis(searchKey);
        if (bnFound) {
          applyHisPatientToForm(bnFound);
          if (!hoTen) hoTen = (bnFound.TEN_BENH_NHAN || bnFound.tenbenhnhan || bnFound.HOTEN || '').trim();
          if (!ngaySinh) ngaySinh = (formatBhxhDate(bnFound.NGAY_SINH || bnFound.ngaysinh) || '').trim();
          if (!maThe) {
            maThe = (bnFound.SO_THE_BAOHIEM_YTE || bnFound.SO_THE_BHYT || bnFound.sobhyt || '').trim();
          }
          if (!soCccd) {
            soCccd = (bnFound.CMT_BENHNHAN || bnFound.socmt || bnFound.SO_CCCD || '').replace(/\D/g, '');
          }
        }
      } catch (e) {
        console.log('[BHYT Extension] Lỗi tra cứu HIS:', e);
      }
    }

    // Nếu sau khi tìm HIS vẫn thiếu ngày sinh, nạp lại từ hàm trích xuất đa tầng
    if (!ngaySinh) {
      ngaySinh = extractTiepNhanDob();
    }

    // Nếu có ngày sinh nhưng ô text trên form bị rỗng, phục hồi lại vào form
    if (ngaySinh) {
      const dobEl = findDobTextInput(document);
      if (dobEl && !dobEl.value) {
        setFieldSuccess(dobEl, ngaySinh);
      }
    }

    // Nếu vẫn chưa có Họ tên và Mã thẻ BHYT
    if (!hoTen && !maThe) {
      renderErrorBanner('⚠️ Bệnh nhân mới chưa có thông tin trong HIS. Vui lòng nhập Họ tên và Ngày sinh (hoặc quét mã QR trên CCCD) để thực hiện Kiểm tra BHYT.');
      const hotenEl = document.getElementById('hoten');
      if (hotenEl) hotenEl.focus();
      return;
    }

    // Gửi yêu cầu lên Cổng BHXH thực tế
    executeBhytCheck(soCccd, hoTen, ngaySinh, maThe);
  }

  // =========================================================================
  // 5. BÓC TÁCH ĐỊA CHỈ & GÁN ĐỊA CHỈ (CV30) THEO DANH MỤC HÀNH CHÍNH NSO / TT30 (*)
